insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('258b133b-e7e9-542f-938c-65d0a13711db', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '237', '‏ ‏و حَدَّثَنِي ‏ ‏حَرْمَلَةُ بْنُ يَحْيَى التُّجِيبِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَبُو ذَرٍّ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فُرِجَ سَقْفُ بَيْتِي وَأَنَا ‏ ‏بِمَكَّةَ ‏ ‏فَنَزَلَ ‏ ‏جِبْرِيلُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَفَرَجَ صَدْرِي ثُمَّ غَسَلَهُ مِنْ مَاءِ ‏ ‏زَمْزَمَ ‏ ‏ثُمَّ جَاءَ بِطَسْتٍ مِنْ ذَهَبٍ مُمْتَلِئٍ حِكْمَةً وَإِيمَانًا فَأَفْرَغَهَا فِي صَدْرِي ثُمَّ أَطْبَقَهُ ثُمَّ أَخَذَ بِيَدِي فَعَرَجَ بِي إِلَى السَّمَاءِ فَلَمَّا جِئْنَا السَّمَاءَ الدُّنْيَا قَالَ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏لِخَازِنِ السَّمَاءِ الدُّنْيَا افْتَحْ قَالَ مَنْ هَذَا قَالَ هَذَا ‏ ‏جِبْرِيلُ ‏ ‏قَالَ هَلْ مَعَكَ أَحَدٌ قَالَ نَعَمْ ‏ ‏مَعِيَ ‏ ‏مُحَمَّدٌ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَأُرْسِلَ إِلَيْهِ قَالَ نَعَمْ فَفَتَحَ قَالَ فَلَمَّا عَلَوْنَا السَّمَاءَ الدُّنْيَا فَإِذَا رَجُلٌ عَنْ يَمِينِهِ أَسْوِدَةٌ وَعَنْ يَسَارِهِ أَسْوِدَةٌ قَالَ فَإِذَا نَظَرَ قِبَلَ يَمِينِهِ ضَحِكَ وَإِذَا نَظَرَ قِبَلَ شِمَالِهِ بَكَى قَالَ فَقَالَ مَرْحَبًا بِالنَّبِيِّ الصَّالِحِ ‏ ‏وَالِابْنِ الصَّالِحِ قَالَ قُلْتُ يَا ‏ ‏جِبْرِيلُ ‏ ‏مَنْ هَذَا قَالَ هَذَا ‏ ‏آدَمُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهَذِهِ الْأَسْوِدَةُ عَنْ يَمِينِهِ وَعَنْ شِمَالِهِ نَسَمُ بَنِيهِ فَأَهْلُ الْيَمِينِ أَهْلُ الْجَنَّةِ وَالْأَسْوِدَةُ الَّتِي عَنْ شِمَالِهِ أَهْلُ النَّارِ فَإِذَا نَظَرَ قِبَلَ يَمِينِهِ ضَحِكَ وَإِذَا نَظَرَ قِبَلَ شِمَالِهِ بَكَى قَالَ ثُمَّ عَرَجَ بِي ‏ ‏جِبْرِيلُ ‏ ‏حَتَّى أَتَى السَّمَاءَ الثَّانِيَةَ فَقَالَ لِخَازِنِهَا افْتَحْ قَالَ فَقَالَ لَهُ خَازِنُهَا مِثْلَ مَا قَالَ خَازِنُ السَّمَاءِ الدُّنْيَا فَفَتَحَ ‏ ‏فَقَالَ ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏فَذَكَرَ أَنَّهُ وَجَدَ فِي السَّمَاوَاتِ ‏ ‏آدَمَ ‏ ‏وَإِدْرِيسَ ‏ ‏وَعِيسَى ‏ ‏وَمُوسَى ‏ ‏وَإِبْرَاهِيمَ ‏ ‏صَلَوَاتُ اللَّهِ عَلَيْهِمْ ‏ ‏أَجْمَعِينَ وَلَمْ يُثْبِتْ كَيْفَ مَنَازِلُهُمْ غَيْرَ أَنَّهُ ذَكَرَ أَنَّهُ قَدْ وَجَدَ ‏ ‏آدَمَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فِي السَّمَاءِ الدُّنْيَا ‏ ‏وَإِبْرَاهِيمَ ‏ ‏فِي السَّمَاءِ السَّادِسَةِ قَالَ فَلَمَّا مَرَّ ‏ ‏جِبْرِيلُ ‏ ‏وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِإِدْرِيسَ ‏ ‏صَلَوَاتُ اللَّهِ عَلَيْهِ ‏ ‏قَالَ مَرْحَبًا بِالنَّبِيِّ الصَّالِحِ وَالْأَخِ الصَّالِحِ قَالَ ثُمَّ مَرَّ فَقُلْتُ مَنْ هَذَا فَقَالَ هَذَا ‏ ‏إِدْرِيسُ ‏ ‏قَالَ ثُمَّ مَرَرْتُ ‏ ‏بِمُوسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَقَالَ مَرْحَبًا بِالنَّبِيِّ الصَّالِحِ وَالْأَخِ الصَّالِحِ قَالَ قُلْتُ مَنْ هَذَا قَالَ هَذَا ‏ ‏مُوسَى ‏ ‏قَالَ ثُمَّ مَرَرْتُ ‏ ‏بِعِيسَى ‏ ‏فَقَالَ مَرْحَبًا بِالنَّبِيِّ الصَّالِحِ وَالْأَخِ الصَّالِحِ قُلْتُ مَنْ هَذَا قَالَ هَذَا ‏ ‏عِيسَى ابْنُ مَرْيَمَ ‏ ‏قَالَ ثُمَّ مَرَرْتُ ‏ ‏بِإِبْرَاهِيمَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَقَالَ مَرْحَبًا بِالنَّبِيِّ الصَّالِحِ ‏ ‏وَالِابْنِ الصَّالِحِ قَالَ قُلْتُ مَنْ هَذَا قَالَ هَذَا ‏ ‏إِبْرَاهِيمُ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏وَأَخْبَرَنِي ‏ ‏ابْنُ حَزْمٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏وَأَبَا حَبَّةَ الْأَنْصَارِيَّ ‏ ‏كَانَا يَقُولَانِ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ عَرَجَ بِي حَتَّى ظَهَرْتُ لِمُسْتَوًى أَسْمَعُ فِيهِ صَرِيفَ الْأَقْلَامِ ‏ ‏قَالَ ‏ ‏ابْنُ حَزْمٍ ‏ ‏وَأَنَسُ بْنُ مَالِكٍ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَفَرَضَ اللَّهُ عَلَى أُمَّتِي خَمْسِينَ صَلَاةً قَالَ فَرَجَعْتُ بِذَلِكَ حَتَّى أَمُرَّ ‏ ‏بِمُوسَى ‏ ‏فَقَالَ ‏ ‏مُوسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏مَاذَا فَرَضَ رَبُّكَ عَلَى أُمَّتِكَ قَالَ قُلْتُ فَرَضَ عَلَيْهِمْ خَمْسِينَ صَلَاةً قَالَ لِي ‏ ‏مُوسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَرَاجِعْ رَبَّكَ فَإِنَّ أُمَّتَكَ لَا تُطِيقُ ذَلِكَ قَالَ فَرَاجَعْتُ رَبِّي فَوَضَعَ ‏ ‏شَطْرَهَا ‏ ‏قَالَ فَرَجَعْتُ إِلَى ‏ ‏مُوسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَأَخْبَرْتُهُ قَالَ رَاجِعْ رَبَّكَ فَإِنَّ أُمَّتَكَ لَا تُطِيقُ ذَلِكَ قَالَ فَرَاجَعْتُ رَبِّي فَقَالَ هِيَ خَمْسٌ وَهِيَ خَمْسُونَ لَا ‏ ‏يُبَدَّلُ ‏ ‏الْقَوْلُ لَدَيَّ قَالَ فَرَجَعْتُ إِلَى ‏ ‏مُوسَى ‏ ‏فَقَالَ رَاجِعْ رَبَّكَ فَقُلْتُ قَدْ اسْتَحْيَيْتُ مِنْ رَبِّي قَالَ ثُمَّ انْطَلَقَ بِي ‏ ‏جِبْرِيلُ ‏ ‏حَتَّى نَأْتِيَ سِدْرَةَ الْمُنْتَهَى فَغَشِيَهَا أَلْوَانٌ لَا أَدْرِي مَا هِيَ قَالَ ثُمَّ أُدْخِلْتُ الْجَنَّةَ فَإِذَا فِيهَا ‏ ‏جَنَابِذُ ‏ ‏اللُّؤْلُؤَ وَإِذَا تُرَابُهَا الْمِسْكُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('62c33c78-1fa9-5edb-afa2-8387810c6d82', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '238', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏لَعَلَّهُ قَالَ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ صَعْصَعَةَ ‏ ‏رَجُلٍ مِنْ قَوْمِهِ ‏ ‏قَالَ ‏ ‏قَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَا أَنَا عِنْدَ ‏ ‏الْبَيْتِ ‏ ‏بَيْنَ النَّائِمِ وَالْيَقْظَانِ إِذْ سَمِعْتُ قَائِلًا يَقُولُ أَحَدُ الثَّلَاثَةِ بَيْنَ الرَّجُلَيْنِ فَأُتِيتُ فَانْطُلِقَ بِي فَأُتِيتُ بِطَسْتٍ مِنْ ذَهَبٍ فِيهَا مِنْ مَاءِ ‏ ‏زَمْزَمَ ‏ ‏فَشُرِحَ ‏ ‏صَدْرِي إِلَى كَذَا وَكَذَا قَالَ ‏ ‏قَتَادَةُ ‏ ‏فَقُلْتُ لِلَّذِي مَعِي مَا ‏ ‏يَعْنِي قَالَ إِلَى أَسْفَلِ بَطْنِهِ فَاسْتُخْرِجَ قَلْبِي فَغُسِلَ بِمَاءِ ‏ ‏زَمْزَمَ ‏ ‏ثُمَّ أُعِيدَ مَكَانَهُ ثُمَّ حُشِيَ إِيمَانًا وَحِكْمَةً ثُمَّ أُتِيتُ بِدَابَّةٍ أَبْيَضَ يُقَالُ لَهُ ‏ ‏الْبُرَاقُ ‏ ‏فَوْقَ الْحِمَارِ وَدُونَ الْبَغْلِ يَقَعُ خَطْوُهُ عِنْدَ أَقْصَى طَرْفِهِ فَحُمِلْتُ عَلَيْهِ ثُمَّ انْطَلَقْنَا حَتَّى أَتَيْنَا السَّمَاءَ الدُّنْيَا فَاسْتَفْتَحَ ‏ ‏جِبْرِيلُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقِيلَ مَنْ هَذَا قَالَ ‏ ‏جِبْرِيلُ ‏ ‏قِيلَ وَمَنْ مَعَكَ قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قِيلَ وَقَدْ بُعِثَ إِلَيْهِ قَالَ نَعَمْ قَالَ فَفَتَحَ لَنَا وَقَالَ مَرْحَبًا بِهِ وَلَنِعْمَ الْمَجِيءُ جَاءَ قَالَ فَأَتَيْنَا عَلَى ‏ ‏آدَمَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَسَاقَ الْحَدِيثَ بِقِصَّتِهِ وَذَكَرَ أَنَّهُ لَقِيَ فِي السَّمَاءِ الثَّانِيَةِ ‏ ‏عِيسَى ‏ ‏وَيَحْيَى ‏ ‏عَلَيْهَا السَّلَام ‏ ‏وَفِي الثَّالِثَةِ ‏ ‏يُوسُفَ ‏ ‏وَفِي الرَّابِعَةِ ‏ ‏إِدْرِيسَ ‏ ‏وَفِي الْخَامِسَةِ ‏ ‏هَارُونَ ‏ ‏صَلَوَاتُ اللَّهِ عَلَيْهِمْ ‏ ‏قَالَ ثُمَّ انْطَلَقْنَا حَتَّى انْتَهَيْنَا إِلَى السَّمَاءِ السَّادِسَةِ فَأَتَيْتُ عَلَى ‏ ‏مُوسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَسَلَّمْتُ عَلَيْهِ فَقَالَ مَرْحَبًا بِالْأَخِ الصَّالِحِ وَالنَّبِيِّ الصَّالِحِ فَلَمَّا جَاوَزْتُهُ بَكَى فَنُودِيَ مَا يُبْكِيكَ قَالَ رَبِّ هَذَا غُلَامٌ بَعَثْتَهُ بَعْدِي يَدْخُلُ مِنْ أُمَّتِهِ الْجَنَّةَ أَكْثَرُ مِمَّا يَدْخُلُ مِنْ أُمَّتِي قَالَ ثُمَّ انْطَلَقْنَا حَتَّى انْتَهَيْنَا إِلَى السَّمَاءِ السَّابِعَةِ فَأَتَيْتُ عَلَى ‏ ‏إِبْرَاهِيمَ ‏ ‏وَقَالَ فِي الْحَدِيثِ وَحَدَّثَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ رَأَى أَرْبَعَةَ أَنْهَارٍ يَخْرُجُ مِنْ أَصْلِهَا نَهْرَانِ ظَاهِرَانِ وَنَهْرَانِ بَاطِنَانِ فَقُلْتُ يَا ‏ ‏جِبْرِيلُ ‏ ‏مَا هَذِهِ الْأَنْهَارُ قَالَ أَمَّا النَّهْرَانِ الْبَاطِنَانِ فَنَهْرَانِ فِي الْجَنَّةِ وَأَمَّا الظَّاهِرَانِ فَالنِّيلُ وَالْفُرَاتُ ثُمَّ رُفِعَ لِي ‏ ‏الْبَيْتُ الْمَعْمُورُ ‏ ‏فَقُلْتُ يَا ‏ ‏جِبْرِيلُ ‏ ‏مَا هَذَا قَالَ هَذَا ‏ ‏الْبَيْتُ الْمَعْمُورُ ‏ ‏يَدْخُلُهُ كُلَّ يَوْمٍ سَبْعُونَ أَلْفَ مَلَكٍ إِذَا خَرَجُوا مِنْهُ لَمْ يَعُودُوا فِيهِ آخِرُ مَا عَلَيْهِمْ ثُمَّ أُتِيتُ بِإِنَاءَيْنِ أَحَدُهُمَا خَمْرٌ وَالْآخَرُ لَبَنٌ فَعُرِضَا عَلَيَّ فَاخْتَرْتُ اللَّبَنَ فَقِيلَ أَصَبْتَ أَصَابَ اللَّهُ بِكَ أُمَّتُكَ عَلَى الْفِطْرَةِ ثُمَّ فُرِضَتْ عَلَيَّ كُلَّ يَوْمٍ خَمْسُونَ صَلَاةً ثُمَّ ذَكَرَ قِصَّتَهَا إِلَى آخِرِ الْحَدِيثِ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ صَعْصَعَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَذَكَرَ نَحْوَهُ وَزَادَ فِيهِ فَأُتِيتُ ‏ ‏بِطَسْتٍ ‏ ‏مِنْ ذَهَبٍ مُمْتَلِئٍ حِكْمَةً وَإِيمَانًا فَشُقَّ مِنْ ‏ ‏النَّحْرِ ‏ ‏إِلَى ‏ ‏مَرَاقِّ ‏ ‏الْبَطْنِ فَغُسِلَ بِمَاءِ ‏ ‏زَمْزَمَ ‏ ‏ثُمَّ مُلِئَ حِكْمَةً وَإِيمَانًا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
