insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e43e5da4-cb8c-5a41-b5a7-7fa24097a0fb', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '240', '‏ ‏و حَدَّثَنَا ‏ ‏عَبْدُ بْنُ حُمَيْدٍ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَمِّ نَبِيِّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَرْتُ لَيْلَةَ ‏ ‏أُسْرِيَ ‏ ‏بِي عَلَى ‏ ‏مُوسَى بْنِ عِمْرَانَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏رَجُلٌ ‏ ‏آدَمُ ‏ ‏طُوَالٌ ‏ ‏جَعْدٌ ‏ ‏كَأَنَّهُ مِنْ رِجَالِ شَنُوءَةَ وَرَأَيْتُ ‏ ‏عِيسَى ابْنَ مَرْيَمَ ‏ ‏مَرْبُوعَ ‏ ‏الْخَلْقِ إِلَى الْحُمْرَةِ وَالْبَيَاضِ ‏ ‏سَبِطَ ‏ ‏الرَّأْسِ وَأُرِيَ ‏ ‏مَالِكًا ‏ ‏خَازِنَ النَّارِ ‏ ‏وَالدَّجَّالَ ‏ ‏فِي آيَاتٍ أَرَاهُنَّ اللَّهُ إِيَّاهُ ‏ { ‏فَلَا تَكُنْ فِي ‏ ‏مِرْيَةٍ ‏ ‏مِنْ لِقَائِهِ ‏} ‏قَالَ ‏ ‏كَانَ ‏ ‏قَتَادَةُ ‏ ‏يُفَسِّرُهَا أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ لَقِيَ ‏ ‏مُوسَى ‏ ‏عَلَيْهِ السَّلَام ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a9fd97b7-261b-5d21-989a-1cad1290cd00', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '241', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ حَنْبَلٍ ‏ ‏وَسُرَيْجُ بْنُ يُونُسَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏دَاوُدُ بْنُ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ ‏ ‏بِوَادِي الْأَزْرَقِ ‏ ‏فَقَالَ ‏ ‏أَيُّ وَادٍ هَذَا فَقَالُوا هَذَا ‏ ‏وَادِي الْأَزْرَقِ ‏ ‏قَالَ كَأَنِّي أَنْظُرُ إِلَى ‏ ‏مُوسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏هَابِطًا مِنْ ‏ ‏الثَّنِيَّةِ ‏ ‏وَلَهُ ‏ ‏جُؤَارٌ ‏ ‏إِلَى اللَّهِ بِالتَّلْبِيَةِ ثُمَّ أَتَى عَلَى ‏ ‏ثَنِيَّةِ هَرْشَى ‏ ‏فَقَالَ أَيُّ ‏ ‏ثَنِيَّةٍ ‏ ‏هَذِهِ قَالُوا ‏ ‏ثَنِيَّةُ هَرْشَى ‏ ‏قَالَ كَأَنِّي أَنْظُرُ إِلَى ‏ ‏يُونُسَ بْنِ مَتَّى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏عَلَى نَاقَةٍ حَمْرَاءَ ‏ ‏جَعْدَةٍ ‏ ‏عَلَيْهِ جُبَّةٌ مِنْ صُوفٍ ‏ ‏خِطَامُ ‏ ‏نَاقَتِهِ ‏ ‏خُلْبَةٌ ‏ ‏وَهُوَ يُلَبِّي ‏ ‏قَالَ ‏ ‏ابْنُ حَنْبَلٍ ‏ ‏فِي حَدِيثِهِ قَالَ ‏ ‏هُشَيْمٌ ‏ ‏يَعْنِي لِيفًا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('30107c4d-579f-5492-a28a-d4e8bc120a68', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '242', '‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏سِرْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ ‏ ‏مَكَّةَ ‏ ‏وَالْمَدِينَةِ ‏ ‏فَمَرَرْنَا بِوَادٍ فَقَالَ ‏ ‏أَيُّ وَادٍ هَذَا فَقَالُوا ‏ ‏وَادِي الْأَزْرَقِ ‏ ‏فَقَالَ كَأَنِّي أَنْظُرُ إِلَى ‏ ‏مُوسَى ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِنْ لَوْنِهِ وَشَعَرِهِ شَيْئًا لَمْ يَحْفَظْهُ ‏ ‏دَاوُدُ ‏ ‏وَاضِعًا إِصْبَعَيْهِ فِي أُذُنَيْهِ لَهُ ‏ ‏جُؤَارٌ ‏ ‏إِلَى اللَّهِ بِالتَّلْبِيَةِ مَارًّا بِهَذَا الْوَادِي قَالَ ثُمَّ سِرْنَا حَتَّى أَتَيْنَا عَلَى ثَنِيَّةٍ فَقَالَ أَيُّ ثَنِيَّةٍ هَذِهِ قَالُوا ‏ ‏هَرْشَى ‏ ‏أَوْ ‏ ‏لِفْتٌ ‏ ‏فَقَالَ كَأَنِّي أَنْظُرُ إِلَى ‏ ‏يُونُسَ ‏ ‏عَلَى نَاقَةٍ حَمْرَاءَ عَلَيْهِ جُبَّةُ صُوفٍ ‏ ‏خِطَامُ ‏ ‏نَاقَتِهِ لِيفٌ ‏ ‏خُلْبَةٌ ‏ ‏مَارًّا بِهَذَا الْوَادِي مُلَبِّيًا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3df3176a-ce34-56ed-abb1-fa625223b724', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '243', '‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏ابْنِ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فَذَكَرُوا ‏ ‏الدَّجَّالَ ‏ ‏فَقَالَ إِنَّهُ مَكْتُوبٌ بَيْنَ عَيْنَيْهِ كَافِرٌ قَالَ فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏لَمْ أَسْمَعْهُ قَالَ ذَاكَ وَلَكِنَّهُ قَالَ ‏ ‏أَمَّا ‏ ‏إِبْرَاهِيمُ ‏ ‏فَانْظُرُوا إِلَى صَاحِبِكُمْ وَأَمَّا ‏ ‏مُوسَى ‏ ‏فَرَجُلٌ آدَمُ ‏ ‏جَعْدٌ ‏ ‏عَلَى جَمَلٍ أَحْمَرَ ‏ ‏مَخْطُومٍ ‏ ‏بِخُلْبَةٍ ‏ ‏كَأَنِّي أَنْظُرُ إِلَيْهِ إِذَا انْحَدَرَ فِي الْوَادِي يُلَبِّي ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6458a2f3-3bb6-5812-acc7-ad2211c82267', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '244', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رُمْحٍ ‏ ‏أَخْبَرَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عُرِضَ عَلَيَّ الْأَنْبِيَاءُ فَإِذَا ‏ ‏مُوسَى ‏ ‏ضَرْبٌ مِنْ الرِّجَالِ كَأَنَّهُ مِنْ رِجَالِ شَنُوءَةَ وَرَأَيْتُ ‏ ‏عِيسَى ابْنَ مَرْيَمَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَإِذَا أَقْرَبُ مَنْ رَأَيْتُ بِهِ شَبَهًا ‏ ‏عُرْوَةُ بْنُ مَسْعُودٍ ‏ ‏وَرَأَيْتُ ‏ ‏إِبْرَاهِيمَ ‏ ‏صَلَوَاتُ اللَّهِ عَلَيْهِ ‏ ‏فَإِذَا أَقْرَبُ مَنْ رَأَيْتُ بِهِ شَبَهًا صَاحِبُكُمْ ‏ ‏يَعْنِي نَفْسَهُ وَرَأَيْتُ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَإِذَا أَقْرَبُ مَنْ رَأَيْتُ بِهِ شَبَهًا ‏ ‏دَحْيَةُ ‏ ‏وَفِي رِوَايَةِ ‏ ‏ابْنِ رُمْحٍ ‏ ‏دَحْيَةُ بْنُ خَلِيفَةَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('81d55050-2744-5692-9899-444bf4731400', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '245', '‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏وَعَبْدُ بْنُ حُمَيْدٍ ‏ ‏وَتَقَارَبَا فِي اللَّفْظِ ‏ ‏قَالَ ‏ ‏ابْنُ رَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏وَقَالَ ‏ ‏عَبْدٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سَعِيدُ بْنُ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ ‏ ‏أُسْرِيَ ‏ ‏بِي ‏ ‏لَقِيتُ ‏ ‏مُوسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَنَعَتَهُ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِذَا رَجُلٌ حَسِبْتُهُ قَالَ مُضْطَرِبٌ ‏ ‏رَجِلُ الرَّأْسِ ‏ ‏كَأَنَّهُ مِنْ رِجَالِ شَنُوءَةَ قَالَ وَلَقِيتُ ‏ ‏عِيسَى ‏ ‏فَنَعَتَهُ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِذَا ‏ ‏رَبْعَةٌ ‏ ‏أَحْمَرُ كَأَنَّمَا خَرَجَ مِنْ ‏ ‏دِيمَاسٍ ‏ ‏يَعْنِي حَمَّامًا قَالَ ‏ ‏وَرَأَيْتُ ‏ ‏إِبْرَاهِيمَ ‏ ‏صَلَوَاتُ اللَّهِ عَلَيْهِ ‏ ‏وَأَنَا أَشْبَهُ وَلَدِهِ بِهِ قَالَ فَأُتِيتُ بِإِنَاءَيْنِ فِي أَحَدِهِمَا لَبَنٌ وَفِي الْآخَرِ خَمْرٌ فَقِيلَ لِي خُذْ أَيَّهُمَا شِئْتَ فَأَخَذْتُ اللَّبَنَ فَشَرِبْتُهُ فَقَالَ هُدِيتَ الْفِطْرَةَ ‏ ‏أَوْ أَصَبْتَ الْفِطْرَةَ ‏ ‏أَمَّا إِنَّكَ لَوْ أَخَذْتَ الْخَمْرَ ‏ ‏غَوَتْ ‏ ‏أُمَّتُكَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d82d75b9-6040-5e6b-8770-7392dddf129e', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '246', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏قَالَ قَرَأْتُ عَلَى ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَرَانِي لَيْلَةً عِنْدَ ‏ ‏الْكَعْبَةِ ‏ ‏فَرَأَيْتُ رَجُلًا ‏ ‏آدَمَ ‏ ‏كَأَحْسَنِ مَا أَنْتَ رَاءٍ مِنْ أُدْمِ الرِّجَالِ لَهُ ‏ ‏لِمَّةٌ ‏ ‏كَأَحْسَنِ مَا أَنْتَ رَاءٍ مِنْ اللِّمَمِ قَدْ ‏ ‏رَجَّلَهَا ‏ ‏فَهِيَ تَقْطُرُ مَاءً مُتَّكِئًا عَلَى رَجُلَيْنِ أَوْ عَلَى ‏ ‏عَوَاتِقِ ‏ ‏رَجُلَيْنِ يَطُوفُ ‏ ‏بِالْبَيْتِ ‏ ‏فَسَأَلْتُ مَنْ هَذَا فَقِيلَ هَذَا ‏ ‏الْمَسِيحُ ابْنُ مَرْيَمَ ‏ ‏ثُمَّ إِذَا أَنَا بِرَجُلٍ ‏ ‏جَعْدٍ ‏ ‏قَطَطٍ ‏ ‏أَعْوَرِ الْعَيْنِ الْيُمْنَى كَأَنَّهَا عِنَبَةٌ ‏ ‏طَافِيَةٌ ‏ ‏فَسَأَلْتُ مَنْ هَذَا فَقِيلَ هَذَا ‏ ‏الْمَسِيحُ الدَّجَّالُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2e67a4f4-a956-5131-9a0c-5bb94d49f1bb', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '247', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَقَ الْمُسَيَّبِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسٌ يَعْنِي ابْنَ عِيَاضٍ ‏ ‏عَنْ ‏ ‏مُوسَى وَهُوَ ابْنُ عُقْبَةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏ذَكَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا بَيْنَ ظَهْرَانَيْ النَّاسِ ‏ ‏الْمَسِيحَ الدَّجَّالَ ‏ ‏فَقَالَ ‏ ‏إِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى لَيْسَ بِأَعْوَرَ أَلَا إِنَّ ‏ ‏الْمَسِيحَ الدَّجَّالَ ‏ ‏أَعْوَرُ عَيْنِ الْيُمْنَى كَأَنَّ عَيْنَهُ عِنَبَةٌ ‏ ‏طَافِيَةٌ ‏ ‏قَالَ وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرَانِي اللَّيْلَةَ فِي الْمَنَامِ عِنْدَ ‏ ‏الْكَعْبَةِ ‏ ‏فَإِذَا رَجُلٌ آدَمُ كَأَحْسَنِ مَا ‏ ‏تَرَى مِنْ أُدْمِ الرِّجَالِ تَضْرِبُ لِمَّتُهُ بَيْنَ مَنْكِبَيْهِ رَجِلُ الشَّعْرِ يَقْطُرُ رَأْسُهُ مَاءً وَاضِعًا يَدَيْهِ عَلَى مَنْكِبَيْ رَجُلَيْنِ وَهُوَ بَيْنَهُمَا يَطُوفُ ‏ ‏بِالْبَيْتِ ‏ ‏فَقُلْتُ مَنْ هَذَا فَقَالُوا ‏ ‏الْمَسِيحُ ابْنُ مَرْيَمَ ‏ ‏وَرَأَيْتُ وَرَاءَهُ رَجُلًا جَعْدًا قَطَطًا أَعْوَرَ عَيْنِ الْيُمْنَى كَأَشْبَهِ مَنْ رَأَيْتُ مِنْ النَّاسِ ‏ ‏بِابْنِ قَطَنٍ ‏ ‏وَاضِعًا يَدَيْهِ عَلَى مَنْكِبَيْ رَجُلَيْنِ يَطُوفُ ‏ ‏بِالْبَيْتِ ‏ ‏فَقُلْتُ مَنْ هَذَا قَالُوا هَذَا ‏ ‏الْمَسِيحُ الدَّجَّالُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
