insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ffbb51a0-4eee-536c-a4f0-a1220423b4c7', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '250', '‏ ‏حَدَّثَنِي ‏ ‏حَرْمَلَةُ بْنُ يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏يُونُسُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ بْنِ الْخَطَّابِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏بَيْنَمَا أَنَا نَائِمٌ رَأَيْتُنِي أَطُوفُ ‏ ‏بِالْكَعْبَةِ ‏ ‏فَإِذَا رَجُلٌ ‏ ‏آدَمُ ‏ ‏سَبِطُ ‏ ‏الشَّعْرِ بَيْنَ رَجُلَيْنِ ‏ ‏يَنْطِفُ ‏ ‏رَأْسُهُ مَاءً ‏ ‏أَوْ ‏ ‏يُهَرَاقُ رَأْسُهُ مَاءً ‏ ‏قُلْتُ مَنْ هَذَا قَالُوا هَذَا ‏ ‏ابْنُ مَرْيَمَ ‏ ‏ثُمَّ ذَهَبْتُ أَلْتَفِتُ فَإِذَا رَجُلٌ أَحْمَرُ جَسِيمٌ ‏ ‏جَعْدُ ‏ ‏الرَّأْسِ أَعْوَرُ الْعَيْنِ كَأَنَّ عَيْنَهُ عِنَبَةٌ ‏ ‏طَافِيَةٌ ‏ ‏قُلْتُ مَنْ هَذَا قَالُوا ‏ ‏الدَّجَّالُ ‏ ‏أَقْرَبُ النَّاسِ بِهِ شَبَهًا ‏ ‏ابْنُ قَطَنٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('03869d84-4d37-5cc1-b576-0c68bf612d9a', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '251', '‏ ‏و حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ وَهُوَ ابْنُ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْفَضْلِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَدْ رَأَيْتُنِي فِي ‏ ‏الْحِجْرِ ‏ ‏وَقُرَيْشٌ ‏ ‏تَسْأَلُنِي عَنْ ‏ ‏مَسْرَايَ ‏ ‏فَسَأَلَتْنِي عَنْ أَشْيَاءَ مِنْ ‏ ‏بَيْتِ الْمَقْدِسِ ‏ ‏لَمْ ‏ ‏أُثْبِتْهَا ‏ ‏فَكُرِبْتُ ‏ ‏كُرْبَةً ‏ ‏مَا كُرِبْتُ مِثْلَهُ قَطُّ قَالَ فَرَفَعَهُ اللَّهُ لِي أَنْظُرُ إِلَيْهِ مَا يَسْأَلُونِي عَنْ شَيْءٍ إِلَّا أَنْبَأْتُهُمْ بِهِ وَقَدْ رَأَيْتُنِي فِي جَمَاعَةٍ مِنْ الْأَنْبِيَاءِ فَإِذَا ‏ ‏مُوسَى ‏ ‏قَائِمٌ ‏ ‏يُصَلِّي فَإِذَا رَجُلٌ ضَرْبٌ ‏ ‏جَعْدٌ ‏ ‏كَأَنَّهُ مِنْ رِجَالِ شَنُوءَةَ وَإِذَا ‏ ‏عِيسَى ابْنُ مَرْيَمَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏قَائِمٌ ‏ ‏يُصَلِّي أَقْرَبُ النَّاسِ بِهِ شَبَهًا ‏ ‏عُرْوَةُ بْنُ مَسْعُودٍ الثَّقَفِيُّ ‏ ‏وَإِذَا ‏ ‏إِبْرَاهِيمُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏قَائِمٌ ‏ ‏يُصَلِّي أَشْبَهُ النَّاسِ بِهِ صَاحِبُكُمْ ‏ ‏يَعْنِي نَفْسَهُ فَحَانَتْ الصَّلَاةُ فَأَمَمْتُهُمْ فَلَمَّا فَرَغْتُ مِنْ الصَّلَاةِ قَالَ قَائِلٌ يَا ‏ ‏مُحَمَّدُ ‏ ‏هَذَا ‏ ‏مَالِكٌ ‏ ‏صَاحِبُ النَّارِ فَسَلِّمْ عَلَيْهِ فَالْتَفَتُّ إِلَيْهِ فَبَدَأَنِي بِالسَّلَامِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4a7aac01-0f83-54f4-9e84-61cc6128473d', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '252', '‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ مِغْوَلٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏وَزُهَيْرُ بْنُ حَرْبٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ نُمَيْرٍ ‏ ‏وَأَلْفَاظُهُمْ مُتَقَارِبَةٌ ‏ ‏قَالَ ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ مِغْوَلٍ ‏ ‏عَنْ ‏ ‏الزُّبَيْرِ بْنِ عَدِيٍّ ‏ ‏عَنْ ‏ ‏طَلْحَةَ ‏ ‏عَنْ ‏ ‏مُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَمَّا أُسْرِيَ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْتُهِيَ بِهِ إِلَى سِدْرَةِ الْمُنْتَهَى وَهِيَ فِي السَّمَاءِ السَّادِسَةِ إِلَيْهَا يَنْتَهِي مَا ‏ ‏يُعْرَجُ ‏ ‏بِهِ مِنْ الْأَرْضِ فَيُقْبَضُ مِنْهَا وَإِلَيْهَا يَنْتَهِي مَا يُهْبَطُ بِهِ مِنْ فَوْقِهَا فَيُقْبَضُ مِنْهَا قَالَ ‏ { ‏إِذْ ‏ ‏يَغْشَى السِّدْرَةَ مَا ‏ ‏يَغْشَى ‏} ‏قَالَ فَرَاشٌ مِنْ ذَهَبٍ قَالَ فَأُعْطِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثًا أُعْطِيَ الصَّلَوَاتِ الْخَمْسَ وَأُعْطِيَ خَوَاتِيمَ سُورَةِ ‏ ‏الْبَقَرَةِ ‏ ‏وَغُفِرَ لِمَنْ لَمْ يُشْرِكْ بِاللَّهِ مِنْ أُمَّتِهِ شَيْئًا ‏ ‏الْمُقْحِمَاتُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6e8874b5-583c-5c6f-bea7-c24bf7fc215e', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '253', '‏ ‏و حَدَّثَنِي ‏ ‏أَبُو الرَّبِيعِ الزَّهْرَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادٌ وَهُوَ ابْنُ الْعَوَّامِ ‏ ‏حَدَّثَنَا ‏ ‏الشَّيْبَانِيُّ ‏ ‏قَالَ سَأَلْتُ ‏ ‏زِرَّ بْنَ حُبَيْشٍ ‏ ‏عَنْ قَوْلِ اللَّهِ عَزَّ وَجَلَّ ‏ { ‏فَكَانَ قَابَ قَوْسَيْنِ أَوْ أَدْنَى ‏} ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ مَسْعُودٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى ‏ ‏جِبْرِيلَ ‏ ‏لَهُ سِتُّ مِائَةِ جَنَاحٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('56dbccf1-8d7e-57d0-a66e-592f29401cdd', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '254', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ غِيَاثٍ ‏ ‏عَنْ ‏ ‏الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ { ‏مَا كَذَبَ الْفُؤَادُ مَا رَأَى ‏} ‏قَالَ ‏ ‏رَأَى ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏لَهُ سِتُّ مِائَةِ جَنَاحٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('656aa0be-84d1-5f46-b7e9-d8de14b946dc', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '255', '‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ الْعَنْبَرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ الشَّيْبَانِيِّ ‏ ‏سَمِعَ ‏ ‏زِرَّ بْنَ حُبَيْشٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ { ‏لَقَدْ رَأَى مِنْ آيَاتِ رَبِّهِ الْكُبْرَى ‏} ‏قَالَ ‏ ‏رَأَى ‏ ‏جِبْرِيلَ ‏ ‏فِي صُورَتِهِ لَهُ سِتُّ مِائَةِ جَنَاحٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c519debf-9484-545d-85e4-f9378f6b6ba7', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '256', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ { ‏وَلَقَدْ رَآهُ نَزْلَةً أُخْرَى ‏} ‏قَالَ ‏ ‏رَأَى ‏ ‏جِبْرِيلَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('27c92c9d-cffc-5257-931b-8eb69e6b3dc9', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '257', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏رَآهُ بِقَلْبِهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f072030a-d399-594c-9fa8-6ebb8fd37865', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '258', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَأَبُو سَعِيدٍ الْأَشَجُّ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏وَكِيعٍ ‏ ‏قَالَ ‏ ‏الْأَشَجُّ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ الْحُصَيْنِ أَبِي جَهْمَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ { ‏مَا كَذَبَ الْفُؤَادُ مَا رَأَى ‏} { ‏وَلَقَدْ رَآهُ نَزْلَةً أُخْرَى ‏} ‏قَالَ ‏ ‏رَآهُ بِفُؤَادِهِ مَرَّتَيْنِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ غِيَاثٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَهْمَةَ ‏ ‏بِهَذَا الْإِسْنَادِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('25c54937-0735-53c8-af32-814e5ae3ef6f', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '259', '‏ ‏حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏قَالَ ‏ ‏كُنْتُ مُتَّكِئًا عِنْدَ ‏ ‏عَائِشَةَ ‏ ‏فَقَالَتْ يَا ‏ ‏أَبَا عَائِشَةَ ‏ ‏ثَلَاثٌ مَنْ تَكَلَّمَ بِوَاحِدَةٍ مِنْهُنَّ فَقَدْ أَعْظَمَ عَلَى اللَّهِ ‏ ‏الْفِرْيَةَ ‏ ‏قُلْتُ مَا هُنَّ قَالَتْ مَنْ زَعَمَ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى رَبَّهُ فَقَدْ أَعْظَمَ عَلَى اللَّهِ ‏ ‏الْفِرْيَةَ ‏ ‏قَالَ وَكُنْتُ مُتَّكِئًا فَجَلَسْتُ فَقُلْتُ يَا أُمَّ الْمُؤْمِنِينَ ‏ ‏أَنْظِرِينِي ‏ ‏وَلَا تَعْجَلِينِي أَلَمْ يَقُلْ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏وَلَقَدْ رَآهُ بِالْأُفُقِ الْمُبِينِ ‏} { ‏وَلَقَدْ رَآهُ نَزْلَةً أُخْرَى ‏} ‏فَقَالَتْ أَنَا أَوَّلُ هَذِهِ الْأُمَّةِ سَأَلَ عَنْ ذَلِكَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنَّمَا هُوَ ‏ ‏جِبْرِيلُ ‏ ‏لَمْ أَرَهُ عَلَى صُورَتِهِ الَّتِي خُلِقَ عَلَيْهَا غَيْرَ هَاتَيْنِ الْمَرَّتَيْنِ رَأَيْتُهُ مُنْهَبِطًا مِنْ السَّمَاءِ سَادًّا عِظَمُ خَلْقِهِ مَا بَيْنَ السَّمَاءِ إِلَى الْأَرْضِ فَقَالَتْ ‏ ‏أَوَ لَمْ تَسْمَعْ أَنَّ اللَّهَ يَقُولُ ‏ { ‏لَا تُدْرِكُهُ الْأَبْصَارُ وَهُوَ يُدْرِكُ الْأَبْصَارَ وَهُوَ اللَّطِيفُ الْخَبِيرُ ‏} ‏أَوَ لَمْ تَسْمَعْ أَنَّ اللَّهَ يَقُولُ ‏ { ‏وَمَا كَانَ لِبَشَرٍ أَنْ يُكَلِّمَهُ اللَّهُ إِلَّا وَحْيًا أَوْ مِنْ وَرَاءِ حِجَابٍ أَوْ يُرْسِلَ رَسُولًا فَيُوحِيَ بِإِذْنِهِ مَا يَشَاءُ إِنَّهُ عَلِيٌّ حَكِيمٌ ‏} ‏قَالَتْ وَمَنْ زَعَمَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَتَمَ شَيْئًا مِنْ كِتَابِ اللَّهِ فَقَدْ أَعْظَمَ عَلَى اللَّهِ ‏ ‏الْفِرْيَةَ ‏ ‏وَاللَّهُ يَقُولُ ‏ { ‏يَا أَيُّهَا الرَّسُولُ بَلِّغْ مَا أُنْزِلَ إِلَيْكَ مِنْ رَبِّكَ وَإِنْ لَمْ تَفْعَلْ فَمَا بَلَّغْتَ رِسَالَتَهُ ‏} ‏قَالَتْ وَمَنْ زَعَمَ أَنَّهُ يُخْبِرُ بِمَا يَكُونُ فِي غَدٍ فَقَدْ أَعْظَمَ عَلَى اللَّهِ ‏ ‏الْفِرْيَةَ ‏ ‏وَاللَّهُ يَقُولُ ‏ { ‏قُلْ لَا يَعْلَمُ مَنْ فِي السَّمَوَاتِ وَالْأَرْضِ الْغَيْبَ إِلَّا اللَّهُ ‏} ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏نَحْوَ حَدِيثِ ‏ ‏ابْنِ عُلَيَّةَ ‏ ‏وَزَادَ قَالَتْ وَلَوْ كَانَ ‏ ‏مُحَمَّدٌ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَاتِمًا شَيْئًا مِمَّا أُنْزِلَ عَلَيْهِ لَكَتَمَ هَذِهِ الْآيَةَ ‏ { ‏وَإِذْ تَقُولُ لِلَّذِي أَنْعَمَ اللَّهُ عَلَيْهِ وَأَنْعَمْتَ عَلَيْهِ أَمْسِكْ عَلَيْكَ زَوْجَكَ وَاتَّقِ اللَّهَ وَتُخْفِي فِي نَفْسِكَ مَا اللَّهُ مُبْدِيهِ ‏ ‏وَتَخْشَى النَّاسَ وَاللَّهُ أَحَقُّ أَنْ تَخْشَاهُ ‏} ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏قَالَ سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏هَلْ رَأَى ‏ ‏مُحَمَّدٌ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَبَّهُ فَقَالَتْ سُبْحَانَ اللَّهِ لَقَدْ قَفَّ شَعَرِي لِمَا قُلْتَ وَسَاقَ الْحَدِيثَ بِقِصَّتِهِ وَحَدِيثُ ‏ ‏دَاوُدَ ‏ ‏أَتَمُّ وَأَطْوَلُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('256660ee-aaac-593d-a4ae-7eeacd326810', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '260', '‏ ‏و حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّاءُ ‏ ‏عَنْ ‏ ‏ابْنِ أَشْوَعَ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏قَالَ قُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏فَأَيْنَ ‏ ‏قَوْله ‏ { ‏ثُمَّ دَنَا ‏ ‏فَتَدَلَّى ‏ ‏فَكَانَ قَابَ قَوْسَيْنِ أَوْ أَدْنَى فَأَوْحَى إِلَى عَبْدِهِ مَا أَوْحَى ‏} ‏قَالَتْ ‏ ‏إِنَّمَا ذَاكَ ‏ ‏جِبْرِيلُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَأْتِيهِ فِي صُورَةِ الرِّجَالِ وَإِنَّهُ أَتَاهُ فِي هَذِهِ الْمَرَّةِ فِي صُورَتِهِ الَّتِي هِيَ صُورَتُهُ فَسَدَّ أُفُقَ السَّمَاءِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('607d9f75-04ec-5388-b88d-ed29ddc42e18', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '261', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنْ ‏ ‏أَبِي ذَرٍّ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ رَأَيْتَ رَبَّكَ قَالَ ‏ ‏نُورٌ أَنَّى أَرَاهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d083e4bc-694c-59a5-a5c0-f70e8aecc916', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '262', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏حَجَّاجُ بْنُ الشَّاعِرِ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏قَالَ قُلْتُ ‏ ‏لِأَبِي ذَرٍّ ‏ ‏لَوْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَسَأَلْتُهُ فَقَالَ عَنْ أَيِّ شَيْءٍ كُنْتَ تَسْأَلُهُ قَالَ كُنْتُ أَسْأَلُهُ هَلْ رَأَيْتَ رَبَّكَ قَالَ ‏ ‏أَبُو ذَرٍّ ‏ ‏قَدْ سَأَلْتُ فَقَالَ ‏ ‏رَأَيْتُ نُورًا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cb74e332-1765-559f-a6dd-c39ed0d2515b', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '263', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَأَبُو كُرَيْبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَامَ فِينَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِخَمْسِ كَلِمَاتٍ فَقَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ لَا يَنَامُ وَلَا يَنْبَغِي لَهُ أَنْ يَنَامَ يَخْفِضُ ‏ ‏الْقِسْطَ ‏ ‏وَيَرْفَعُهُ يُرْفَعُ إِلَيْهِ عَمَلُ اللَّيْلِ قَبْلَ عَمَلِ النَّهَارِ وَعَمَلُ النَّهَارِ قَبْلَ عَمَلِ اللَّيْلِ حِجَابُهُ النُّورُ ‏ ‏وَفِي رِوَايَةِ ‏ ‏أَبِي بَكْرٍ ‏ ‏النَّارُ ‏ ‏لَوْ كَشَفَهُ لَأَحْرَقَتْ سُبُحَاتُ وَجْهِهِ مَا انْتَهَى إِلَيْهِ بَصَرُهُ مِنْ خَلْقِهِ ‏ ‏وَفِي رِوَايَةِ ‏ ‏أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏وَلَمْ يَقُلْ حَدَّثَنَا ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏أَخْبَرَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏قَالَ ‏ ‏قَامَ فِينَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِأَرْبَعِ كَلِمَاتٍ ثُمَّ ذَكَرَ بِمِثْلِ حَدِيثِ ‏ ‏أَبِي مُعَاوِيَةَ ‏ ‏وَلَمْ يَذْكُرْ مِنْ خَلْقِهِ وَقَالَ حِجَابُهُ النُّورُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c99bb415-e839-5a06-a405-8f63090fce29', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '264', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏وَابْنُ بَشَّارٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَامَ فِينَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِأَرْبَعٍ ‏ ‏إِنَّ اللَّهَ لَا يَنَامُ وَلَا يَنْبَغِي لَهُ أَنْ يَنَامَ يَرْفَعُ ‏ ‏الْقِسْطَ ‏ ‏وَيَخْفِضُهُ وَيُرْفَعُ إِلَيْهِ عَمَلُ النَّهَارِ بِاللَّيْلِ وَعَمَلُ اللَّيْلِ بِالنَّهَارِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0c35dec1-765c-5b0b-bf54-fbef5c90fd43', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '265', '‏ ‏حَدَّثَنَا ‏ ‏نَصْرُ بْنُ عَلِيٍّ الْجَهْضَمِيُّ ‏ ‏وَأَبُو غَسَّانَ الْمَسْمَعِيُّ ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ عَبْدِ الصَّمَدِ ‏ ‏وَاللَّفْظُ ‏ ‏لِأَبِي غَسَّانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عِمْرَانَ الْجَوْنِيُّ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ اللَّهِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏جَنَّتَانِ مِنْ فِضَّةٍ آنِيَتُهُمَا وَمَا فِيهِمَا وَجَنَّتَانِ مِنْ ذَهَبٍ آنِيَتُهُمَا وَمَا فِيهِمَا وَمَا بَيْنَ الْقَوْمِ وَبَيْنَ أَنْ يَنْظُرُوا إِلَى رَبِّهِمْ إِلَّا رِدَاءُ الْكِبْرِيَاءِ عَلَى وَجْهِهِ فِي جَنَّةِ عَدْنٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('977cfda5-b535-5a7a-ade4-3a6cd258b528', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '266', '‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مَيْسَرَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏صُهَيْبٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا دَخَلَ أَهْلُ الْجَنَّةِ الْجَنَّةَ قَالَ يَقُولُ اللَّهُ تَبَارَكَ وَتَعَالَى تُرِيدُونَ شَيْئًا أَزِيدُكُمْ فَيَقُولُونَ أَلَمْ تُبَيِّضْ وُجُوهَنَا أَلَمْ تُدْخِلْنَا الْجَنَّةَ وَتُنَجِّنَا مِنْ النَّارِ قَالَ فَيَكْشِفُ الْحِجَابَ فَمَا أُعْطُوا شَيْئًا أَحَبَّ إِلَيْهِمْ مِنْ النَّظَرِ إِلَى رَبِّهِمْ عَزَّ وَجَلَّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏عَنْ ‏ ‏حَمَّادِ بْنِ سَلَمَةَ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏وَزَادَ ثُمَّ تَلَا هَذِهِ الْآيَةَ ‏ { ‏لِلَّذِينَ أَحْسَنُوا الْحُسْنَى وَزِيَادَةٌ ‏}', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0da72e9b-886a-53b5-ba24-0f5a54bf04fa', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '267', '‏ ‏حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ نَاسًا قَالُوا لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا رَسُولَ اللَّهِ هَلْ نَرَى رَبَّنَا يَوْمَ الْقِيَامَةِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ تُضَارُّونَ فِي رُؤْيَةِ الْقَمَرِ لَيْلَةَ الْبَدْرِ قَالُوا لَا يَا رَسُولَ اللَّهِ قَالَ هَلْ تُضَارُّونَ فِي الشَّمْسِ لَيْسَ دُونَهَا سَحَابٌ قَالُوا لَا يَا رَسُولَ اللَّهِ قَالَ فَإِنَّكُمْ تَرَوْنَهُ كَذَلِكَ يَجْمَعُ اللَّهُ النَّاسَ يَوْمَ الْقِيَامَةِ فَيَقُولُ مَنْ كَانَ يَعْبُدُ شَيْئًا فَلْيَتَّبِعْهُ فَيَتَّبِعُ مَنْ كَانَ يَعْبُدُ الشَّمْسَ الشَّمْسَ وَيَتَّبِعُ مَنْ كَانَ يَعْبُدُ الْقَمَرَ الْقَمَرَ وَيَتَّبِعُ مَنْ كَانَ يَعْبُدُ الطَّوَاغِيتَ الطَّوَاغِيتَ وَتَبْقَى هَذِهِ الْأُمَّةُ فِيهَا مُنَافِقُوهَا ‏ ‏فَيَأْتِيهِمْ اللَّهُ تَبَارَكَ وَتَعَالَى فِي صُورَةٍ غَيْرِ صُورَتِهِ الَّتِي يَعْرِفُونَ فَيَقُولُ أَنَا رَبُّكُمْ فَيَقُولُونَ نَعُوذُ بِاللَّهِ مِنْكَ هَذَا مَكَانُنَا حَتَّى يَأْتِيَنَا رَبُّنَا فَإِذَا جَاءَ رَبُّنَا عَرَفْنَاهُ ‏ ‏فَيَأْتِيهِمْ اللَّهُ تَعَالَى فِي صُورَتِهِ الَّتِي يَعْرِفُونَ فَيَقُولُ أَنَا رَبُّكُمْ فَيَقُولُونَ أَنْتَ رَبُّنَا فَيَتَّبِعُونَهُ ‏ ‏وَيُضْرَبُ ‏ ‏الصِّرَاطُ بَيْنَ ظَهْرَيْ جَهَنَّمَ فَأَكُونُ أَنَا وَأُمَّتِي أَوَّلَ مَنْ يُجِيزُ وَلَا يَتَكَلَّمُ يَوْمَئِذٍ إِلَّا الرُّسُلُ وَدَعْوَى الرُّسُلِ يَوْمَئِذٍ اللَّهُمَّ سَلِّمْ سَلِّمْ وَفِي جَهَنَّمَ كَلَالِيبُ مِثْلُ شَوْكِ السَّعْدَانِ هَلْ رَأَيْتُمْ السَّعْدَانَ قَالُوا نَعَمْ يَا رَسُولَ اللَّهِ قَالَ فَإِنَّهَا مِثْلُ شَوْكِ السَّعْدَانِ غَيْرَ أَنَّهُ لَا يَعْلَمُ مَا قَدْرُ عِظَمِهَا إِلَّا اللَّهُ تَخْطَفُ النَّاسَ بِأَعْمَالِهِمْ فَمِنْهُمْ الْمُؤْمِنُ بَقِيَ بِعَمَلِهِ وَمِنْهُمْ الْمُجَازَى حَتَّى ‏ ‏يُنَجَّى حَتَّى إِذَا فَرَغَ اللَّهُ مِنْ الْقَضَاءِ بَيْنَ الْعِبَادِ وَأَرَادَ أَنْ يُخْرِجَ بِرَحْمَتِهِ مَنْ أَرَادَ مِنْ أَهْلِ النَّارِ أَمَرَ الْمَلَائِكَةَ أَنْ يُخْرِجُوا مِنْ النَّارِ مَنْ كَانَ لَا يُشْرِكُ بِاللَّهِ شَيْئًا مِمَّنْ أَرَادَ اللَّهُ تَعَالَى أَنْ يَرْحَمَهُ مِمَّنْ يَقُولُ لَا إِلَهَ إِلَّا اللَّهُ فَيَعْرِفُونَهُمْ فِي النَّارِ يَعْرِفُونَهُمْ بِأَثَرِ السُّجُودِ تَأْكُلُ النَّارُ مِنْ ابْنِ ‏ ‏آدَمَ ‏ ‏إِلَّا أَثَرَ السُّجُودِ حَرَّمَ اللَّهُ عَلَى النَّارِ أَنْ تَأْكُلَ أَثَرَ السُّجُودِ فَيُخْرَجُونَ مِنْ النَّارِ وَقَدْ امْتَحَشُوا فَيُصَبُّ عَلَيْهِمْ مَاءُ الْحَيَاةِ فَيَنْبُتُونَ مِنْهُ كَمَا تَنْبُتُ الْحِبَّةُ فِي حَمِيلِ السَّيْلِ ثُمَّ يَفْرُغُ اللَّهُ تَعَالَى مِنْ الْقَضَاءِ بَيْنَ الْعِبَادِ وَيَبْقَى رَجُلٌ مُقْبِلٌ بِوَجْهِهِ عَلَى النَّارِ وَهُوَ آخِرُ أَهْلِ الْجَنَّةِ دُخُولًا الْجَنَّةَ فَيَقُولُ أَيْ رَبِّ اصْرِفْ وَجْهِي عَنْ النَّارِ فَإِنَّهُ قَدْ قَشَبَنِي رِيحُهَا وَأَحْرَقَنِي ذَكَاؤُهَا فَيَدْعُو اللَّهَ مَا شَاءَ اللَّهُ أَنْ يَدْعُوَهُ ثُمَّ يَقُولُ اللَّهُ تَبَارَكَ وَتَعَالَى هَلْ عَسَيْتَ إِنْ فَعَلْتُ ذَلِكَ بِكَ أَنْ تَسْأَلَ غَيْرَهُ فَيَقُولُ لَا أَسْأَلُكَ غَيْرَهُ وَيُعْطِي رَبَّهُ مِنْ عُهُودٍ وَمَوَاثِيقَ مَا شَاءَ اللَّهُ فَيَصْرِفُ اللَّهُ وَجْهَهُ عَنْ النَّارِ فَإِذَا أَقْبَلَ عَلَى الْجَنَّةِ وَرَآهَا سَكَتَ مَا شَاءَ اللَّهُ أَنْ يَسْكُتَ ثُمَّ يَقُولُ أَيْ رَبِّ قَدِّمْنِي إِلَى بَابِ الْجَنَّةِ فَيَقُولُ اللَّهُ لَهُ أَلَيْسَ قَدْ أَعْطَيْتَ عُهُودَكَ وَمَوَاثِيقَكَ لَا تَسْأَلُنِي غَيْرَ الَّذِي أَعْطَيْتُكَ وَيْلَكَ يَا ابْنَ ‏ ‏آدَمَ ‏ ‏مَا أَغْدَرَكَ فَيَقُولُ أَيْ رَبِّ وَيَدْعُو اللَّهَ حَتَّى يَقُولَ لَهُ فَهَلْ عَسَيْتَ إِنْ أَعْطَيْتُكَ ذَلِكَ أَنْ تَسْأَلَ غَيْرَهُ فَيَقُولُ لَا وَعِزَّتِكَ فَيُعْطِي رَبَّهُ مَا شَاءَ اللَّهُ مِنْ عُهُودٍ وَمَوَاثِيقَ فَيُقَدِّمُهُ إِلَى بَابِ الْجَنَّةِ فَإِذَا قَامَ عَلَى بَابِ الْجَنَّةِ ‏ ‏انْفَهَقَتْ ‏ ‏لَهُ الْجَنَّةُ فَرَأَى مَا فِيهَا مِنْ الْخَيْرِ وَالسُّرُورِ فَيَسْكُتُ مَا شَاءَ اللَّهُ أَنْ يَسْكُتَ ثُمَّ يَقُولُ أَيْ رَبِّ أَدْخِلْنِي الْجَنَّةَ فَيَقُولُ اللَّهُ تَبَارَكَ وَتَعَالَى لَهُ أَلَيْسَ قَدْ أَعْطَيْتَ عُهُودَكَ وَمَوَاثِيقَكَ أَنْ لَا تَسْأَلَ غَيْرَ مَا أُعْطِيتَ وَيْلَكَ يَا ابْنَ ‏ ‏آدَمَ ‏ ‏مَا أَغْدَرَكَ فَيَقُولُ أَيْ رَبِّ لَا أَكُونُ أَشْقَى خَلْقِكَ فَلَا يَزَالُ يَدْعُو اللَّهَ حَتَّى يَضْحَكَ اللَّهُ تَبَارَكَ وَتَعَالَى مِنْهُ فَإِذَا ضَحِكَ اللَّهُ مِنْهُ قَالَ ادْخُلْ الْجَنَّةَ فَإِذَا دَخَلَهَا قَالَ اللَّهُ لَهُ ‏ ‏تَمَنَّهْ فَيَسْأَلُ رَبَّهُ ‏ ‏وَيَتَمَنَّى حَتَّى إِنَّ اللَّهَ لَيُذَكِّرُهُ مِنْ كَذَا وَكَذَا حَتَّى إِذَا انْقَطَعَتْ بِهِ الْأَمَانِيُّ قَالَ اللَّهُ تَعَالَى ذَلِكَ لَكَ وَمِثْلُهُ مَعَهُ ‏ ‏قَالَ ‏ ‏عَطَاءُ بْنُ يَزِيدَ ‏ ‏وَأَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏مَعَ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏لَا يَرُدُّ عَلَيْهِ مِنْ حَدِيثِهِ شَيْئًا حَتَّى إِذَا حَدَّثَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏أَنَّ اللَّهَ قَالَ لِذَلِكَ الرَّجُلِ وَمِثْلُهُ مَعَهُ قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏وَعَشَرَةُ أَمْثَالِهِ مَعَهُ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏مَا حَفِظْتُ إِلَّا قَوْلَهُ ذَلِكَ لَكَ وَمِثْلُهُ مَعَهُ قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏أَشْهَدُ أَنِّي حَفِظْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَوْلَهُ ذَلِكَ لَكَ وَعَشَرَةُ أَمْثَالِهِ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏وَذَلِكَ الرَّجُلُ آخِرُ أَهْلِ الْجَنَّةِ دُخُولًا الْجَنَّةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ الدَّارِمِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سَعِيدُ بْنُ الْمُسَيَّبِ ‏ ‏وَعَطَاءُ بْنُ يَزِيدَ اللَّيْثِيُّ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَخْبَرَهُمَا ‏ ‏أَنَّ النَّاسَ قَالُوا لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا رَسُولَ اللَّهِ هَلْ نَرَى رَبَّنَا يَوْمَ الْقِيَامَةِ وَسَاقَ الْحَدِيثَ بِمِثْلِ مَعْنَى حَدِيثِ ‏ ‏إِبْرَاهِيمَ بْنِ سَعْدٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7c0d569b-2e66-5da9-9fdc-c7a4ffcc7340', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '268', '‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ مُنَبِّهٍ ‏ ‏قَالَ هَذَا مَا حَدَّثَنَا ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ أَحَادِيثَ مِنْهَا ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَدْنَى مَقْعَدِ أَحَدِكُمْ مِنْ الْجَنَّةِ أَنْ يَقُولَ لَهُ تَمَنَّ فَيَتَمَنَّى ‏ ‏وَيَتَمَنَّى فَيَقُولُ لَهُ هَلْ تَمَنَّيْتَ فَيَقُولُ نَعَمْ فَيَقُولُ لَهُ فَإِنَّ لَكَ مَا تَمَنَّيْتَ وَمِثْلَهُ مَعَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('89e4773f-8fa8-538b-b18d-0575476d6fb1', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '269', '‏ ‏و حَدَّثَنِي ‏ ‏سُوَيْدُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏حَفْصُ بْنُ مَيْسَرَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ نَاسًا فِي زَمَنِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالُوا يَا رَسُولَ اللَّهِ هَلْ نَرَى رَبَّنَا يَوْمَ الْقِيَامَةِ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَعَمْ قَالَ ‏ ‏هَلْ ‏ ‏تُضَارُّونَ ‏ ‏فِي رُؤْيَةِ الشَّمْسِ بِالظَّهِيرَةِ صَحْوًا لَيْسَ مَعَهَا سَحَابٌ وَهَلْ ‏ ‏تُضَارُّونَ ‏ ‏فِي رُؤْيَةِ الْقَمَرِ لَيْلَةَ الْبَدْرِ صَحْوًا لَيْسَ فِيهَا سَحَابٌ قَالُوا لَا يَا رَسُولَ اللَّهِ قَالَ مَا ‏ ‏تُضَارُّونَ ‏ ‏فِي رُؤْيَةِ اللَّهِ تَبَارَكَ وَتَعَالَى يَوْمَ الْقِيَامَةِ إِلَّا كَمَا ‏ ‏تُضَارُّونَ ‏ ‏فِي رُؤْيَةِ أَحَدِهِمَا إِذَا كَانَ يَوْمُ الْقِيَامَةِ أَذَّنَ مُؤَذِّنٌ لِيَتَّبِعْ كُلُّ أُمَّةٍ مَا كَانَتْ تَعْبُدُ فَلَا يَبْقَى أَحَدٌ كَانَ يَعْبُدُ غَيْرَ اللَّهِ سُبْحَانَهُ مِنْ الْأَصْنَامِ وَالْأَنْصَابِ إِلَّا يَتَسَاقَطُونَ فِي النَّارِ حَتَّى إِذَا لَمْ يَبْقَ إِلَّا مَنْ كَانَ يَعْبُدُ اللَّهَ مِنْ بَرٍّ وَفَاجِرٍ وَغُبَّرِ ‏ ‏أَهْلِ الْكِتَابِ ‏ ‏فَيُدْعَى ‏ ‏الْيَهُودُ ‏ ‏فَيُقَالُ لَهُمْ مَا كُنْتُمْ تَعْبُدُونَ قَالُوا كُنَّا نَعْبُدُ ‏ ‏عُزَيْرَ ‏ ‏ابْنَ اللَّهِ فَيُقَالُ كَذَبْتُمْ مَا اتَّخَذَ اللَّهُ مِنْ صَاحِبَةٍ وَلَا وَلَدٍ فَمَاذَا ‏ ‏تَبْغُونَ ‏ ‏قَالُوا عَطِشْنَا يَا رَبَّنَا فَاسْقِنَا فَيُشَارُ إِلَيْهِمْ أَلَا تَرِدُونَ فَيُحْشَرُونَ إِلَى النَّارِ كَأَنَّهَا سَرَابٌ ‏ ‏يَحْطِمُ ‏ ‏بَعْضُهَا بَعْضًا فَيَتَسَاقَطُونَ فِي النَّارِ ثُمَّ يُدْعَى ‏ ‏النَّصَارَى ‏ ‏فَيُقَالُ لَهُمْ مَا كُنْتُمْ تَعْبُدُونَ قَالُوا كُنَّا نَعْبُدُ ‏ ‏الْمَسِيحَ ‏ ‏ابْنَ اللَّهِ فَيُقَالُ لَهُمْ كَذَبْتُمْ مَا اتَّخَذَ اللَّهُ مِنْ صَاحِبَةٍ وَلَا وَلَدٍ فَيُقَالُ لَهُمْ مَاذَا تَبْغُونَ فَيَقُولُونَ عَطِشْنَا يَا رَبَّنَا فَاسْقِنَا قَالَ فَيُشَارُ إِلَيْهِمْ أَلَا تَرِدُونَ فَيُحْشَرُونَ إِلَى جَهَنَّمَ كَأَنَّهَا سَرَابٌ يَحْطِمُ بَعْضُهَا بَعْضًا فَيَتَسَاقَطُونَ فِي النَّارِ حَتَّى إِذَا لَمْ يَبْقَ إِلَّا مَنْ كَانَ يَعْبُدُ اللَّهَ تَعَالَى مِنْ ‏ ‏بَرٍّ ‏ ‏وَفَاجِرٍ أَتَاهُمْ رَبُّ الْعَالَمِينَ سُبْحَانَهُ وَتَعَالَى فِي أَدْنَى صُورَةٍ مِنْ الَّتِي رَأَوْهُ فِيهَا قَالَ فَمَا تَنْتَظِرُونَ تَتْبَعُ كُلُّ أُمَّةٍ مَا كَانَتْ تَعْبُدُ قَالُوا يَا رَبَّنَا فَارَقْنَا النَّاسَ فِي الدُّنْيَا أَفْقَرَ مَا كُنَّا إِلَيْهِمْ وَلَمْ نُصَاحِبْهُمْ فَيَقُولُ أَنَا رَبُّكُمْ فَيَقُولُونَ نَعُوذُ بِاللَّهِ مِنْكَ لَا نُشْرِكُ بِاللَّهِ شَيْئًا مَرَّتَيْنِ أَوْ ثَلَاثًا حَتَّى إِنَّ بَعْضَهُمْ لَيَكَادُ أَنْ ‏ ‏يَنْقَلِبَ ‏ ‏فَيَقُولُ هَلْ بَيْنَكُمْ وَبَيْنَهُ ‏ ‏آيَةٌ ‏ ‏فَتَعْرِفُونَهُ بِهَا فَيَقُولُونَ نَعَمْ فَيُكْشَفُ عَنْ سَاقٍ فَلَا يَبْقَى مَنْ كَانَ يَسْجُدُ لِلَّهِ مِنْ تِلْقَاءِ نَفْسِهِ إِلَّا أَذِنَ اللَّهُ لَهُ بِالسُّجُودِ وَلَا يَبْقَى مَنْ كَانَ يَسْجُدُ اتِّقَاءً وَرِيَاءً إِلَّا جَعَلَ اللَّهُ ظَهْرَهُ ‏ ‏طَبَقَةً ‏ ‏وَاحِدَةً كُلَّمَا أَرَادَ أَنْ يَسْجُدَ ‏ ‏خَرَّ ‏ ‏عَلَى ‏ ‏قَفَاهُ ‏ ‏ثُمَّ يَرْفَعُونَ رُءُوسَهُمْ وَقَدْ تَحَوَّلَ فِي صُورَتِهِ الَّتِي رَأَوْهُ فِيهَا أَوَّلَ مَرَّةٍ فَقَالَ أَنَا رَبُّكُمْ فَيَقُولُونَ أَنْتَ رَبُّنَا ثُمَّ ‏ ‏يُضْرَبُ ‏ ‏الْجِسْرُ عَلَى جَهَنَّمَ ‏ ‏وَتَحِلُّ ‏ ‏الشَّفَاعَةُ وَيَقُولُونَ اللَّهُمَّ سَلِّمْ سَلِّمْ قِيلَ يَا رَسُولَ اللَّهِ وَمَا الْجِسْرُ قَالَ ‏ ‏دَحْضٌ ‏ ‏مَزِلَّةٌ فِيهِ ‏ ‏خَطَاطِيفُ ‏ ‏وَكَلَالِيبُ ‏ ‏وَحَسَكٌ ‏ ‏تَكُونُ ‏ ‏بِنَجْدٍ ‏ ‏فِيهَا ‏ ‏شُوَيْكَةٌ يُقَالُ لَهَا ‏ ‏السَّعْدَانُ ‏ ‏فَيَمُرُّ الْمُؤْمِنُونَ كَطَرْفِ الْعَيْنِ وَكَالْبَرْقِ وَكَالرِّيحِ وَكَالطَّيْرِ ‏ ‏وَكَأَجَاوِيدِ ‏ ‏الْخَيْلِ ‏ ‏وَالرِّكَابِ ‏ ‏فَنَاجٍ مُسَلَّمٌ وَمَخْدُوشٌ مُرْسَلٌ ‏ ‏وَمَكْدُوسٌ ‏ ‏فِي نَارِ جَهَنَّمَ حَتَّى إِذَا خَلَصَ الْمُؤْمِنُونَ مِنْ النَّارِ فَوَالَّذِي نَفْسِي بِيَدِهِ مَا مِنْكُمْ مِنْ أَحَدٍ بِأَشَدَّ مُنَاشَدَةً لِلَّهِ فِي ‏ ‏اسْتِقْصَاءِ ‏ ‏الْحَقِّ مِنْ الْمُؤْمِنِينَ لِلَّهِ يَوْمَ الْقِيَامَةِ لِإِخْوَانِهِمْ الَّذِينَ فِي النَّارِ يَقُولُونَ رَبَّنَا كَانُوا يَصُومُونَ مَعَنَا وَيُصَلُّونَ وَيَحُجُّونَ فَيُقَالُ لَهُمْ أَخْرِجُوا مَنْ عَرَفْتُمْ فَتُحَرَّمُ صُوَرُهُمْ عَلَى النَّارِ فَيُخْرِجُونَ خَلْقًا كَثِيرًا قَدْ أَخَذَتْ النَّارُ إِلَى نِصْفِ سَاقَيْهِ وَإِلَى رُكْبَتَيْهِ ثُمَّ يَقُولُونَ رَبَّنَا مَا بَقِيَ فِيهَا أَحَدٌ مِمَّنْ أَمَرْتَنَا بِهِ فَيَقُولُ ارْجِعُوا فَمَنْ وَجَدْتُمْ فِي قَلْبِهِ مِثْقَالَ دِينَارٍ مِنْ خَيْرٍ فَأَخْرِجُوهُ فَيُخْرِجُونَ خَلْقًا كَثِيرًا ثُمَّ يَقُولُونَ رَبَّنَا لَمْ ‏ ‏نَذَرْ ‏ ‏فِيهَا أَحَدًا مِمَّنْ أَمَرْتَنَا ثُمَّ يَقُولُ ارْجِعُوا فَمَنْ وَجَدْتُمْ فِي قَلْبِهِ مِثْقَالَ نِصْفِ دِينَارٍ مِنْ خَيْرٍ فَأَخْرِجُوهُ فَيُخْرِجُونَ خَلْقًا كَثِيرًا ثُمَّ يَقُولُونَ رَبَّنَا لَمْ ‏ ‏نَذَرْ ‏ ‏فِيهَا مِمَّنْ أَمَرْتَنَا أَحَدًا ثُمَّ يَقُولُ ارْجِعُوا فَمَنْ وَجَدْتُمْ فِي قَلْبِهِ مِثْقَالَ ذَرَّةٍ مِنْ خَيْرٍ فَأَخْرِجُوهُ فَيُخْرِجُونَ خَلْقًا كَثِيرًا ثُمَّ يَقُولُونَ رَبَّنَا لَمْ ‏ ‏نَذَرْ ‏ ‏فِيهَا خَيْرًا وَكَانَ ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏يَقُولُ إِنْ لَمْ تُصَدِّقُونِي بِهَذَا الْحَدِيثِ فَاقْرَءُوا إِنْ شِئْتُمْ ‏ { ‏إِنَّ اللَّهَ لَا يَظْلِمُ مِثْقَالَ ذَرَّةٍ وَإِنْ تَكُ حَسَنَةً يُضَاعِفْهَا وَيُؤْتِ مِنْ لَدُنْهُ أَجْرًا عَظِيمًا ‏} ‏فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ شَفَعَتْ الْمَلَائِكَةُ وَشَفَعَ النَّبِيُّونَ وَشَفَعَ الْمُؤْمِنُونَ وَلَمْ يَبْقَ إِلَّا أَرْحَمُ الرَّاحِمِينَ فَيَقْبِضُ قَبْضَةً مِنْ النَّارِ فَيُخْرِجُ مِنْهَا قَوْمًا لَمْ يَعْمَلُوا خَيْرًا قَطُّ قَدْ ‏ ‏عَادُوا ‏ ‏حُمَمًا ‏ ‏فَيُلْقِيهِمْ فِي نَهَرٍ فِي أَفْوَاهِ الْجَنَّةِ يُقَالُ لَهُ نَهَرُ الْحَيَاةِ فَيَخْرُجُونَ كَمَا تَخْرُجُ الْحِبَّةُ فِي ‏ ‏حَمِيلِ ‏ ‏السَّيْلِ أَلَا تَرَوْنَهَا تَكُونُ إِلَى الْحَجَرِ أَوْ إِلَى الشَّجَرِ مَا يَكُونُ إِلَى الشَّمْسِ ‏ ‏أُصَيْفِرُ وَأُخَيْضِرُ وَمَا يَكُونُ مِنْهَا إِلَى الظِّلِّ يَكُونُ أَبْيَضَ فَقَالُوا يَا رَسُولَ اللَّهِ كَأَنَّكَ كُنْتَ ‏ ‏تَرْعَى بِالْبَادِيَةِ قَالَ فَيَخْرُجُونَ كَاللُّؤْلُؤِ فِي رِقَابِهِمْ الْخَوَاتِمُ يَعْرِفُهُمْ أَهْلُ الْجَنَّةِ هَؤُلَاءِ عُتَقَاءُ اللَّهِ الَّذِينَ أَدْخَلَهُمْ اللَّهُ الْجَنَّةَ بِغَيْرِ عَمَلٍ عَمِلُوهُ وَلَا خَيْرٍ قَدَّمُوهُ ثُمَّ يَقُولُ ادْخُلُوا الْجَنَّةَ فَمَا رَأَيْتُمُوهُ فَهُوَ لَكُمْ فَيَقُولُونَ رَبَّنَا أَعْطَيْتَنَا مَا لَمْ تُعْطِ أَحَدًا مِنْ الْعَالَمِينَ فَيَقُولُ لَكُمْ عِنْدِي أَفْضَلُ مِنْ هَذَا فَيَقُولُونَ يَا رَبَّنَا أَيُّ شَيْءٍ أَفْضَلُ مِنْ هَذَا فَيَقُولُ رِضَايَ فَلَا أَسْخَطُ عَلَيْكُمْ بَعْدَهُ أَبَدًا ‏ ‏قَالَ ‏ ‏مُسْلِم ‏ ‏قَرَأْتُ عَلَى ‏ ‏عِيسَى بْنِ حَمَّادٍ زُغْبَةَ الْمِصْرِيِّ ‏ ‏هَذَا الْحَدِيثَ فِي الشَّفَاعَةِ وَقُلْتُ لَهُ أُحَدِّثُ بِهَذَا الْحَدِيثِ عَنْكَ أَنَّكَ ‏ ‏سَمِعْتَ مِنَ ‏ ‏اللَّيْثِ بْنِ سَعْدٍ ‏ ‏فَقَالَ نَعَمْ قُلْتُ ‏ ‏لِعِيسَى بْنِ حَمَّادٍ ‏ ‏أَخْبَرَكُمُ ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي هِلَالٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّهُ قَالَ قُلْنَا يَا رَسُولَ اللَّهِ ‏ ‏أَنَرَى رَبَّنَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ ‏ ‏تُضَارُّونَ ‏ ‏فِي رُؤْيَةِ الشَّمْسِ إِذَا كَانَ يَوْمٌ صَحْوٌ قُلْنَا لَا وَسُقْتُ الْحَدِيثَ حَتَّى انْقَضَى آخِرُهُ وَهُوَ نَحْوُ حَدِيثِ ‏ ‏حَفْصِ بْنِ مَيْسَرَةَ ‏ ‏وَزَادَ بَعْدَ قَوْلِهِ بِغَيْرِ عَمَلٍ عَمِلُوهُ وَلَا قَدَمٍ قَدَّمُوهُ فَيُقَالُ لَهُمْ لَكُمْ مَا رَأَيْتُمْ وَمِثْلُهُ مَعَهُ قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏بَلَغَنِي أَنَّ الْجِسْرَ أَدَقُّ مِنْ الشَّعْرَةِ وَأَحَدُّ مِنْ السَّيْفِ وَلَيْسَ فِي حَدِيثِ ‏ ‏اللَّيْثِ ‏ ‏فَيَقُولُونَ رَبَّنَا أَعْطَيْتَنَا مَا لَمْ تُعْطِ أَحَدًا مِنْ الْعَالَمِينَ وَمَا بَعْدَهُ فَأَقَرَّ بِهِ ‏ ‏عِيسَى بْنُ حَمَّادٍ ‏ ‏و حَدَّثَنَاه ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏بِإِسْنَادِهِمَا ‏ ‏نَحْوَ حَدِيثِ ‏ ‏حَفْصِ بْنِ مَيْسَرَةَ ‏ ‏إِلَى آخِرِهِ وَقَدْ زَادَ وَنَقَصَ شَيْئًا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9bdce880-44a6-55ce-a342-c006acdb3ab3', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '270', '‏ ‏و حَدَّثَنِي ‏ ‏هَارُونُ بْنُ سَعِيدٍ الْأَيْلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى بْنِ عُمَارَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُدْخِلُ اللَّهُ أَهْلَ الْجَنَّةِ الْجَنَّةَ يُدْخِلُ مَنْ يَشَاءُ بِرَحْمَتِهِ وَيُدْخِلُ أَهْلَ النَّارِ النَّارَ ثُمَّ يَقُولُ انْظُرُوا مَنْ وَجَدْتُمْ فِي قَلْبِهِ مِثْقَالَ حَبَّةٍ مِنْ خَرْدَلٍ مِنْ إِيمَانٍ فَأَخْرِجُوهُ فَيُخْرَجُونَ مِنْهَا حُمَمًا قَدْ ‏ ‏امْتَحَشُوا ‏ ‏فَيُلْقَوْنَ فِي نَهَرِ الْحَيَاةِ ‏ ‏أَوْ الْحَيَا ‏ ‏فَيَنْبُتُونَ فِيهِ كَمَا تَنْبُتُ الْحِبَّةُ إِلَى جَانِبِ السَّيْلِ أَلَمْ تَرَوْهَا كَيْفَ تَخْرُجُ صَفْرَاءَ مُلْتَوِيَةً ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ الشَّاعِرِ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏أَخْبَرَنَا ‏ ‏خَالِدٌ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏وَقَالَا ‏ ‏فَيُلْقَوْنَ فِي نَهَرٍ يُقَالَ لَهُ الْحَيَاةُ وَلَمْ يَشُكَّا وَفِي حَدِيثِ ‏ ‏خَالِدٍ ‏ ‏كَمَا تَنْبُتُ ‏ ‏الْغُثَاءَةُ ‏ ‏فِي جَانِبِ السَّيْلِ ‏ ‏وَفِي حَدِيثِ ‏ ‏وُهَيْبٍ ‏ ‏كَمَا تَنْبُتُ الْحِبَّةُ فِي ‏ ‏حَمِئَةٍ ‏ ‏أَوْ ‏ ‏حَمِيلَةِ ‏ ‏السَّيْلِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4103dc3c-fb41-5e6b-a57f-888c28064a15', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '271', '‏ ‏و حَدَّثَنِي ‏ ‏نَصْرُ بْنُ عَلِيٍّ الْجَهْضَمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏بِشْرٌ يَعْنِي ابْنَ الْمُفَضَّلِ ‏ ‏عَنْ ‏ ‏أَبِي مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَّا أَهْلُ النَّارِ الَّذِينَ هُمْ أَهْلُهَا فَإِنَّهُمْ لَا يَمُوتُونَ فِيهَا وَلَا يَحْيَوْنَ وَلَكِنْ نَاسٌ أَصَابَتْهُمْ النَّارُ بِذُنُوبِهِمْ ‏ ‏أَوْ قَالَ بِخَطَايَاهُمْ ‏ ‏فَأَمَاتَهُمْ إِمَاتَةً حَتَّى إِذَا كَانُوا فَحْمًا أُذِنَ بِالشَّفَاعَةِ فَجِيءَ بِهِمْ ‏ ‏ضَبَائِرَ ‏ ‏ضَبَائِرَ ‏ ‏فَبُثُّوا ‏ ‏عَلَى أَنْهَارِ الْجَنَّةِ ثُمَّ قِيلَ يَا أَهْلَ الْجَنَّةِ أَفِيضُوا عَلَيْهِمْ فَيَنْبُتُونَ نَبَاتَ الْحِبَّةِ تَكُونُ فِي ‏ ‏حَمِيلِ ‏ ‏السَّيْلِ فَقَالَ رَجُلٌ مِنْ الْقَوْمِ كَأَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ كَانَ ‏ ‏بِالْبَادِيَةِ ‏ ‏و حَدَّثَنَاه ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏وَابْنُ بَشَّارٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي مَسْلَمَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ إِلَى قَوْلِهِ فِي ‏ ‏حَمِيلِ ‏ ‏السَّيْلِ وَلَمْ يَذْكُرْ مَا بَعْدَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6d84ee8b-0b99-5882-b532-52d5bdbd9a66', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '272', '‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ الْحَنْظَلِيُّ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏عُثْمَانُ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبِيدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي لَأَعْلَمُ آخِرَ أَهْلِ النَّارِ خُرُوجًا مِنْهَا وَآخِرَ أَهْلِ الْجَنَّةِ دُخُولًا الْجَنَّةَ رَجُلٌ يَخْرُجُ مِنْ النَّارِ حَبْوًا فَيَقُولُ اللَّهُ تَبَارَكَ وَتَعَالَى لَهُ اذْهَبْ فَادْخُلْ الْجَنَّةَ فَيَأْتِيهَا فَيُخَيَّلُ إِلَيْهِ أَنَّهَا مَلْأَى فَيَرْجِعُ فَيَقُولُ يَا رَبِّ وَجَدْتُهَا مَلْأَى فَيَقُولُ اللَّهُ تَبَارَكَ وَتَعَالَى لَهُ اذْهَبْ فَادْخُلْ الْجَنَّةَ قَالَ فَيَأْتِيهَا فَيُخَيَّلُ إِلَيْهِ أَنَّهَا مَلْأَى فَيَرْجِعُ فَيَقُولُ يَا رَبِّ وَجَدْتُهَا مَلْأَى فَيَقُولُ اللَّهُ لَهُ اذْهَبْ فَادْخُلْ الْجَنَّةَ فَإِنَّ لَكَ مِثْلَ الدُّنْيَا وَعَشَرَةَ أَمْثَالِهَا ‏ ‏أَوْ إِنَّ لَكَ عَشَرَةَ أَمْثَالِ الدُّنْيَا ‏ ‏قَالَ فَيَقُولُ أَتَسْخَرُ بِي ‏ ‏أَوْ أَتَضْحَكُ بِي ‏ ‏وَأَنْتَ الْمَلِكُ قَالَ لَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَحِكَ حَتَّى بَدَتْ ‏ ‏نَوَاجِذُهُ ‏ ‏قَالَ فَكَانَ يُقَالُ ذَاكَ أَدْنَى أَهْلِ الْجَنَّةِ مَنْزِلَةً ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0055db5f-b208-5fda-a85e-b2b27537db3b', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '273', '‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَأَبُو كُرَيْبٍ ‏ ‏وَاللَّفْظُ ‏ ‏لِأَبِي كُرَيْبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبِيدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي لَأَعْرِفُ آخَرُ أَهْلِ النَّارِ خُرُوجًا مِنْ النَّارِ رَجُلٌ يَخْرُجُ مِنْهَا زَحْفًا فَيُقَالُ لَهُ انْطَلِقْ فَادْخُلْ الْجَنَّةَ قَالَ فَيَذْهَبُ فَيَدْخُلُ الْجَنَّةَ فَيَجِدُ النَّاسَ قَدْ أَخَذُوا الْمَنَازِلَ فَيُقَالُ لَهُ أَتَذْكُرُ الزَّمَانَ الَّذِي كُنْتَ فِيهِ فَيَقُولُ نَعَمْ فَيُقَالُ لَهُ تَمَنَّ فَيَتَمَنَّى فَيُقَالُ لَهُ لَكَ الَّذِي تَمَنَّيْتَ وَعَشَرَةَ أَضْعَافِ الدُّنْيَا قَالَ فَيَقُولُ أَتَسْخَرُ بِي وَأَنْتَ الْمَلِكُ قَالَ فَلَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَحِكَ حَتَّى بَدَتْ ‏ ‏نَوَاجِذُهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fda9a120-4b13-537e-aa0a-4d4b7a65f3e7', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '274', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏آخِرُ مَنْ يَدْخُلُ الْجَنَّةَ رَجُلٌ فَهْوَ يَمْشِي مَرَّةً ‏ ‏وَيَكْبُو ‏ ‏مَرَّةً وَتَسْفَعُهُ النَّارُ مَرَّةً فَإِذَا مَا جَاوَزَهَا الْتَفَتَ إِلَيْهَا فَقَالَ تَبَارَكَ الَّذِي نَجَّانِي مِنْكِ لَقَدْ أَعْطَانِي اللَّهُ شَيْئًا مَا أَعْطَاهُ أَحَدًا مِنْ الْأَوَّلِينَ وَالْآخِرِينَ فَتُرْفَعُ لَهُ شَجَرَةٌ فَيَقُولُ أَيْ رَبِّ أَدْنِنِي مِنْ هَذِهِ الشَّجَرَةِ فَلِأَسْتَظِلَّ بِظِلِّهَا وَأَشْرَبَ مِنْ مَائِهَا فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ يَا ابْنَ ‏ ‏آدَمَ ‏ ‏لَعَلِّي إِنَّ أَعْطَيْتُكَهَا سَأَلْتَنِي غَيْرَهَا فَيَقُولُ لَا يَا رَبِّ وَيُعَاهِدُهُ أَنْ لَا يَسْأَلَهُ غَيْرَهَا وَرَبُّهُ يَعْذِرُهُ لِأَنَّهُ يَرَى مَا لَا صَبْرَ لَهُ عَلَيْهِ ‏ ‏فَيُدْنِيهِ ‏ ‏مِنْهَا فَيَسْتَظِلُّ بِظِلِّهَا وَيَشْرَبُ مِنْ مَائِهَا ثُمَّ تُرْفَعُ لَهُ شَجَرَةٌ هِيَ أَحْسَنُ مِنْ الْأُولَى فَيَقُولُ أَيْ رَبِّ أَدْنِنِي مِنْ هَذِهِ لِأَشْرَبَ مِنْ مَائِهَا وَأَسْتَظِلَّ بِظِلِّهَا لَا أَسْأَلُكَ غَيْرَهَا فَيَقُولُ يَا ابْنَ ‏ ‏آدَمَ ‏ ‏أَلَمْ تُعَاهِدْنِي أَنْ لَا تَسْأَلَنِي غَيْرَهَا فَيَقُولُ لَعَلِّي إِنْ أَدْنَيْتُكَ مِنْهَا تَسْأَلُنِي غَيْرَهَا فَيُعَاهِدُهُ أَنْ لَا يَسْأَلَهُ غَيْرَهَا وَرَبُّهُ يَعْذِرُهُ لِأَنَّهُ يَرَى مَا لَا صَبْرَ لَهُ عَلَيْهِ ‏ ‏فَيُدْنِيهِ مِنْهَا فَيَسْتَظِلُّ بِظِلِّهَا وَيَشْرَبُ مِنْ مَائِهَا ثُمَّ تُرْفَعُ لَهُ شَجَرَةٌ عِنْدَ بَابِ الْجَنَّةِ هِيَ أَحْسَنُ مِنْ الْأُولَيَيْنِ فَيَقُولُ أَيْ رَبِّ أَدْنِنِي مِنْ هَذِهِ لِأَسْتَظِلَّ بِظِلِّهَا وَأَشْرَبَ مِنْ مَائِهَا لَا أَسْأَلُكَ غَيْرَهَا فَيَقُولُ يَا ابْنَ ‏ ‏آدَمَ ‏ ‏أَلَمْ تُعَاهِدْنِي أَنْ لَا تَسْأَلَنِي غَيْرَهَا قَالَ بَلَى يَا رَبِّ هَذِهِ لَا أَسْأَلُكَ غَيْرَهَا وَرَبُّهُ يَعْذِرُهُ لِأَنَّهُ يَرَى مَا لَا صَبْرَ لَهُ عَلَيْهَا ‏ ‏فَيُدْنِيهِ مِنْهَا فَإِذَا أَدْنَاهُ مِنْهَا فَيَسْمَعُ أَصْوَاتَ أَهْلِ الْجَنَّةِ فَيَقُولُ أَيْ رَبِّ أَدْخِلْنِيهَا فَيَقُولُ يَا ابْنَ ‏ ‏آدَمَ ‏ ‏مَا ‏ ‏يَصْرِينِي مِنْكَ ‏ ‏أَيُرْضِيكَ أَنْ أُعْطِيَكَ الدُّنْيَا وَمِثْلَهَا مَعَهَا قَالَ يَا رَبِّ أَتَسْتَهْزِئُ مِنِّي وَأَنْتَ رَبُّ الْعَالَمِينَ ‏ ‏فَضَحِكَ ‏ ‏ابْنُ مَسْعُودٍ ‏ ‏فَقَالَ أَلَا تَسْأَلُونِي مِمَّ أَضْحَكُ فَقَالُوا مِمَّ تَضْحَكُ قَالَ هَكَذَا ضَحِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا مِمَّ تَضْحَكُ يَا رَسُولَ اللَّهِ قَالَ مِنْ ضِحْكِ رَبِّ الْعَالَمِينَ حِينَ قَالَ أَتَسْتَهْزِئُ مِنِّي وَأَنْتَ رَبُّ الْعَالَمِينَ فَيَقُولُ إِنِّي لَا أَسْتَهْزِئُ مِنْكَ وَلَكِنِّي عَلَى مَا أَشَاءُ قَادِرٌ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1c671644-580b-5570-a36c-78d50f6311e4', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '275', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏النُّعْمَانِ بْنِ أَبِي عَيَّاشٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ أَدْنَى أَهْلِ الْجَنَّةِ مَنْزِلَةً رَجُلٌ صَرَفَ اللَّهُ وَجْهَهُ عَنْ النَّارِ قِبَلَ الْجَنَّةِ وَمَثَّلَ لَهُ شَجَرَةً ذَاتَ ظِلٍّ فَقَالَ أَيْ رَبِّ قَدِّمْنِي إِلَى هَذِهِ الشَّجَرَةِ أَكُونُ فِي ظِلِّهَا ‏ ‏وَسَاقَ الْحَدِيثَ بِنَحْوِ حَدِيثِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏وَلَمْ يَذْكُرْ فَيَقُولُ يَا ابْنَ ‏ ‏آدَمَ ‏ ‏مَا ‏ ‏يَصْرِينِي مِنْكَ إِلَى آخِرِ الْحَدِيثِ وَزَادَ فِيهِ وَيُذَكِّرُهُ اللَّهُ سَلْ كَذَا وَكَذَا فَإِذَا انْقَطَعَتْ بِهِ الْأَمَانِيُّ قَالَ اللَّهُ هُوَ لَكَ وَعَشَرَةُ أَمْثَالِهِ قَالَ ‏ ‏ثُمَّ يَدْخُلُ بَيْتَهُ فَتَدْخُلُ عَلَيْهِ زَوْجَتَاهُ مِنْ الْحُورِ الْعِينِ فَتَقُولَانِ الْحَمْدُ لِلَّهِ الَّذِي أَحْيَاكَ لَنَا وَأَحْيَانَا لَكَ قَالَ فَيَقُولُ مَا أُعْطِيَ أَحَدٌ مِثْلَ مَا أُعْطِيتُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e9374ea6-0bba-531f-97d3-352c469ea666', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '276', '‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَمْرٍو الْأَشْعَثِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏وَابْنِ أَبْجَرَ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْمُغِيرَةَ بْنَ شُعْبَةَ ‏ ‏رِوَايَةً ‏ ‏إِنْ شَاءَ اللَّهُ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏ابْنُ أَبِي عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏مُطَرِّفُ بْنُ طَرِيفٍ ‏ ‏وَعَبْدُ الْمَلِكِ بْنُ سَعِيدٍ ‏ ‏سَمِعَا ‏ ‏الشَّعْبِيَّ ‏ ‏يُخْبِرُ عَنْ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏قَالَ سَمِعْتُهُ ‏ ‏عَلَى الْمِنْبَرِ يَرْفَعُهُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏و حَدَّثَنِي ‏ ‏بِشْرُ بْنُ الْحَكَمِ ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُطَرِّفٌ ‏ ‏وَابْنُ أَبْجَرَ ‏ ‏سَمِعَا ‏ ‏الشَّعْبِيَّ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏الْمُغِيرَةَ بْنَ شُعْبَةَ ‏ ‏يُخْبِرُ بِهِ النَّاسَ عَلَى الْمِنْبَرِ قَالَ ‏ ‏سُفْيَانُ ‏ ‏رَفَعَهُ أَحَدُهُمَا أُرَاهُ ‏ ‏ابْنَ أَبْجَرَ ‏ ‏قَالَ ‏ ‏سَأَلَ ‏ ‏مُوسَى ‏ ‏رَبَّهُ ‏ ‏مَا أَدْنَى أَهْلِ الْجَنَّةِ مَنْزِلَةً قَالَ هُوَ رَجُلٌ يَجِيءُ بَعْدَ مَا أُدْخِلَ أَهْلُ الْجَنَّةِ الْجَنَّةَ فَيُقَالُ لَهُ ادْخُلْ الْجَنَّةَ فَيَقُولُ أَيْ رَبِّ كَيْفَ وَقَدْ نَزَلَ النَّاسُ مَنَازِلَهُمْ وَأَخَذُوا ‏ ‏أَخَذَاتِهِمْ ‏ ‏فَيُقَالُ لَهُ ‏ ‏أَتَرْضَى أَنْ يَكُونَ لَكَ مِثْلُ مُلْكِ مَلِكٍ مِنْ مُلُوكِ الدُّنْيَا فَيَقُولُ رَضِيتُ رَبِّ فَيَقُولُ لَكَ ذَلِكَ وَمِثْلُهُ وَمِثْلُهُ وَمِثْلُهُ وَمِثْلُهُ فَقَالَ فِي الْخَامِسَةِ رَضِيتُ رَبِّ فَيَقُولُ هَذَا لَكَ وَعَشَرَةُ أَمْثَالِهِ وَلَكَ مَا اشْتَهَتْ نَفْسُكَ وَلَذَّتْ عَيْنُكَ فَيَقُولُ رَضِيتُ رَبِّ قَالَ رَبِّ فَأَعْلَاهُمْ مَنْزِلَةً قَالَ أُولَئِكَ الَّذِينَ ‏ ‏أَرَدْتُ ‏ ‏غَرَسْتُ كَرَامَتَهُمْ بِيَدِي وَخَتَمْتُ عَلَيْهَا فَلَمْ تَرَ عَيْنٌ وَلَمْ تَسْمَعْ أُذُنٌ وَلَمْ يَخْطُرْ عَلَى قَلْبِ بَشَرٍ قَالَ وَمِصْدَاقُهُ فِي كِتَابِ اللَّهِ عَزَّ وَجَلَّ ‏ { ‏فَلَا تَعْلَمُ نَفْسٌ مَا أُخْفِيَ لَهُمْ مِنْ قُرَّةِ أَعْيُنٍ ‏} ‏الْآيَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ الْأَشْجَعِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ أَبْجَرَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الشَّعْبِيَّ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏الْمُغِيرَةَ بْنَ شُعْبَةَ ‏ ‏يَقُولُا ‏ ‏عَلَى الْمِنْبَرِ إِنَّ ‏ ‏مُوسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏سَأَلَ اللَّهَ عَزَّ وَجَلَّ عَنْ ‏ ‏أَخَسِّ ‏ ‏أَهْلِ الْجَنَّةِ مِنْهَا حَظًّا ‏ ‏وَسَاقَ الْحَدِيثَ بِنَحْوِهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('52f74588-ba86-5c7e-a8a9-a878ab64d5a9', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '277', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏الْمَعْرُورِ بْنِ سُوَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي ذَرٍّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي لَأَعْلَمُ آخِرَ أَهْلِ الْجَنَّةِ دُخُولًا الْجَنَّةَ وَآخِرَ أَهْلِ النَّارِ خُرُوجًا مِنْهَا رَجُلٌ يُؤْتَى بِهِ يَوْمَ الْقِيَامَةِ فَيُقَالُ اعْرِضُوا عَلَيْهِ صِغَارَ ذُنُوبِهِ وَارْفَعُوا عَنْهُ كِبَارَهَا فَتُعْرَضُ عَلَيْهِ صِغَارُ ذُنُوبِهِ فَيُقَالُ عَمِلْتَ يَوْمَ كَذَا وَكَذَا كَذَا وَكَذَا وَعَمِلْتَ يَوْمَ كَذَا وَكَذَا كَذَا وَكَذَا فَيَقُولُ نَعَمْ لَا يَسْتَطِيعُ أَنْ يُنْكِرَ وَهُوَ مُشْفِقٌ مِنْ كِبَارِ ذُنُوبِهِ أَنْ تُعْرَضَ عَلَيْهِ فَيُقَالُ لَهُ فَإِنَّ لَكَ مَكَانَ كُلِّ سَيِّئَةٍ حَسَنَةً فَيَقُولُ رَبِّ قَدْ عَمِلْتُ أَشْيَاءَ لَا أَرَاهَا هَا هُنَا فَلَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَحِكَ حَتَّى بَدَتْ ‏ ‏نَوَاجِذُهُ ‏ ‏و حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏وَوَكِيعٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏بِهَذَا الْإِسْنَادِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ea6354f0-0fb9-5308-bb72-90c40583230f', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '278', '‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏وَإِسْحَقُ بْنُ مَنْصُورٍ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏رَوْحٍ ‏ ‏قَالَ ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحُ بْنُ عُبَادَةَ الْقَيْسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يُسْأَلُ عَنْ الْوُرُودِ فَقَالَ ‏ ‏نَجِيءُ نَحْنُ يَوْمَ الْقِيَامَةِ عَنْ كَذَا وَكَذَا انْظُرْ أَيْ ذَلِكَ فَوْقَ النَّاسِ قَالَ ‏ ‏فَتُدْعَى الْأُمَمُ بِأَوْثَانِهَا وَمَا كَانَتْ تَعْبُدُ الْأَوَّلُ فَالْأَوَّلُ ثُمَّ يَأْتِينَا رَبُّنَا بَعْدَ ذَلِكَ فَيَقُولُ مَنْ تَنْظُرُونَ فَيَقُولُونَ نَنْظُرُ رَبَّنَا فَيَقُولُ أَنَا رَبُّكُمْ فَيَقُولُونَ حَتَّى نَنْظُرَ إِلَيْكَ ‏ ‏فَيَتَجَلَّى لَهُمْ يَضْحَكُ قَالَ فَيَنْطَلِقُ بِهِمْ وَيَتَّبِعُونَهُ وَيُعْطَى كُلُّ إِنْسَانٍ مِنْهُمْ مُنَافِقٍ أَوْ مُؤْمِنٍ نُورًا ثُمَّ يَتَّبِعُونَهُ وَعَلَى جِسْرِ جَهَنَّمَ ‏ ‏كَلَالِيبُ ‏ ‏وَحَسَكٌ ‏ ‏تَأْخُذُ مَنْ شَاءَ اللَّهُ ثُمَّ يُطْفَأُ نُورُ الْمُنَافِقِينَ ثُمَّ يَنْجُو الْمُؤْمِنُونَ ‏ ‏فَتَنْجُو أَوَّلُ ‏ ‏زُمْرَةٍ ‏ ‏وُجُوهُهُمْ كَالْقَمَرِ لَيْلَةَ الْبَدْرِ سَبْعُونَ أَلْفًا لَا يُحَاسَبُونَ ثُمَّ الَّذِينَ يَلُونَهُمْ ‏ ‏كَأَضْوَإِ نَجْمٍ فِي السَّمَاءِ ثُمَّ كَذَلِكَ ثُمَّ تَحِلُّ الشَّفَاعَةُ وَيَشْفَعُونَ حَتَّى يَخْرُجَ مِنْ النَّارِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَكَانَ فِي قَلْبِهِ مِنْ الْخَيْرِ مَا يَزِنُ شَعِيرَةً فَيُجْعَلُونَ بِفِنَاءِ الْجَنَّةِ وَيَجْعَلُ أَهْلُ الْجَنَّةِ يَرُشُّونَ عَلَيْهِمْ الْمَاءَ حَتَّى يَنْبُتُوا نَبَاتَ الشَّيْءِ فِي السَّيْلِ وَيَذْهَبُ حُرَاقُهُ ثُمَّ يَسْأَلُ حَتَّى تُجْعَلَ لَهُ الدُّنْيَا وَعَشَرَةُ أَمْثَالِهَا مَعَهَا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5f62ded9-0142-5d3f-8d85-13c0981694f8', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '279', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏سَمِعَ ‏ ‏جَابِرًا ‏ ‏يَقُولُا ‏ ‏سَمِعَهُ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِأُذُنِهِ يَقُولُ ‏ ‏إِنَّ اللَّهَ يُخْرِجُ نَاسًا مِنْ النَّارِ فَيُدْخِلَهُمْ الْجَنَّةَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('47d8de10-b187-57d8-8795-d632e10070b2', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '280', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الرَّبِيعِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏قَالَ قُلْتُ ‏ ‏لِعَمْرِو بْنِ دِينَارٍ ‏ ‏أَسَمِعْتَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ يُخْرِجُ قَوْمًا مِنْ النَّارِ بِالشَّفَاعَةِ قَالَ نَعَمْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6137592a-cf55-5879-8e7c-3a6385081ade', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '281', '‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ الشَّاعِرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏قَيْسُ بْنُ سُلَيْمٍ الْعَنْبَرِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ الْفَقِيرُ ‏ ‏حَدَّثَنَا ‏ ‏جَابِرُ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ قَوْمًا يُخْرَجُونَ مِنْ النَّارِ يَحْتَرِقُونَ فِيهَا إِلَّا ‏ ‏دَارَاتِ ‏ ‏وُجُوهِهِمْ حَتَّى يَدْخُلُونَ الْجَنَّةَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a0c43869-cb24-549b-a001-f2b951897c94', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '282', '‏ ‏و حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ الشَّاعِرِ ‏ ‏حَدَّثَنَا ‏ ‏الْفَضْلُ بْنُ دُكَيْنٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَاصِمٍ يَعْنِي مُحَمَّدَ بْنَ أَبِي أَيُّوبَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ الْفَقِيرُ ‏ ‏قَالَ ‏ ‏كُنْتُ قَدْ ‏ ‏شَغَفَنِي ‏ ‏رَأْيٌ مِنْ رَأْيِ ‏ ‏الْخَوَارِجِ ‏ ‏فَخَرَجْنَا فِي عِصَابَةٍ ذَوِي عَدَدٍ نُرِيدُ أَنْ نَحُجَّ ثُمَّ نَخْرُجَ عَلَى النَّاسِ قَالَ فَمَرَرْنَا عَلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَإِذَا ‏ ‏جَابِرُ بْنُ عَبْدِ اللَّهِ ‏ ‏يُحَدِّثُ الْقَوْمَ جَالِسٌ إِلَى سَارِيَةٍ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَإِذَا هُوَ قَدْ ذَكَرَ ‏ ‏الْجَهَنَّمِيِّينَ قَالَ فَقُلْتُ لَهُ يَا صَاحِبَ رَسُولِ اللَّهِ مَا هَذَا الَّذِي تُحَدِّثُونَ وَاللَّهُ يَقُولُ ‏ { ‏إِنَّكَ مَنْ تُدْخِلْ النَّارَ فَقَدْ أَخْزَيْتَهُ ‏} ‏وَ ‏ { ‏كُلَّمَا أَرَادُوا أَنْ يَخْرُجُوا مِنْهَا أُعِيدُوا فِيهَا ‏} ‏فَمَا هَذَا الَّذِي تَقُولُونَ قَالَ فَقَالَ أَتَقْرَأُ الْقُرْآنَ قُلْتُ نَعَمْ قَالَ فَهَلْ سَمِعْتَ بِمَقَامِ ‏ ‏مُحَمَّدٍ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏يَعْنِي الَّذِي يَبْعَثُهُ اللَّهُ فِيهِ قُلْتُ نَعَمْ قَالَ ‏ ‏فَإِنَّهُ مَقَامُ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَحْمُودُ الَّذِي يُخْرِجُ اللَّهُ بِهِ مَنْ يُخْرِجُ قَالَ ثُمَّ ‏ ‏نَعَتَ ‏ ‏وَضْعَ الصِّرَاطِ وَمَرَّ النَّاسِ عَلَيْهِ قَالَ وَأَخَافُ أَنْ لَا أَكُونَ أَحْفَظُ ذَاكَ قَالَ غَيْرَ أَنَّهُ قَدْ زَعَمَ أَنَّ قَوْمًا يَخْرُجُونَ مِنْ النَّارِ بَعْدَ أَنْ يَكُونُوا فِيهَا قَالَ ‏ ‏يَعْنِي فَيَخْرُجُونَ كَأَنَّهُمْ عِيدَانُ السَّمَاسِمِ قَالَ فَيَدْخُلُونَ نَهَرًا مِنْ أَنْهَارِ الْجَنَّةِ فَيَغْتَسِلُونَ فِيهِ فَيَخْرُجُونَ كَأَنَّهُمْ الْقَرَاطِيسُ ‏ ‏فَرَجَعْنَا قُلْنَا وَيْحَكُمْ أَتُرَوْنَ الشَّيْخَ يَكْذِبُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَجَعْنَا فَلَا وَاللَّهِ مَا خَرَجَ مِنَّا غَيْرُ رَجُلٍ وَاحِدٍ أَوْ كَمَا قَالَ ‏ ‏أَبُو نُعَيْمٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d8ec96ab-1812-5fe3-8200-9b72c56907ea', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '283', '‏ ‏حَدَّثَنَا ‏ ‏هَدَّابُ بْنُ خَالِدٍ الْأَزْدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي عِمْرَانَ ‏ ‏وَثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَخْرُجُ مِنْ النَّارِ أَرْبَعَةٌ فَيُعْرَضُونَ عَلَى اللَّهِ فَيَلْتَفِتُ أَحَدُهُمْ فَيَقُولُ أَيْ رَبِّ إِذْ أَخْرَجْتَنِي مِنْهَا فَلَا تُعِدْنِي فِيهَا ‏ ‏فَيُنْجِيهِ اللَّهُ مِنْهَا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3a534b63-8db7-5a6c-afcb-e75058450271', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '284', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ فُضَيْلُ بْنُ حُسَيْنٍ الْجَحْدَرِيُّ ‏ ‏وَمُحَمَّدُ بْنُ عُبَيْدٍ الْغُبَرِيُّ ‏ ‏وَاللَّفْظُ ‏ ‏لِأَبِي كَامِلٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَجْمَعُ اللَّهُ النَّاسَ يَوْمَ الْقِيَامَةِ فَيَهْتَمُّونَ لِذَلِكَ ‏ ‏و قَالَ ‏ ‏ابْنُ عُبَيْدٍ ‏ ‏فَيُلْهَمُونَ لِذَلِكَ ‏ ‏فَيَقُولُونَ لَوْ اسْتَشْفَعْنَا عَلَى رَبِّنَا حَتَّى يُرِيحَنَا مِنْ مَكَانِنَا هَذَا قَالَ فَيَأْتُونَ ‏ ‏آدَمَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَقُولُونَ أَنْتَ ‏ ‏آدَمُ ‏ ‏أَبُو الْخَلْقِ خَلَقَكَ اللَّهُ بِيَدِهِ وَنَفَخَ فِيكَ مِنْ رُوحِهِ وَأَمَرَ الْمَلَائِكَةَ فَسَجَدُوا لَكَ اشْفَعْ لَنَا عِنْدَ رَبِّكَ حَتَّى يُرِيحَنَا مِنْ مَكَانِنَا هَذَا فَيَقُولُ لَسْتُ هُنَاكُمْ فَيَذْكُرُ خَطِيئَتَهُ الَّتِي أَصَابَ فَيَسْتَحْيِي رَبَّهُ مِنْهَا وَلَكِنْ ائْتُوا ‏ ‏نُوحًا ‏ ‏أَوَّلَ رَسُولٍ بَعَثَهُ اللَّهُ قَالَ فَيَأْتُونَ ‏ ‏نُوحًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَقُولُ لَسْتُ هُنَاكُمْ فَيَذْكُرُ خَطِيئَتَهُ الَّتِي أَصَابَ فَيَسْتَحْيِي رَبَّهُ مِنْهَا وَلَكِنْ ائْتُوا ‏ ‏إِبْرَاهِيمَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّذِي اتَّخَذَهُ اللَّهُ ‏ ‏خَلِيلًا ‏ ‏فَيَأْتُونَ ‏ ‏إِبْرَاهِيمَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَقُولُ لَسْتُ هُنَاكُمْ وَيَذْكُرُ خَطِيئَتَهُ الَّتِي أَصَابَ فَيَسْتَحْيِي رَبَّهُ مِنْهَا وَلَكِنْ ائْتُوا ‏ ‏مُوسَى ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّذِي كَلَّمَهُ اللَّهُ وَأَعْطَاهُ التَّوْرَاةَ قَالَ فَيَأْتُونَ ‏ ‏مُوسَى ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَقُولُ لَسْتُ هُنَاكُمْ وَيَذْكُرُ خَطِيئَتَهُ الَّتِي أَصَابَ فَيَسْتَحْيِي رَبَّهُ مِنْهَا وَلَكِنْ ائْتُوا ‏ ‏عِيسَى ‏ ‏رُوحَ اللَّهِ وَكَلِمَتَهُ فَيَأْتُونَ ‏ ‏عِيسَى ‏ ‏رُوحَ اللَّهِ وَكَلِمَتَهُ فَيَقُولُ لَسْتُ هُنَاكُمْ وَلَكِنْ ائْتُوا ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَبْدًا قَدْ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ وَمَا تَأَخَّرَ قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَأْتُونِي فَأَسْتَأْذِنُ عَلَى رَبِّي فَيُؤْذَنُ لِي فَإِذَا أَنَا رَأَيْتُهُ وَقَعْتُ سَاجِدًا فَيَدَعُنِي مَا شَاءَ اللَّهُ فَيُقَالُ يَا ‏ ‏مُحَمَّدُ ‏ ‏ارْفَعْ رَأْسَكَ قُلْ تُسْمَعْ سَلْ ‏ ‏تُعْطَهْ اشْفَعْ تُشَفَّعْ فَأَرْفَعُ رَأْسِي فَأَحْمَدُ رَبِّي بِتَحْمِيدٍ يُعَلِّمُنِيهِ رَبِّي ثُمَّ أَشْفَعُ فَيَحُدُّ لِي حَدًّا فَأُخْرِجُهُمْ مِنْ النَّارِ وَأُدْخِلُهُمْ الْجَنَّةَ ثُمَّ أَعُودُ فَأَقَعُ سَاجِدًا فَيَدَعُنِي مَا شَاءَ اللَّهُ أَنْ يَدَعَنِي ثُمَّ يُقَالُ ارْفَعْ رَأْسَكَ يَا ‏ ‏مُحَمَّدُ ‏ ‏قُلْ تُسْمَعْ سَلْ ‏ ‏تُعْطَهْ اشْفَعْ تُشَفَّعْ فَأَرْفَعُ رَأْسِي فَأَحْمَدُ رَبِّي بِتَحْمِيدٍ يُعَلِّمُنِيهِ ثُمَّ أَشْفَعُ فَيَحُدُّ لِي حَدًّا فَأُخْرِجَهُمْ مِنْ النَّارِ وَأُدْخِلُهُمْ الْجَنَّةَ ‏ ‏قَالَ فَلَا أَدْرِي فِي الثَّالِثَةِ أَوْ فِي الرَّابِعَةِ قَالَ ‏ ‏فَأَقُولُ يَا رَبِّ مَا بَقِيَ فِي النَّارِ إِلَّا مَنْ حَبَسَهُ الْقُرْآنُ أَيْ وَجَبَ عَلَيْهِ الْخُلُودُ ‏ ‏قَالَ ‏ ‏ابْنُ عُبَيْدٍ ‏ ‏فِي رِوَايَتِهِ ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏أَيْ وَجَبَ عَلَيْهِ الْخُلُودُ ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏وَمُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَجْتَمِعُ الْمُؤْمِنُونَ يَوْمَ الْقِيَامَةِ فَيَهْتَمُّونَ بِذَلِكَ ‏ ‏أَوْ يُلْهَمُونَ ذَلِكَ ‏ ‏بِمِثْلِ حَدِيثِ ‏ ‏أَبِي عَوَانَةَ ‏ ‏وَقَالَ فِي الْحَدِيثِ ثُمَّ آتِيهِ الرَّابِعَةَ ‏ ‏أَوْ أَعُودُ الرَّابِعَةَ ‏ ‏فَأَقُولُ يَا رَبِّ مَا بَقِيَ إِلَّا مَنْ حَبَسَهُ الْقُرْآنُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَجْمَعُ اللَّهُ الْمُؤْمِنِينَ يَوْمَ الْقِيَامَةِ فَيُلْهَمُونَ لِذَلِكَ بِمِثْلِ حَدِيثِهِمَا وَذَكَرَ فِي الرَّابِعَةِ فَأَقُولُ يَا رَبِّ مَا بَقِيَ فِي النَّارِ إِلَّا مَنْ حَبَسَهُ الْقُرْآنُ أَيْ وَجَبَ عَلَيْهِ الْخُلُودُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('62470621-bce9-5e5f-82f8-c2b473408a7f', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '285', '‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مِنْهَالٍ الضَّرِيرُ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏وَهِشَامٌ صَاحِبُ الدَّسْتَوَائِيِّ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏أَبُو غَسَّانَ الْمِسْمَعِيُّ ‏ ‏وَمُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُعَاذٌ وَهُوَ ابْنُ هِشَامٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَخْرُجُ مِنْ النَّارِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَكَانَ فِي قَلْبِهِ مِنْ الْخَيْرِ مَا ‏ ‏يَزِنُ ‏ ‏شَعِيرَةً ثُمَّ يَخْرُجُ مِنْ النَّارِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَكَانَ فِي قَلْبِهِ مِنْ الْخَيْرِ مَا يَزِنُ ‏ ‏بُرَّةً ‏ ‏ثُمَّ يَخْرُجُ مِنْ النَّارِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَكَانَ فِي قَلْبِهِ مِنْ الْخَيْرِ مَا يَزِنُ ذَرَّةً ‏ ‏زَادَ ‏ ‏ابْنُ مِنْهَالٍ ‏ ‏فِي رِوَايَتِهِ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏فَلَقِيتُ ‏ ‏شُعْبَةَ ‏ ‏فَحَدَّثْتُهُ بِالْحَدِيثِ ‏ ‏فَقَالَ ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا بِهِ ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْحَدِيثِ إِلَّا أَنَّ ‏ ‏شُعْبَةَ ‏ ‏جَعَلَ مَكَانَ الذَّرَّةِ ذُرَةً ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏صَحَّفَ فِيهَا ‏ ‏أَبُو بِسْطَامَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9c750d52-4cce-5269-bf00-a2eea6e991cc', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '286', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الرَّبِيعِ الْعَتَكِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَعْبَدُ بْنُ هِلَالٍ الْعَنَزِيُّ ‏ ‏ح ‏ ‏و حَدَّثَنَاه ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَعْبَدُ بْنُ هِلَالٍ الْعَنَزِيُّ ‏ ‏قَالَ ‏ ‏انْطَلَقْنَا إِلَى ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏وَتَشَفَّعْنَا ‏ ‏بِثَابِتٍ ‏ ‏فَانْتَهَيْنَا إِلَيْهِ وَهُوَ ‏ ‏يُصَلِّي الضُّحَى فَاسْتَأْذَنَ لَنَا ‏ ‏ثَابِتٌ ‏ ‏فَدَخَلْنَا عَلَيْهِ وَأَجْلَسَ ‏ ‏ثَابِتًا ‏ ‏مَعَهُ عَلَى سَرِيرِهِ فَقَالَ لَهُ يَا ‏ ‏أَبَا حَمْزَةَ ‏ ‏إِنَّ إِخْوَانَكَ مِنْ أَهْلِ ‏ ‏الْبَصْرَةِ ‏ ‏يَسْأَلُونَكَ أَنْ تُحَدِّثَهُمْ حَدِيثَ الشَّفَاعَةِ قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ يَوْمُ الْقِيَامَةِ ‏ ‏مَاجَ ‏ ‏النَّاسُ بَعْضُهُمْ إِلَى بَعْضٍ فَيَأْتُونَ ‏ ‏آدَمَ ‏ ‏فَيَقُولُونَ لَهُ اشْفَعْ لِذُرِّيَّتِكَ فَيَقُولُ لَسْتُ لَهَا وَلَكِنْ عَلَيْكُمْ ‏ ‏بِإِبْرَاهِيمَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَإِنَّهُ ‏ ‏خَلِيلُ ‏ ‏اللَّهِ فَيَأْتُونَ ‏ ‏إِبْرَاهِيمَ ‏ ‏فَيَقُولُ لَسْتُ لَهَا وَلَكِنْ عَلَيْكُمْ ‏ ‏بِمُوسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَإِنَّهُ كَلِيمُ اللَّهِ فَيُؤْتَى ‏ ‏مُوسَى ‏ ‏فَيَقُولُ لَسْتُ لَهَا وَلَكِنْ عَلَيْكُمْ ‏ ‏بِعِيسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَإِنَّهُ رُوحُ اللَّهِ وَكَلِمَتُهُ ‏ ‏فَيُؤتَى ‏ ‏عِيسَى ‏ ‏فَيَقُولُ لَسْتُ لَهَا وَلَكِنْ عَلَيْكُمْ ‏ ‏بِمُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأُوتَى فَأَقُولُ أَنَا لَهَا فَأَنْطَلِقُ فَأَسْتَأْذِنُ عَلَى رَبِّي فَيُؤْذَنُ لِي فَأَقُومُ بَيْنَ يَدَيْهِ فَأَحْمَدُهُ بِمَحَامِدَ لَا أَقْدِرُ عَلَيْهِ الْآنَ يُلْهِمُنِيهِ اللَّهُ ثُمَّ أَخِرُّ لَهُ سَاجِدًا فَيُقَالُ لِي يَا ‏ ‏مُحَمَّدُ ‏ ‏ارْفَعْ رَأْسَكَ وَقُلْ يُسْمَعْ لَكَ وَسَلْ ‏ ‏تُعْطَهْ وَاشْفَعْ تُشَفَّعْ فَأَقُولُ رَبِّ أُمَّتِي أُمَّتِي فَيُقَالُ انْطَلِقْ فَمَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ حَبَّةٍ مِنْ بُرَّةٍ أَوْ شَعِيرَةٍ مِنْ إِيمَانٍ فَأَخْرِجْهُ مِنْهَا فَأَنْطَلِقُ فَأَفْعَلُ ثُمَّ أَرْجِعُ إِلَى رَبِّي فَأَحْمَدُهُ بِتِلْكَ الْمَحَامِدِ ثُمَّ أَخِرُّ لَهُ سَاجِدًا فَيُقَالُ لِي يَا ‏ ‏مُحَمَّدُ ‏ ‏ارْفَعْ رَأْسَكَ وَقُلْ يُسْمَعْ لَكَ وَسَلْ ‏ ‏تُعْطَهْ وَاشْفَعْ تُشَفَّعْ فَأَقُولُ أُمَّتِي أُمَّتِي فَيُقَالُ لِي انْطَلِقْ فَمَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ حَبَّةٍ مِنْ ‏ ‏خَرْدَلٍ ‏ ‏مِنْ إِيمَانٍ فَأَخْرِجْهُ مِنْهَا فَأَنْطَلِقُ فَأَفْعَلُ ثُمَّ أَعُودُ إِلَى رَبِّي فَأَحْمَدُهُ بِتِلْكَ الْمَحَامِدِ ثُمَّ أَخِرُّ لَهُ سَاجِدًا فَيُقَالُ لِي يَا ‏ ‏مُحَمَّدُ ‏ ‏ارْفَعْ رَأْسَكَ وَقُلْ يُسْمَعْ لَكَ وَسَلْ ‏ ‏تُعْطَهْ وَاشْفَعْ تُشَفَّعْ فَأَقُولُ يَا رَبِّ أُمَّتِي أُمَّتِي فَيُقَالُ لِي انْطَلِقْ فَمَنْ كَانَ فِي قَلْبِهِ أَدْنَى أَدْنَى أَدْنَى مِنْ مِثْقَالِ حَبَّةٍ مِنْ ‏ ‏خَرْدَلٍ ‏ ‏مِنْ إِيمَانٍ فَأَخْرِجْهُ مِنْ النَّارِ فَأَنْطَلِقُ فَأَفْعَلُ ‏ ‏هَذَا حَدِيثُ ‏ ‏أَنَسٍ ‏ ‏الَّذِي أَنْبَأَنَا بِهِ فَخَرَجْنَا مِنْ عِنْدِهِ فَلَمَّا كُنَّا ‏ ‏بِظَهْرِ الْجَبَّانِ ‏ ‏قُلْنَا لَوْ مِلْنَا إِلَى ‏ ‏الْحَسَنِ ‏ ‏فَسَلَّمْنَا عَلَيْهِ وَهُوَ مُسْتَخْفٍ فِي دَارِ ‏ ‏أَبِي خَلِيفَةَ ‏ ‏قَالَ فَدَخَلْنَا عَلَيْهِ فَسَلَّمْنَا عَلَيْهِ فَقُلْنَا يَا ‏ ‏أَبَا سَعِيدٍ ‏ ‏جِئْنَا مِنْ عِنْدِ أَخِيكَ ‏ ‏أَبِي حَمْزَةَ ‏ ‏فَلَمْ نَسْمَعْ مِثْلَ حَدِيثٍ حَدَّثَنَاهُ فِي الشَّفَاعَةِ قَالَ ‏ ‏هِيَهِ فَحَدَّثْنَاهُ الْحَدِيثَ فَقَالَ ‏ ‏هِيَهِ قُلْنَا مَا زَادَنَا قَالَ ‏ ‏قَدْ حَدَّثَنَا بِهِ مُنْذُ عِشْرِينَ سَنَةً وَهُوَ يَوْمَئِذٍ جَمِيعٌ وَلَقَدْ تَرَكَ شَيْئًا مَا أَدْرِي أَنَسِيَ الشَّيْخُ أَوْ كَرِهَ أَنْ يُحَدِّثَكُمْ فَتَتَّكِلُوا قُلْنَا لَهُ حَدِّثْنَا فَضَحِكَ وَقَالَ ‏ { ‏خُلِقَ الْإِنْسَانُ مِنْ عَجَلٍ ‏} ‏مَا ذَكَرْتُ لَكُمْ هَذَا إِلَّا وَأَنَا أُرِيدُ أَنْ أُحَدِّثَكُمُوهُ ثُمَّ أَرْجِعُ إِلَى رَبِّي فِي الرَّابِعَةِ فَأَحْمَدُهُ بِتِلْكَ الْمَحَامِدِ ثُمَّ أَخِرُّ لَهُ سَاجِدًا فَيُقَالُ لِي يَا ‏ ‏مُحَمَّدُ ‏ ‏ارْفَعْ رَأْسَكَ وَقُلْ يُسْمَعْ لَكَ وَسَلْ تُعْطَ وَاشْفَعْ تُشَفَّعْ فَأَقُولُ يَا رَبِّ ائْذَنْ لِي فِيمَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ قَالَ لَيْسَ ذَاكَ لَكَ أَوْ قَالَ لَيْسَ ذَاكَ إِلَيْكَ وَلَكِنْ وَعِزَّتِي وَكِبْرِيَائِي وَعَظَمَتِي ‏ ‏وَجِبْرِيَائِي ‏ ‏لَأُخْرِجَنَّ مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ قَالَ فَأَشْهَدُ عَلَى ‏ ‏الْحَسَنِ ‏ ‏أَنَّهُ حَدَّثَنَا بِهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏أُرَاهُ قَالَ قَبْلَ عِشْرِينَ سَنَةً وَهُوَ يَوْمِئِذٍ جَمِيعٌ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ec5cd4c8-fc58-5ec1-a2ee-bf0d5054fa69', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '287', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَمُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ ‏ ‏وَاتَّفَقَا فِي سِيَاقِ الْحَدِيثِ إِلَّا مَا يَزِيدُ أَحَدُهُمَا مِنْ الْحَرْفِ بَعْدَ الْحَرْفِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو حَيَّانَ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا بِلَحْمٍ فَرُفِعَ إِلَيْهِ الذِّرَاعُ وَكَانَتْ تُعْجِبُهُ فَنَهَسَ مِنْهَا نَهْسَةً فَقَالَ ‏ ‏أَنَا سَيِّدُ النَّاسِ يَوْمَ الْقِيَامَةِ وَهَلْ تَدْرُونَ بِمَ ذَاكَ يَجْمَعُ اللَّهُ يَوْمَ الْقِيَامَةِ الْأَوَّلِينَ وَالْآخِرِينَ فِي ‏ ‏صَعِيدٍ ‏ ‏وَاحِدٍ فَيُسْمِعُهُمْ الدَّاعِي ‏ ‏وَيَنْفُذُهُمْ الْبَصَرُ ‏ ‏وَتَدْنُو الشَّمْسُ فَيَبْلُغُ النَّاسَ مِنْ الْغَمِّ ‏ ‏وَالْكَرْبِ ‏ ‏مَا لَا يُطِيقُونَ وَمَا لَا يَحْتَمِلُونَ فَيَقُولُ بَعْضُ النَّاسِ لِبَعْضٍ أَلَا تَرَوْنَ مَا أَنْتُمْ فِيهِ أَلَا تَرَوْنَ مَا قَدْ بَلَغَكُمْ أَلَا تَنْظُرُونَ مَنْ يَشْفَعُ لَكُمْ إِلَى رَبِّكُمْ فَيَقُولُ بَعْضُ النَّاسِ لِبَعْضٍ ائْتُوا ‏ ‏آدَمَ ‏ ‏فَيَأْتُونَ ‏ ‏آدَمَ ‏ ‏فَيَقُولُونَ يَا ‏ ‏آدَمُ ‏ ‏أَنْتَ أَبُو الْبَشَرِ خَلَقَكَ اللَّهُ بِيَدِهِ وَنَفَخَ فِيكَ مِنْ رُوحِهِ وَأَمَرَ الْمَلَائِكَةَ فَسَجَدُوا لَكَ اشْفَعْ لَنَا إِلَى رَبِّكَ أَلَا ‏ ‏تَرَى إِلَى مَا نَحْنُ فِيهِ أَلَا ‏ ‏تَرَى إِلَى مَا قَدْ بَلَغَنَا فَيَقُولُ ‏ ‏آدَمُ ‏ ‏إِنَّ رَبِّي غَضِبَ الْيَوْمَ غَضَبًا لَمْ يَغْضَبْ قَبْلَهُ مِثْلَهُ وَلَنْ يَغْضَبَ بَعْدَهُ مِثْلَهُ وَإِنَّهُ نَهَانِي عَنْ الشَّجَرَةِ فَعَصَيْتُهُ نَفْسِي نَفْسِي اذْهَبُوا إِلَى غَيْرِي اذْهَبُوا إِلَى ‏ ‏نُوحٍ ‏ ‏فَيَأْتُونَ ‏ ‏نُوحًا ‏ ‏فَيَقُولُونَ يَا ‏ ‏نُوحُ ‏ ‏أَنْتَ أَوَّلُ الرُّسُلِ إِلَى الْأَرْضِ وَسَمَّاكَ اللَّهُ عَبْدًا شَكُورًا اشْفَعْ لَنَا إِلَى رَبِّكَ أَلَا ‏ ‏تَرَى مَا نَحْنُ فِيهِ أَلَا ‏ ‏تَرَى مَا قَدْ بَلَغَنَا فَيَقُولُ لَهُمْ إِنَّ رَبِّي قَدْ غَضِبَ الْيَوْمَ غَضَبًا لَمْ يَغْضَبْ قَبْلَهُ مِثْلَهُ وَلَنْ يَغْضَبَ بَعْدَهُ مِثْلَهُ وَإِنَّهُ قَدْ كَانَتْ لِي دَعْوَةٌ دَعَوْتُ بِهَا عَلَى قَوْمِي نَفْسِي نَفْسِي اذْهَبُوا إِلَى ‏ ‏إِبْرَاهِيمَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَأْتُونَ ‏ ‏إِبْرَاهِيمَ ‏ ‏فَيَقُولُونَ أَنْتَ نَبِيُّ اللَّهِ ‏ ‏وَخَلِيلُهُ ‏ ‏مِنْ أَهْلِ الْأَرْضِ اشْفَعْ لَنَا إِلَى رَبِّكَ أَلَا ‏ ‏تَرَى إِلَى مَا نَحْنُ فِيهِ أَلَا ‏ ‏تَرَى إِلَى مَا قَدْ بَلَغَنَا فَيَقُولُ لَهُمْ ‏ ‏إِبْرَاهِيمُ ‏ ‏إِنَّ رَبِّي قَدْ غَضِبَ الْيَوْمَ غَضَبًا لَمْ يَغْضَبْ قَبْلَهُ مِثْلَهُ وَلَا يَغْضَبُ بَعْدَهُ مِثْلَهُ وَذَكَرَ كَذَبَاتِهِ نَفْسِي نَفْسِي اذْهَبُوا إِلَى غَيْرِي اذْهَبُوا إِلَى ‏ ‏مُوسَى ‏ ‏فَيَأْتُونَ ‏ ‏مُوسَى ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَقُولُونَ يَا ‏ ‏مُوسَى ‏ ‏أَنْتَ رَسُولُ اللَّهِ فَضَّلَكَ اللَّهُ بِرِسَالَاتِهِ وَبِتَكْلِيمِهِ عَلَى النَّاسِ اشْفَعْ لَنَا إِلَى رَبِّكَ أَلَا ‏ ‏تَرَى إِلَى مَا نَحْنُ فِيهِ أَلَا ‏ ‏تَرَى مَا قَدْ بَلَغَنَا فَيَقُولُ لَهُمْ ‏ ‏مُوسَى ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ رَبِّي قَدْ غَضِبَ الْيَوْمَ غَضَبًا لَمْ يَغْضَبْ قَبْلَهُ مِثْلَهُ وَلَنْ يَغْضَبَ بَعْدَهُ مِثْلَهُ وَإِنِّي قَتَلْتُ نَفْسًا لَمْ أُومَرْ بِقَتْلِهَا نَفْسِي نَفْسِي اذْهَبُوا إِلَى ‏ ‏عِيسَى ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَأْتُونَ ‏ ‏عِيسَى ‏ ‏فَيَقُولُونَ يَا ‏ ‏عِيسَى ‏ ‏أَنْتَ رَسُولُ اللَّهِ وَكَلَّمْتَ النَّاسَ فِي الْمَهْدِ وَكَلِمَةٌ مِنْهُ أَلْقَاهَا إِلَى ‏ ‏مَرْيَمَ ‏ ‏وَرُوحٌ مِنْهُ فَاشْفَعْ لَنَا إِلَى رَبِّكَ أَلَا ‏ ‏تَرَى مَا نَحْنُ فِيهِ أَلَا ‏ ‏تَرَى مَا قَدْ بَلَغَنَا فَيَقُولُ لَهُمْ ‏ ‏عِيسَى ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ رَبِّي قَدْ غَضِبَ الْيَوْمَ غَضَبًا لَمْ يَغْضَبْ قَبْلَهُ مِثْلَهُ وَلَنْ يَغْضَبَ بَعْدَهُ مِثْلَهُ وَلَمْ يَذْكُرْ لَهُ ذَنْبًا نَفْسِي نَفْسِي اذْهَبُوا إِلَى غَيْرِي اذْهَبُوا إِلَى ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَأْتُونِّي فَيَقُولُونَ يَا ‏ ‏مُحَمَّدُ ‏ ‏أَنْتَ رَسُولُ اللَّهِ وَخَاتَمُ الْأَنْبِيَاءِ وَغَفَرَ اللَّهُ لَكَ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ اشْفَعْ لَنَا إِلَى رَبِّكَ أَلَا ‏ ‏تَرَى مَا نَحْنُ فِيهِ أَلَا ‏ ‏تَرَى مَا قَدْ بَلَغَنَا فَأَنْطَلِقُ فَآتِي تَحْتَ الْعَرْشِ فَأَقَعُ سَاجِدًا لِرَبِّي ثُمَّ يَفْتَحُ اللَّهُ عَلَيَّ وَيُلْهِمُنِي مِنْ مَحَامِدِهِ وَحُسْنِ الثَّنَاءِ عَلَيْهِ شَيْئًا لَمْ يَفْتَحْهُ لِأَحَدٍ قَبْلِي ثُمَّ يُقَالُ يَا ‏ ‏مُحَمَّدُ ‏ ‏ارْفَعْ رَأْسَكَ سَلْ ‏ ‏تُعْطَهْ اشْفَعْ تُشَفَّعْ فَأَرْفَعُ رَأْسِي فَأَقُولُ يَا رَبِّ أُمَّتِي أُمَّتِي فَيُقَالُ يَا ‏ ‏مُحَمَّدُ ‏ ‏أَدْخِلْ الْجَنَّةَ مِنْ أُمَّتِكَ مَنْ لَا حِسَابَ عَلَيْهِ مِنْ الْبَابِ الْأَيْمَنِ مِنْ أَبْوَابِ الْجَنَّةِ وَهُمْ شُرَكَاءُ النَّاسِ فِيمَا سِوَى ذَلِكَ مِنْ الْأَبْوَابِ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ إِنَّ مَا بَيْنَ الْمِصْرَاعَيْنِ مِنْ ‏ ‏مَصَارِيعِ ‏ ‏الْجَنَّةِ لَكَمَا بَيْنَ ‏ ‏مَكَّةَ ‏ ‏وَهَجَرٍ ‏ ‏أَوْ كَمَا بَيْنَ ‏ ‏مَكَّةَ ‏ ‏وَبُصْرَى ‏ ‏و حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ الْقَعْقَاعِ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏وُضِعَتْ بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَصْعَةٌ مِنْ ثَرِيدٍ وَلَحْمٍ فَتَنَاوَلَ الذِّرَاعَ وَكَانَتْ أَحَبَّ الشَّاةِ إِلَيْهِ فَنَهَسَ نَهْسَةً فَقَالَ أَنَا سَيِّدُ النَّاسِ يَوْمَ الْقِيَامَةِ ثُمَّ نَهَسَ أُخْرَى فَقَالَ أَنَا سَيِّدُ النَّاسِ يَوْمَ الْقِيَامَةِ فَلَمَّا رَأَى أَصْحَابَهُ لَا يَسْأَلُونَهُ قَالَ أَلَا تَقُولُونَ ‏ ‏كَيْفَهْ قَالُوا ‏ ‏كَيْفَهْ يَا رَسُولَ اللَّهِ قَالَ يَقُومُ النَّاسُ لِرَبِّ الْعَالَمِينَ وَسَاقَ الْحَدِيثَ بِمَعْنَى حَدِيثِ ‏ ‏أَبِي حَيَّانَ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏وَزَادَ فِي قِصَّةِ ‏ ‏إِبْرَاهِيمَ ‏ ‏فَقَالَ وَذَكَرَ قَوْلَهُ فِي الْكَوْكَبِ ‏ { ‏هَذَا رَبِّي ‏} ‏و قَوْله ‏ ‏لِآلِهَتِهِمْ ‏ { ‏بَلْ فَعَلَهُ كَبِيرُهُمْ هَذَا ‏} ‏و قَوْله ‏ { ‏إِنِّي سَقِيمٌ ‏} ‏قَالَ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ إِنَّ مَا بَيْنَ الْمِصْرَاعَيْنِ مِنْ مَصَارِيعِ الْجَنَّةِ إِلَى عِضَادَتَيْ الْبَابِ لَكَمَا بَيْنَ ‏ ‏مَكَّةَ ‏ ‏وَهَجَرٍ ‏ ‏أَوْ ‏ ‏هَجَرٍ ‏ ‏وَمَكَّةَ ‏ ‏قَالَ لَا أَدْرِي أَيَّ ذَلِكَ قَالَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b2216382-b48c-54f2-880b-25bb79436395', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '288', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ طَرِيفِ بْنِ خَلِيفَةَ الْبَجَلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَالِكٍ الْأَشْجَعِيُّ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَأَبُو مَالِكٍ ‏ ‏عَنْ ‏ ‏رِبْعِيٍّ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏قَالَا ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَجْمَعُ اللَّهُ تَبَارَكَ وَتَعَالَى النَّاسَ فَيَقُومُ الْمُؤْمِنُونَ حَتَّى ‏ ‏تُزْلَفَ ‏ ‏لَهُمْ الْجَنَّةُ فَيَأْتُونَ ‏ ‏آدَمَ ‏ ‏فَيَقُولُونَ يَا أَبَانَا اسْتَفْتِحْ لَنَا الْجَنَّةَ فَيَقُولُ وَهَلْ أَخْرَجَكُمْ مِنْ الْجَنَّةِ إِلَّا خَطِيئَةُ أَبِيكُمْ ‏ ‏آدَمَ ‏ ‏لَسْتُ بِصَاحِبِ ذَلِكَ اذْهَبُوا إِلَى ابْنِي ‏ ‏إِبْرَاهِيمَ ‏ ‏خَلِيلِ ‏ ‏اللَّهِ قَالَ فَيَقُولُ ‏ ‏إِبْرَاهِيمُ ‏ ‏لَسْتُ بِصَاحِبِ ذَلِكَ إِنَّمَا كُنْتُ خَلِيلًا مِنْ وَرَاءَ وَرَاءَ اعْمِدُوا إِلَى ‏ ‏مُوسَى ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّذِي كَلَّمَهُ اللَّهُ تَكْلِيمًا فَيَأْتُونَ ‏ ‏مُوسَى ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَقُولُ لَسْتُ بِصَاحِبِ ذَلِكَ اذْهَبُوا إِلَى ‏ ‏عِيسَى ‏ ‏كَلِمَةِ اللَّهِ وَرُوحِهِ فَيَقُولُ ‏ ‏عِيسَى ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَسْتُ بِصَاحِبِ ذَلِكَ فَيَأْتُونَ ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَقُومُ فَيُؤْذَنُ لَهُ وَتُرْسَلُ الْأَمَانَةُ وَالرَّحِمُ فَتَقُومَانِ جَنَبَتَيْ الصِّرَاطِ يَمِينًا وَشِمَالًا فَيَمُرُّ أَوَّلُكُمْ كَالْبَرْقِ قَالَ قُلْتُ بِأَبِي أَنْتَ وَأُمِّي أَيُّ شَيْءٍ كَمَرِّ الْبَرْقِ قَالَ أَلَمْ تَرَوْا إِلَى الْبَرْقِ كَيْفَ يَمُرُّ وَيَرْجِعُ فِي طَرْفَةِ عَيْنٍ ثُمَّ كَمَرِّ الرِّيحِ ثُمَّ كَمَرِّ الطَّيْرِ ‏ ‏وَشَدِّ ‏ ‏الرِّجَالِ ‏ ‏تَجْرِي بِهِمْ أَعْمَالُهُمْ وَنَبِيُّكُمْ قَائِمٌ عَلَى الصِّرَاطِ يَقُولُ رَبِّ سَلِّمْ سَلِّمْ حَتَّى تَعْجِزَ أَعْمَالُ الْعِبَادِ حَتَّى يَجِيءَ الرَّجُلُ فَلَا يَسْتَطِيعُ السَّيْرَ إِلَّا زَحْفًا قَالَ وَفِي حَافَتَيْ الصِّرَاطِ ‏ ‏كَلَالِيبُ ‏ ‏مُعَلَّقَةٌ مَأْمُورَةٌ بِأَخْذِ مَنْ أُمِرَتْ بِهِ ‏ ‏فَمَخْدُوشٌ ‏ ‏نَاجٍ ‏ ‏وَمَكْدُوسٌ ‏ ‏فِي النَّارِ وَالَّذِي نَفْسُ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏بِيَدِهِ إِنَّ قَعْرَ جَهَنَّمَ لَسَبْعُونَ خَرِيفًا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a895572c-9054-5faa-a420-cf0b66f124c9', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '289', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏الْمُخْتَارِ بْنِ فُلْفُلٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا أَوَّلُ النَّاسِ يَشْفَعُ فِي الْجَنَّةِ وَأَنَا أَكْثَرُ الْأَنْبِيَاءِ تَبَعًا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7402ac36-4c2f-598b-845f-2c0051d5abec', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '290', '‏ ‏و حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ هِشَامٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مُخْتَارِ بْنِ فُلْفُلٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا أَكْثَرُ الْأَنْبِيَاءِ تَبَعًا يَوْمَ الْقِيَامَةِ وَأَنَا أَوَّلُ مَنْ يَقْرَعُ بَابَ الْجَنَّةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ed0bc21c-c698-536b-93f1-43583397a58c', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '291', '‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏الْمُخْتَارِ بْنِ فُلْفُلٍ ‏ ‏قَالَ قَالَ ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا أَوَّلُ شَفِيعٍ فِي الْجَنَّةِ لَمْ يُصَدَّقْ نَبِيٌّ مِنْ الْأَنْبِيَاءِ مَا صُدِّقْتُ وَإِنَّ مِنْ الْأَنْبِيَاءِ نَبِيًّا مَا يُصَدِّقُهُ مِنْ أُمَّتِهِ إِلَّا رَجُلٌ وَاحِدٌ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d81fc2dc-b703-5aab-a90b-c9a59fe14b7d', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '292', '‏ ‏و حَدَّثَنِي ‏ ‏عَمْرٌو النَّاقِدُ ‏ ‏وَزُهَيْرُ بْنُ حَرْبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏آتِي بَابَ الْجَنَّةِ يَوْمَ الْقِيَامَةِ فَأَسْتَفْتِحُ فَيَقُولُ الْخَازِنُ مَنْ أَنْتَ فَأَقُولُ ‏ ‏مُحَمَّدٌ ‏ ‏فَيَقُولُ بِكَ أُمِرْتُ لَا أَفْتَحُ لِأَحَدٍ قَبْلَكَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('86769d5a-d7e9-5323-9183-13deb412e89f', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '293', '‏ ‏حَدَّثَنِي ‏ ‏يُونُسُ بْنُ عَبْدِ الْأَعْلَى ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِكُلِّ نَبِيٍّ دَعْوَةٌ ‏ ‏يَدْعُوهَا فَأُرِيدُ أَنْ أَخْتَبِئَ دَعْوَتِي شَفَاعَةً لِأُمَّتِي يَوْمَ الْقِيَامَةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('271fbe38-05ef-5908-a241-497808ff2360', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '294', '‏ ‏و حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏وَعَبْدُ بْنُ حُمَيْدٍ ‏ ‏قَالَ ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَخِي ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِكُلِّ نَبِيٍّ دَعْوَةٌ وَأَرَدْتُ إِنْ شَاءَ اللَّهُ أَنْ أَخْتَبِئَ دَعْوَتِي شَفَاعَةً لِأُمَّتِي يَوْمَ الْقِيَامَةِ ‏ ‏حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏وَعَبْدُ بْنُ حُمَيْدٍ ‏ ‏قَالَ ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَخِي ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ أَبِي سُفْيَانَ بْنِ أَسِيدِ بْنِ جَارِيَةَ الثَّقَفِيُّ ‏ ‏مِثْلَ ذَلِكَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1c33f664-977f-5148-b459-7dbc2f1cd7d1', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '295', '‏ ‏و حَدَّثَنِي ‏ ‏حَرْمَلَةُ بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَنَّ ‏ ‏عَمْرَو بْنَ أَبِي سُفْيَانَ بْنِ أَسِيدِ بْنِ جَارِيَةَ الثَّقَفِيَّ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لِكَعْبِ الْأَحْبَارِ ‏ ‏إِنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِكُلِّ نَبِيٍّ دَعْوَةٌ ‏ ‏يَدْعُوهَا فَأَنَا أُرِيدُ إِنْ شَاءَ اللَّهُ أَنْ أَخْتَبِئَ دَعْوَتِي شَفَاعَةً لِأُمَّتِي يَوْمَ الْقِيَامَةِ ‏ ‏فَقَالَ ‏ ‏كَعْبٌ ‏ ‏لِأَبِي هُرَيْرَةَ ‏ ‏أَنْتَ سَمِعْتَ هَذَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏نَعَمْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('038d158d-6a97-5d93-b7f3-093c71a1688d', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '296', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَأَبُو كُرَيْبٍ ‏ ‏وَاللَّفْظُ ‏ ‏لِأَبِي كُرَيْبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِكُلِّ نَبِيٍّ دَعْوَةٌ مُسْتَجَابَةٌ فَتَعَجَّلَ كُلُّ نَبِيٍّ دَعْوَتَهُ وَإِنِّي اخْتَبَأْتُ دَعْوَتِي شَفَاعَةً لِأُمَّتِي يَوْمَ الْقِيَامَةِ فَهِيَ نَائِلَةٌ إِنْ شَاءَ اللَّهُ مَنْ مَاتَ مِنْ أُمَّتِي لَا يُشْرِكُ بِاللَّهِ شَيْئًا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a89d3190-71c9-5774-9f59-626f77b59757', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '297', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏عُمَارَةَ وَهُوَ ابْنُ الْقَعْقَاعِ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِكُلِّ نَبِيٍّ دَعْوَةٌ مُسْتَجَابَةٌ يَدْعُو بِهَا فَيُسْتَجَابُ لَهُ ‏ ‏فَيُؤْتَاهَا وَإِنِّي اخْتَبَأْتُ دَعْوَتِي شَفَاعَةً لِأُمَّتِي يَوْمَ الْقِيَامَةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ed7e614f-e40b-5eac-b1e8-0e5aa3597d60', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '298', '‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ الْعَنْبَرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ وَهُوَ ابْنُ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُا ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِكُلِّ نَبِيٍّ دَعْوَةٌ دَعَا بِهَا فِي أُمَّتِهِ فَاسْتُجِيبَ لَهُ وَإِنِّي أُرِيدُ إِنْ شَاءَ اللَّهُ أَنْ أُؤَخِّرَ دَعْوَتِي شَفَاعَةً لِأُمَّتِي يَوْمَ الْقِيَامَةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9fc34547-d5e5-5cb5-9039-86e9f900e941', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '299', '‏ ‏حَدَّثَنِي ‏ ‏أَبُو غَسَّانَ الْمِسْمَعِيُّ ‏ ‏وَمُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏وَابْنُ بَشَّارٍ ‏ ‏حَدَّثَانَا ‏ ‏وَاللَّفْظُ ‏ ‏لِأَبِي غَسَّانَ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏مُعَاذٌ يَعْنُونَ ابْنَ هِشَامٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِكُلِّ نَبِيٍّ دَعْوَةٌ دَعَاهَا لِأُمَّتِهِ وَإِنِّي اخْتَبَأْتُ دَعْوَتِي شَفَاعَةً لِأُمَّتِي يَوْمَ الْقِيَامَةِ ‏ ‏و حَدَّثَنِيهِ ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏وَابْنُ أَبِي خَلَفٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏ح ‏ ‏و حَدَّثَنِيهِ ‏ ‏إِبْرَاهِيمُ بْنُ سَعِيدٍ الْجَوْهَرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏مِسْعَرٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏غَيْرَ أَنَّ فِي حَدِيثِ ‏ ‏وَكِيعٍ ‏ ‏قَالَ قَالَ أُعْطِيَ ‏ ‏وَفِي حَدِيثِ ‏ ‏أَبِي أُسَامَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الْأَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏الْمُعْتَمِرُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَذَكَرَ نَحْوَ حَدِيثِ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f498becb-f9a9-5908-98e7-ff893a92585e', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '300', '‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ أَحْمَدَ بْنِ أَبِي خَلَفٍ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُا ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِكُلِّ نَبِيٍّ دَعْوَةٌ قَدْ دَعَا بِهَا فِي أُمَّتِهِ وَخَبَأْتُ دَعْوَتِي شَفَاعَةً لِأُمَّتِي يَوْمَ الْقِيَامَةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('06487dcd-c693-5757-9b0f-b57ba0b02f2f', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '301', '‏ ‏حَدَّثَنِي ‏ ‏يُونُسُ بْنُ عَبْدِ الْأَعْلَى الصَّدَفِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏أَنَّ ‏ ‏بَكْرَ بْنَ سَوَادَةَ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَلَا قَوْلَ اللَّهِ عَزَّ وَجَلَّ فِي ‏ ‏إِبْرَاهِيمَ ‏ { ‏رَبِّ إِنَّهُنَّ أَضْلَلْنَ كَثِيرًا مِنْ النَّاسِ فَمَنْ تَبِعَنِي فَإِنَّهُ مِنِّي ‏} ‏الْآيَةَ وَقَالَ ‏ ‏عِيسَى ‏ ‏عَلَيْهِ السَّلَام ‏ { ‏إِنْ تُعَذِّبْهُمْ فَإِنَّهُمْ عِبَادُكَ وَإِنْ تَغْفِرْ لَهُمْ فَإِنَّكَ أَنْتَ الْعَزِيزُ الْحَكِيمُ ‏} ‏فَرَفَعَ يَدَيْهِ وَقَالَ اللَّهُمَّ أُمَّتِي أُمَّتِي وَبَكَى فَقَالَ اللَّهُ عَزَّ وَجَلَّ يَا ‏ ‏جِبْرِيلُ ‏ ‏اذْهَبْ إِلَى ‏ ‏مُحَمَّدٍ ‏ ‏وَرَبُّكَ أَعْلَمُ فَسَلْهُ مَا يُبْكِيكَ فَأَتَاهُ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَسَأَلَهُ فَأَخْبَرَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَا قَالَ وَهُوَ أَعْلَمُ فَقَالَ اللَّهُ ‏ ‏يَا ‏ ‏جِبْرِيلُ ‏ ‏اذْهَبْ إِلَى ‏ ‏مُحَمَّدٍ ‏ ‏فَقُلْ إِنَّا ‏ ‏سَنُرْضِيكَ فِي أُمَّتِكَ وَلَا نَسُوءُكَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('146cc66f-3c60-5d37-a6c2-660a97154d19', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '302', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَجُلًا قَالَ يَا رَسُولَ اللَّهِ أَيْنَ أَبِي قَالَ فِي النَّارِ فَلَمَّا ‏ ‏قَفَّى ‏ ‏دَعَاهُ فَقَالَ ‏ ‏إِنَّ أَبِي وَأَبَاكَ فِي النَّارِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c688a449-69fe-5ca5-b3fe-705fc416eba8', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '303', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏وَزُهَيْرُ بْنُ حَرْبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لَمَّا أُنْزِلَتْ هَذِهِ الْآيَةُ ‏ { ‏وَأَنْذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ ‏} ‏دَعَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُرَيْشًا ‏ ‏فَاجْتَمَعُوا فَعَمَّ وَخَصَّ فَقَالَ ‏ ‏يَا ‏ ‏بَنِي كَعْبِ بْنِ لُؤَيٍّ ‏ ‏أَنْقِذُوا أَنْفُسَكُمْ مِنْ النَّارِ يَا ‏ ‏بَنِي مُرَّةَ بنِ كَعْبٍ ‏ ‏أَنْقِذُوا أَنْفُسَكُمْ مِنْ النَّارِ يَا ‏ ‏بَنِي عَبْدِ شَمْسٍ ‏ ‏أَنْقِذُوا أَنْفُسَكُمْ مِنْ النَّارِ يَا ‏ ‏بَنِي عَبْدِ مَنَافٍ ‏ ‏أَنْقِذُوا أَنْفُسَكُمْ مِنْ النَّارِ يَا ‏ ‏بَنِي هَاشِمٍ ‏ ‏أَنْقِذُوا أَنْفُسَكُمْ مِنْ النَّارِ يَا ‏ ‏بَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏أَنْقِذُوا أَنْفُسَكُمْ مِنْ النَّارِ يَا ‏ ‏فَاطِمَةُ ‏ ‏أَنْقِذِي نَفْسَكِ مِنْ النَّارِ فَإِنِّي لَا أَمْلِكُ لَكُمْ مِنْ اللَّهِ شَيْئًا غَيْرَ أَنَّ لَكُمْ رَحِمًا ‏ ‏سَأَبُلُّهَا ‏ ‏بِبَلَالِهَا ‏ ‏و حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ الْقَوَارِيرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏وَحَدِيثُ ‏ ‏جَرِيرٍ ‏ ‏أَتَمُّ وَأَشْبَعُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f38ba721-3dff-5cb0-9221-09fbf0cd0325', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '304', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَيُونُسُ بْنُ بُكَيْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَمَّا نَزَلَتْ ‏ { ‏وَأَنْذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ ‏} ‏قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏الصَّفَا ‏ ‏فَقَالَ ‏ ‏يَا ‏ ‏فَاطِمَةُ بِنْتَ مُحَمَّدٍ ‏ ‏يَا ‏ ‏صَفِيَّةُ بِنْتَ عَبْدِ الْمُطَّلِبِ ‏ ‏يَا ‏ ‏بَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏لَا أَمْلِكُ لَكُمْ مِنْ اللَّهِ شَيْئًا سَلُونِي مِنْ مَالِي مَا شِئْتُمْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('66013852-21b9-5d92-ae68-4628fb751627', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '305', '‏ ‏و حَدَّثَنِي ‏ ‏حَرْمَلَةُ بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ الْمُسَيَّبِ ‏ ‏وَأَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ أُنْزِلَ عَلَيْهِ ‏ { ‏وَأَنْذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ ‏} ‏يَا مَعْشَرَ ‏ ‏قُرَيْشٍ ‏ ‏اشْتَرُوا أَنْفُسَكُمْ مِنْ اللَّهِ لَا ‏ ‏أُغْنِي عَنْكُمْ مِنْ اللَّهِ شَيْئًا يَا ‏ ‏بَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏لَا ‏ ‏أُغْنِي عَنْكُمْ مِنْ اللَّهِ شَيْئًا يَا ‏ ‏عَبَّاسَ بْنَ عَبْدِ الْمُطَّلِبِ ‏ ‏لَا ‏ ‏أُغْنِي عَنْكَ مِنْ اللَّهِ شَيْئًا يَا ‏ ‏صَفِيَّةُ ‏ ‏عَمَّةَ رَسُولِ اللَّهِ لَا ‏ ‏أُغْنِي عَنْكِ مِنْ اللَّهِ شَيْئًا يَا ‏ ‏فَاطِمَةُ ‏ ‏بِنْتَ رَسُولِ اللَّهِ سَلِينِي بِمَا شِئْتِ لَا ‏ ‏أُغْنِي عَنْكِ مِنْ اللَّهِ شَيْئًا ‏ ‏و حَدَّثَنِي ‏ ‏عَمْرٌو النَّاقِدُ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ ذَكْوَانَ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَ هَذَا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d2d3f70e-86b1-55d7-a66d-55c0bdcfef26', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '306', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ الْجَحْدَرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏قَبِيصَةَ بْنِ الْمُخَارِقِ ‏ ‏وَزُهَيْرِ بْنِ عَمْرٍو ‏ ‏قَالَا ‏ ‏لَمَّا نَزَلَتْ ‏ { ‏وَأَنْذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ ‏} ‏قَالَ انْطَلَقَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏رَضْمَةٍ ‏ ‏مِنْ جَبَلٍ فَعَلَا أَعْلَاهَا حَجَرًا ثُمَّ نَادَى ‏ ‏يَا ‏ ‏بَنِي عَبْدِ مَنَافَاهْ ‏ ‏إِنِّي نَذِيرٌ إِنَّمَا مَثَلِي وَمَثَلُكُمْ كَمَثَلِ رَجُلٍ رَأَى الْعَدُوَّ فَانْطَلَقَ ‏ ‏يَرْبَأُ ‏ ‏أَهْلَهُ فَخَشِيَ أَنْ يَسْبِقُوهُ فَجَعَلَ يَهْتِفُ ‏ ‏يَا ‏ ‏صَبَاحَاهْ ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الْأَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏الْمُعْتَمِرُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عُثْمَانَ ‏ ‏عَنْ ‏ ‏زُهَيْرِ بْنِ عَمْرٍو ‏ ‏وَقَبِيصَةَ بْنِ مُخَارِقٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِنَحْوِهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0de88eff-4ef7-5fbc-98bf-2f820b91375f', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '307', '‏ ‏و حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏وَأَنْذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ ‏} ‏وَرَهْطَكَ مِنْهُمْ الْمُخْلَصِينَ خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى صَعِدَ ‏ ‏الصَّفَا ‏ ‏فَهَتَفَ ‏ ‏يَا ‏ ‏صَبَاحَاهْ ‏ ‏فَقَالُوا مَنْ هَذَا الَّذِي يَهْتِفُ قَالُوا ‏ ‏مُحَمَّدٌ ‏ ‏فَاجْتَمَعُوا إِلَيْهِ فَقَالَ يَا بَنِي فُلَانٍ يَا بَنِي فُلَانٍ يَا بَنِي فُلَانٍ يَا ‏ ‏بَنِي عَبْدِ مَنَافٍ ‏ ‏يَا ‏ ‏بَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏فَاجْتَمَعُوا إِلَيْهِ فَقَالَ ‏ ‏أَرَأَيْتَكُمْ لَوْ أَخْبَرْتُكُمْ أَنَّ خَيْلًا تَخْرُجُ ‏ ‏بِسَفْحِ ‏ ‏هَذَا الْجَبَلِ أَكُنْتُمْ مُصَدِّقِيَّ قَالُوا مَا جَرَّبْنَا عَلَيْكَ كَذِبًا قَالَ فَإِنِّي نَذِيرٌ لَكُمْ بَيْنَ يَدَيْ عَذَابٍ شَدِيدٍ قَالَ فَقَالَ ‏ ‏أَبُو لَهَبٍ ‏ ‏تَبًّا لَكَ أَمَا جَمَعْتَنَا إِلَّا لِهَذَا ثُمَّ قَامَ فَنَزَلَتْ هَذِهِ السُّورَةُ ‏ ‏تَبَّتْ يَدَا ‏ ‏أَبِي لَهَبٍ ‏ ‏وَقَدْ ‏ ‏تَبَّ ‏ ‏كَذَا قَرَأَ ‏ ‏الْأَعْمَشُ ‏ ‏إِلَى آخِرِ السُّورَةِ ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَأَبُو كُرَيْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏قَالَ صَعِدَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ ‏ ‏الصَّفَا ‏ ‏فَقَالَ ‏ ‏يَا ‏ ‏صَبَاحَاهْ ‏ ‏بِنَحْوِ حَدِيثِ ‏ ‏أَبِي أُسَامَةَ ‏ ‏وَلَمْ يَذْكُرْ نُزُولَ الْآيَةِ ‏ { ‏وَأَنْذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ ‏}', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8f0bd211-d2e2-5e7e-be46-00e6789edc53', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '308', '‏ ‏و حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ الْقَوَارِيرِيُّ ‏ ‏وَمُحَمَّدُ بْنُ أَبِي بَكْرٍ الْمُقَدَّمِيُّ ‏ ‏وَمُحَمَّدُ بْنُ عَبْدِ الْمَلِكِ الْأُمَوِيُّ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ بْنِ نَوْفَلٍ ‏ ‏عَنْ ‏ ‏الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏أَنَّهُ قَالَ يَا رَسُولَ اللَّهِ هَلْ نَفَعْتَ ‏ ‏أَبَا طَالِبٍ ‏ ‏بِشَيْءٍ فَإِنَّهُ كَانَ ‏ ‏يَحُوطُكَ ‏ ‏وَيَغْضَبُ لَكَ قَالَ ‏ ‏نَعَمْ هُوَ فِي ‏ ‏ضَحْضَاحٍ ‏ ‏مِنْ نَارٍ وَلَوْلَا أَنَا لَكَانَ فِي ‏ ‏الدَّرْكِ ‏ ‏الْأَسْفَلِ مِنْ النَّارِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('81029961-d06b-5e79-88ae-344623eab87a', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '309', '‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْعَبَّاسَ ‏ ‏يَقُولُا ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏أَبَا طَالِبٍ ‏ ‏كَانَ ‏ ‏يَحُوطُكَ ‏ ‏وَيَنْصُرُكَ فَهَلْ نَفَعَهُ ذَلِكَ قَالَ ‏ ‏نَعَمْ وَجَدْتُهُ فِي ‏ ‏غَمَرَاتٍ ‏ ‏مِنْ النَّارِ فَأَخْرَجْتُهُ إِلَى ‏ ‏ضَحْضَاحٍ ‏ ‏و حَدَّثَنِيهِ ‏ ‏مُحَمَّدُ بْنُ حَاتِمٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏الْعَبَّاسُ بْنُ عَبْدِ الْمُطَّلِبِ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏بِهَذَا الْإِسْنَادِ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِنَحْوِ حَدِيثِ ‏ ‏أَبِي عَوَانَةَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ccfc67ee-7bd6-58ba-86a9-651cb5e4fa9b', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '310', '‏ ‏و حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏ابْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ خَبَّابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذُكِرَ عِنْدَهُ عَمُّهُ ‏ ‏أَبُو طَالِبٍ ‏ ‏فَقَالَ ‏ ‏لَعَلَّهُ تَنْفَعُهُ شَفَاعَتِي يَوْمَ الْقِيَامَةِ فَيُجْعَلُ فِي ‏ ‏ضَحْضَاحٍ ‏ ‏مِنْ نَارٍ يَبْلُغُ كَعْبَيْهِ يَغْلِي مِنْهُ دِمَاغُهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ed27b14a-25e5-59db-87c1-63241cf39194', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '311', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏النُّعْمَانِ بْنِ أَبِي عَيَّاشٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ أَدْنَى أَهْلِ النَّارِ عَذَابًا يَنْتَعِلُ بِنَعْلَيْنِ مِنْ نَارٍ يَغْلِي دِمَاغُهُ مِنْ حَرَارَةِ نَعْلَيْهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('202bc6e2-6d6b-55b7-9de3-22ad9bf7c41f', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '312', '‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَهْوَنُ أَهْلِ النَّارِ عَذَابًا ‏ ‏أَبُو طَالِبٍ ‏ ‏وَهُوَ مُنْتَعِلٌ بِنَعْلَيْنِ يَغْلِي مِنْهُمَا دِمَاغُهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e9d96d6e-9dad-52be-bbf5-5e69ace9886d', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '313', '‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏وَابْنُ بَشَّارٍ ‏ ‏وَاللَّفْظُ ‏ ‏لِابْنِ الْمُثَنَّى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا إِسْحَقَ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏يَخْطُبُ وَهُوَ يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ أَهْوَنَ أَهْلِ النَّارِ عَذَابًا يَوْمَ الْقِيَامَةِ لَرَجُلٌ تُوضَعُ فِي أَخْمَصِ قَدَمَيْهِ جَمْرَتَانِ يَغْلِي مِنْهُمَا دِمَاغُهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2c944ee5-602b-59aa-8b92-497e5fb3aa3f', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '314', '‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏النُّعْمَانِ بْنِ بَشِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَهْوَنَ أَهْلِ النَّارِ عَذَابًا مَنْ لَهُ نَعْلَانِ ‏ ‏وَشِرَاكَانِ ‏ ‏مِنْ نَارٍ يَغْلِي مِنْهُمَا دِمَاغُهُ كَمَا ‏ ‏يَغْلِ ‏ ‏الْمِرْجَلُ مَا يَرَى أَنَّ أَحَدًا أَشَدُّ مِنْهُ عَذَابًا وَإِنَّهُ لَأَهْوَنُهُمْ عَذَابًا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3cf98295-443a-51af-b41c-152afa1ff1e2', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '315', '‏ ‏حَدَّثَنِي ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ غِيَاثٍ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏ابْنُ جُدْعَانَ ‏ ‏كَانَ فِي الْجَاهِلِيَّةِ يَصِلُ الرَّحِمَ وَيُطْعِمُ الْمِسْكِينَ فَهَلْ ذَاكَ نَافِعُهُ قَالَ ‏ ‏لَا يَنْفَعُهُ إِنَّهُ لَمْ يَقُلْ يَوْمًا رَبِّ اغْفِرْ لِي خَطِيئَتِي يَوْمَ الدِّينِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6f01755e-d024-5b33-90a9-18a1063ba5ec', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '316', '‏ ‏حَدَّثَنِي ‏ ‏أَحْمَدُ بْنُ حَنْبَلٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ بْنِ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْعَاصِ ‏ ‏قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جِهَارًا غَيْرَ سِرٍّ يَقُولُ ‏ ‏أَلَا إِنَّ آلَ أَبِي ‏ ‏يَعْنِي فُلَانًا لَيْسُوا لِي بِأَوْلِيَاءَ إِنَّمَا ‏ ‏وَلِيِّيَ اللَّهُ وَصَالِحُ الْمُؤْمِنِينَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2f38aaa9-b98d-5977-9106-313b1b84799e', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '317', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ سَلَّامِ بْنِ عُبَيْدِ اللَّهِ الْجُمَحِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الرَّبِيعُ يَعْنِي ابْنَ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَدْخُلُ مِنْ أُمَّتِي الْجَنَّةَ سَبْعُونَ أَلْفًا بِغَيْرِ حِسَابٍ فَقَالَ رَجُلٌ يَا رَسُولَ اللَّهِ ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ قَالَ اللَّهُمَّ اجْعَلْهُ مِنْهُمْ ثُمَّ قَامَ آخَرُ فَقَالَ يَا رَسُولَ اللَّهِ ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ قَالَ سَبَقَكَ بِهَا ‏ ‏عُكَّاشَةُ ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏بِمِثْلِ حَدِيثِ ‏ ‏الرَّبِيعِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('47e677f6-a706-5e2d-af30-bd0b5c2ebd0a', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '318', '‏ ‏حَدَّثَنِي ‏ ‏حَرْمَلَةُ بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ الْمُسَيَّبِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏حَدَّثَهُ ‏ ‏قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَدْخُلُ مِنْ أُمَّتِي ‏ ‏زُمْرَةٌ ‏ ‏هُمْ سَبْعُونَ أَلْفًا تُضِيءُ وُجُوهُهُمْ إِضَاءَةَ الْقَمَرِ لَيْلَةَ الْبَدْرِ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏فَقَامَ ‏ ‏عُكَّاشَةُ بْنُ مِحْصَنٍ الْأَسَدِيُّ ‏ ‏يَرْفَعُ ‏ ‏نَمِرَةً ‏ ‏عَلَيْهِ فَقَالَ يَا رَسُولَ اللَّهِ ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ اجْعَلْهُ مِنْهُمْ ثُمَّ قَامَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَبَقَكَ بِهَا ‏ ‏عُكَّاشَةُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9d295735-c711-56d2-b707-d2958b637f34', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '319', '‏ ‏و حَدَّثَنِي ‏ ‏حَرْمَلَةُ بْنُ يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏حَيْوَةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو يُونُسَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَدْخُلُ الْجَنَّةَ مِنْ أُمَّتِي سَبْعُونَ أَلْفًا ‏ ‏زُمْرَةٌ ‏ ‏وَاحِدَةٌ مِنْهُمْ عَلَى صُورَةِ الْقَمَرِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d2ae981f-ef25-5f1f-9d84-540d5b3b56d9', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '320', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ خَلَفٍ الْبَاهِلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْمُعْتَمِرُ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ حَسَّانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ يَعْنِي ابْنَ سِيرِينَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عِمْرَانُ ‏ ‏قَالَ ‏ ‏قَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدْخُلُ الْجَنَّةَ مِنْ أُمَّتِي سَبْعُونَ أَلْفًا بِغَيْرِ حِسَابٍ قَالُوا وَمَنْ هُمْ يَا رَسُولَ اللَّهِ قَالَ هُمْ الَّذِينَ لَا يَكْتَوُونَ وَلَا ‏ ‏يَسْتَرْقُونَ ‏ ‏وَعَلَى رَبِّهِمْ يَتَوَكَّلُونَ فَقَامَ ‏ ‏عُكَّاشَةُ ‏ ‏فَقَالَ ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ قَالَ أَنْتَ مِنْهُمْ قَالَ فَقَامَ رَجُلٌ فَقَالَ يَا نَبِيَّ اللَّهِ ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ قَالَ سَبَقَكَ بِهَا ‏ ‏عُكَّاشَةُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e6cf9622-129a-5ae6-9ebd-b7f52aa7b9d1', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '321', '‏ ‏حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏حَاجِبُ بْنُ عُمَرَ أَبُو خُشَيْنَةَ الثَّقَفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَدْخُلُ الْجَنَّةَ مِنْ أُمَّتِي سَبْعُونَ أَلْفًا بِغَيْرِ حِسَابٍ قَالُوا مَنْ هُمْ يَا رَسُولَ اللَّهِ قَالَ هُمْ الَّذِينَ لَا ‏ ‏يَسْتَرْقُونَ ‏ ‏وَلَا ‏ ‏يَتَطَيَّرُونَ ‏ ‏وَلَا يَكْتَوُونَ وَعَلَى رَبِّهِمْ يَتَوَكَّلُونَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9e8ea6eb-7c85-5c8c-a857-d44d3e0b51a9', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '322', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي ابْنَ أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ سَعْدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيَدْخُلَنَّ الْجَنَّةَ مِنْ أُمَّتِي سَبْعُونَ أَلْفًا ‏ ‏أَوْ سَبْعُ مِائَةِ أَلْفٍ لَا يَدْرِي ‏ ‏أَبُو حَازِمٍ ‏ ‏أَيَّهُمَا قَالَ ‏ ‏مُتَمَاسِكُونَ آخِذٌ بَعْضُهُمْ بَعْضًا لَا يَدْخُلُ أَوَّلُهُمْ حَتَّى يَدْخُلَ آخِرُهُمْ وُجُوهُهُمْ عَلَى صُورَةِ الْقَمَرِ لَيْلَةَ الْبَدْرِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8b79d76b-72ae-5311-b1ef-76d61c9b6718', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '323', '‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏حُصَيْنُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ كُنْتُ عِنْدَ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏فَقَالَ ‏ ‏أَيُّكُمْ رَأَى الْكَوْكَبَ الَّذِي ‏ ‏انْقَضَّ ‏ ‏الْبَارِحَةَ قُلْتُ أَنَا ثُمَّ قُلْتُ أَمَا إِنِّي لَمْ أَكُنْ فِي صَلَاةٍ وَلَكِنِّي لُدِغْتُ قَالَ فَمَاذَا صَنَعْتَ قُلْتُ اسْتَرْقَيْتُ قَالَ فَمَا حَمَلَكَ عَلَى ذَلِكَ قُلْتُ حَدِيثٌ ‏ ‏حَدَّثَنَاهُ ‏ ‏الشَّعْبِيُّ ‏ ‏فَقَالَ وَمَا حَدَّثَكُمْ ‏ ‏الشَّعْبِيُّ ‏ ‏قُلْتُ حَدَّثَنَا ‏ ‏عَنْ ‏ ‏بُرَيْدَةَ بْنِ حُصَيْبٍ الْأَسْلَمِيِّ ‏ ‏أَنَّهُ قَالَ لَا رُقْيَةَ إِلَّا مِنْ ‏ ‏عَيْنٍ ‏ ‏أَوْ ‏ ‏حُمَةٍ ‏ ‏فَقَالَ قَدْ أَحْسَنَ مَنْ انْتَهَى إِلَى مَا سَمِعَ وَلَكِنْ حَدَّثَنَا ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عُرِضَتْ عَلَيَّ الْأُمَمُ فَرَأَيْتُ النَّبِيَّ وَمَعَهُ ‏ ‏الرُّهَيْطُ ‏ ‏وَالنَّبِيَّ وَمَعَهُ الرَّجُلُ وَالرَّجُلَانِ وَالنَّبِيَّ لَيْسَ مَعَهُ أَحَدٌ إِذْ رُفِعَ لِي سَوَادٌ عَظِيمٌ فَظَنَنْتُ أَنَّهُمْ أُمَّتِي فَقِيلَ لِي هَذَا ‏ ‏مُوسَى ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَوْمُهُ وَلَكِنْ انْظُرْ إِلَى الْأُفُقِ فَنَظَرْتُ فَإِذَا سَوَادٌ عَظِيمٌ فَقِيلَ لِي انْظُرْ إِلَى الْأُفُقِ الْآخَرِ فَإِذَا سَوَادٌ عَظِيمٌ فَقِيلَ لِي هَذِهِ أُمَّتُكَ وَمَعَهُمْ سَبْعُونَ أَلْفًا يَدْخُلُونَ الْجَنَّةَ بِغَيْرِ حِسَابٍ وَلَا عَذَابٍ ثُمَّ نَهَضَ فَدَخَلَ مَنْزِلَهُ ‏ ‏فَخَاضَ ‏ ‏النَّاسُ فِي أُولَئِكَ الَّذِينَ يَدْخُلُونَ الْجَنَّةَ بِغَيْرِ حِسَابٍ وَلَا عَذَابٍ فَقَالَ بَعْضُهُمْ فَلَعَلَّهُمْ الَّذِينَ صَحِبُوا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ بَعْضُهُمْ فَلَعَلَّهُمْ الَّذِينَ وُلِدُوا فِي الْإِسْلَامِ وَلَمْ يُشْرِكُوا بِاللَّهِ وَذَكَرُوا أَشْيَاءَ فَخَرَجَ عَلَيْهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَا الَّذِي ‏ ‏تَخُوضُونَ ‏ ‏فِيهِ فَأَخْبَرُوهُ فَقَالَ هُمْ الَّذِينَ لَا يَرْقُونَ وَلَا ‏ ‏يَسْتَرْقُونَ ‏ ‏وَلَا ‏ ‏يَتَطَيَّرُونَ ‏ ‏وَعَلَى رَبِّهِمْ يَتَوَكَّلُونَ فَقَامَ ‏ ‏عُكَّاشَةُ بْنُ مِحْصَنٍ ‏ ‏فَقَالَ ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ فَقَالَ أَنْتَ مِنْهُمْ ثُمَّ قَامَ رَجُلٌ آخَرُ فَقَالَ ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ فَقَالَ سَبَقَكَ بِهَا ‏ ‏عُكَّاشَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏حُصَيْنٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عُرِضَتْ عَلَيَّ الْأُمَمُ ثُمَّ ذَكَرَ بَاقِيَ الْحَدِيثِ نَحْوَ حَدِيثِ ‏ ‏هُشَيْمٍ ‏ ‏وَلَمْ يَذْكُرْ أَوَّلَ حَدِيثِهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6afa0ba4-8d04-5857-bd4e-d173cffc341f', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '324', '‏ ‏حَدَّثَنَا ‏ ‏هَنَّادُ بْنُ السَّرِيِّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَا تَرْضَوْنَ أَنْ تَكُونُوا رُبُعَ أَهْلِ الْجَنَّةِ قَالَ فَكَبَّرْنَا ثُمَّ قَالَ أَمَا تَرْضَوْنَ أَنْ تَكُونُوا ثُلُثَ أَهْلِ الْجَنَّةِ قَالَ فَكَبَّرْنَا ثُمَّ قَالَ إِنِّي لَأَرْجُو أَنْ تَكُونُوا شَطْرَ أَهْلِ الْجَنَّةِ وَسَأُخْبِرُكُمْ عَنْ ذَلِكَ مَا الْمُسْلِمُونَ فِي الْكُفَّارِ إِلَّا كَشَعْرَةٍ بَيْضَاءَ فِي ثَوْرٍ أَسْوَدَ أَوْ كَشَعْرَةٍ سَوْدَاءَ فِي ثَوْرٍ أَبْيَضَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('39036a53-321b-5ede-975a-502c84b0bf96', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '325', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏وَمُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏وَاللَّفْظُ ‏ ‏لِابْنِ الْمُثَنَّى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي قُبَّةٍ نَحْوًا مِنْ أَرْبَعِينَ رَجُلًا فَقَالَ ‏ ‏أَتَرْضَوْنَ أَنْ تَكُونُوا رُبُعَ أَهْلِ الْجَنَّةِ قَالَ قُلْنَا نَعَمْ فَقَالَ أَتَرْضَوْنَ أَنْ تَكُونُوا ثُلُثَ أَهْلِ الْجَنَّةِ فَقُلْنَا نَعَمْ فَقَالَ وَالَّذِي نَفْسِي بِيَدِهِ إِنِّي لَأَرْجُو أَنْ تَكُونُوا نِصْفَ أَهْلِ الْجَنَّةِ وَذَاكَ أَنَّ الْجَنَّةَ لَا يَدْخُلُهَا إِلَّا نَفْسٌ مُسْلِمَةٌ وَمَا أَنْتُمْ فِي أَهْلِ الشِّرْكِ إِلَّا كَالشَّعْرَةِ الْبَيْضَاءِ فِي جِلْدِ الثَّوْرِ الْأَسْوَدِ أَوْ كَالشَّعْرَةِ السَّوْدَاءِ فِي جِلْدِ الثَّوْرِ الْأَحْمَرِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0ada3060-ccea-5254-9ba5-ebcf472397cf', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '326', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ وَهُوَ ابْنُ مِغْوَلٍ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏خَطَبَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَسْنَدَ ظَهْرَهُ إِلَى قُبَّةِ أَدَمٍ فَقَالَ ‏ ‏أَلَا لَا يَدْخُلُ الْجَنَّةَ إِلَّا نَفْسٌ مُسْلِمَةٌ اللَّهُمَّ هَلْ بَلَّغْتُ اللَّهُمَّ اشْهَدْ أَتُحِبُّونَ أَنَّكُمْ رُبُعُ أَهْلِ الْجَنَّةِ فَقُلْنَا نَعَمْ يَا رَسُولَ اللَّهِ فَقَالَ أَتُحِبُّونَ أَنْ تَكُونُوا ثُلُثَ أَهْلِ الْجَنَّةِ قَالُوا نَعَمْ يَا رَسُولَ اللَّهِ قَالَ إِنِّي لَأَرْجُو أَنْ تَكُونُوا شَطْرَ أَهْلِ الْجَنَّةِ مَا أَنْتُمْ فِي سِوَاكُمْ مِنْ الْأُمَمِ إِلَّا كَالشَّعْرَةِ السَّوْدَاءِ فِي الثَّوْرِ الْأَبْيَضِ أَوْ كَالشَّعْرَةِ الْبَيْضَاءِ فِي الثَّوْرِ الْأَسْوَدِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c8a80418-a08a-580d-82fd-6b33005b0af4', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '327', '‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ أَبِي شَيْبَةَ الْعَبْسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ اللَّهُ عَزَّ وَجَلَّ ‏ ‏يَا ‏ ‏آدَمُ ‏ ‏فَيَقُولُ لَبَّيْكَ وَسَعْدَيْكَ وَالْخَيْرُ فِي يَدَيْكَ قَالَ يَقُولُ أَخْرِجْ ‏ ‏بَعْثَ ‏ ‏النَّارِ قَالَ وَمَا بَعْثُ النَّارِ قَالَ مِنْ كُلِّ أَلْفٍ تِسْعَ مِائَةٍ وَتِسْعَةً وَتِسْعِينَ قَالَ فَذَاكَ حِينَ يَشِيبُ الصَّغِيرُ ‏ { ‏وَتَضَعُ كُلُّ ذَاتِ حَمْلٍ حَمْلَهَا وَتَرَى النَّاسَ سُكَارَى وَمَا هُمْ بِسُكَارَى وَلَكِنَّ عَذَابَ اللَّهِ شَدِيدٌ ‏} ‏قَالَ فَاشْتَدَّ عَلَيْهِمْ قَالُوا يَا رَسُولَ اللَّهِ أَيُّنَا ذَلِكَ الرَّجُلُ فَقَالَ أَبْشِرُوا فَإِنَّ مِنْ ‏ ‏يَأْجُوجَ ‏ ‏وَمَأْجُوجَ ‏ ‏أَلْفًا وَمِنْكُمْ رَجُلٌ قَالَ ثُمَّ قَالَ وَالَّذِي نَفْسِي بِيَدِهِ إِنِّي لَأَطْمَعُ أَنْ تَكُونُوا رُبُعَ أَهْلِ الْجَنَّةِ فَحَمِدْنَا اللَّهَ وَكَبَّرْنَا ثُمَّ قَالَ وَالَّذِي نَفْسِي بِيَدِهِ إِنِّي لَأَطْمَعُ أَنْ تَكُونُوا ثُلُثَ أَهْلِ الْجَنَّةِ فَحَمِدْنَا اللَّهَ وَكَبَّرْنَا ثُمَّ قَالَ وَالَّذِي نَفْسِي بِيَدِهِ إِنِّي لَأَطْمَعُ أَنْ تَكُونُوا ‏ ‏شَطْرَ ‏ ‏أَهْلِ الْجَنَّةِ إِنَّ مَثَلَكُمْ فِي الْأُمَمِ كَمَثَلِ الشَّعْرَةِ الْبَيْضَاءِ فِي جِلْدِ الثَّوْرِ الْأَسْوَدِ أَوْ ‏ ‏كَالرَّقْمَةِ ‏ ‏فِي ذِرَاعِ الْحِمَارِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏بِهَذَا الْإِسْنَادِ غَيْرَ أَنَّهُمَا ‏ ‏قَالَا ‏ ‏مَا أَنْتُمْ يَوْمَئِذٍ فِي النَّاسِ إِلَّا كَالشَّعْرَةِ الْبَيْضَاءِ فِي الثَّوْرِ الْأَسْوَدِ أَوْ كَالشَّعْرَةِ السَّوْدَاءِ فِي الثَّوْرِ الْأَبْيَضِ وَلَمْ يَذْكُرَا أَوْ ‏ ‏كَالرَّقْمَةِ ‏ ‏فِي ذِرَاعِ الْحِمَارِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9018a06d-1ee9-5d7b-bfe3-e383d34aadba', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '328', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ مَنْصُورٍ ‏ ‏حَدَّثَنَا ‏ ‏حَبَّانُ بْنُ هِلَالٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏أَنَّ ‏ ‏زَيْدًا ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏أَبَا سَلَّامٍ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِي مَالِكٍ الْأَشْعَرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الطُّهُورُ ‏ ‏شَطْرُ ‏ ‏الْإِيمَانِ وَالْحَمْدُ لِلَّهِ تَمْلَأُ الْمِيزَانَ وَسُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ تَمْلَآَنِ ‏ ‏أَوْ تَمْلَأُ ‏ ‏مَا بَيْنَ السَّمَاوَاتِ وَالْأَرْضِ وَالصَّلَاةُ نُورٌ وَالصَّدَقَةُ بُرْهَانٌ وَالصَّبْرُ ضِيَاءٌ وَالْقُرْآنُ حُجَّةٌ لَكَ أَوْ عَلَيْكَ كُلُّ النَّاسِ ‏ ‏يَغْدُو ‏ ‏فَبَايِعٌ نَفْسَهُ فَمُعْتِقُهَا أَوْ ‏ ‏مُوبِقُهَا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('41e013f6-3a90-5881-8137-6f6c193a4467', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '329', '‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ ‏ ‏وَقُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏وَأَبُو كَامِلٍ الْجَحْدَرِيُّ ‏ ‏وَاللَّفْظُ ‏ ‏لِسَعِيدٍ ‏ ‏قَالُوا ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ سَعْدٍ ‏ ‏قَالَ ‏ ‏دَخَلَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَلَى ‏ ‏ابْنِ عَامِرٍ ‏ ‏يَعُودُهُ وَهُوَ مَرِيضٌ فَقَالَ أَلَا تَدْعُو اللَّهَ لِي يَا ‏ ‏ابْنَ عُمَرَ ‏ ‏قَالَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تُقْبَلُ صَلَاةٌ بِغَيْرِ طُهُورٍ وَلَا صَدَقَةٌ مِنْ ‏ ‏غُلُولٍ ‏ ‏وَكُنْتَ عَلَى ‏ ‏الْبَصْرَةِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏وَابْنُ بَشَّارٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏ح ‏ ‏قَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَوَكِيعٌ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏بِهَذَا الْإِسْنَادِ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d0cd47b3-4059-5909-815c-57f13687e9b3', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '330', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ بْنُ هَمَّامٍ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرُ بْنُ رَاشِدٍ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ مُنَبِّهٍ ‏ ‏أَخِي ‏ ‏وَهْبِ بْنِ مُنَبِّهٍ ‏ ‏قَالَ هَذَا مَا حَدَّثَنَا ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ أَحَادِيثَ مِنْهَا وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُقْبَلُ صَلَاةُ أَحَدِكُمْ إِذَا أَحْدَثَ حَتَّى يَتَوَضَّأَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('58831cac-fe4c-5e8d-af25-394a5b7bfae6', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '331', '‏ ‏حَدَّثَنِي ‏ ‏أَبُو الطَّاهِرِ أَحْمَدُ بْنُ عَمْرِو بْنِ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ سَرْحٍ ‏ ‏وَحَرْمَلَةُ بْنُ يَحْيَى التُّجِيبِيُّ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَنَّ ‏ ‏عَطَاءَ بْنَ يَزِيدَ اللَّيْثِيَّ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏حُمْرَانَ ‏ ‏مَوْلَى ‏ ‏عُثْمَانَ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏دَعَا بِوَضُوءٍ فَتَوَضَّأَ فَغَسَلَ كَفَّيْهِ ثَلَاثَ مَرَّاتٍ ثُمَّ مَضْمَضَ ‏ ‏وَاسْتَنْثَرَ ‏ ‏ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثَ مَرَّاتٍ ثُمَّ غَسَلَ يَدَهُ الْيُمْنَى إِلَى ‏ ‏الْمِرْفَقِ ‏ ‏ثَلَاثَ مَرَّاتٍ ثُمَّ غَسَلَ يَدَهُ الْيُسْرَى مِثْلَ ذَلِكَ ثُمَّ مَسَحَ رَأْسَهُ ثُمَّ غَسَلَ رِجْلَهُ الْيُمْنَى إِلَى الْكَعْبَيْنِ ثَلَاثَ مَرَّاتٍ ثُمَّ غَسَلَ الْيُسْرَى مِثْلَ ذَلِكَ ثُمَّ قَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ نَحْوَ وُضُوئِي هَذَا ثُمَّ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَوَضَّأَ نَحْوَ وُضُوئِي هَذَا ثُمَّ قَامَ فَرَكَعَ رَكْعَتَيْنِ لَا يُحَدِّثُ فِيهِمَا نَفْسَهُ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏وَكَانَ عُلَمَاؤُنَا يَقُولُونَ هَذَا الْوُضُوءُ ‏ ‏أَسْبَغُ ‏ ‏مَا يَتَوَضَّأُ بِهِ أَحَدٌ لِلصَّلَاةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('32f79cea-efaa-544d-a7c6-54f89cb30aeb', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '332', '‏ ‏و حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏حُمْرَانَ ‏ ‏مَوْلَى ‏ ‏عُثْمَانَ ‏ ‏أَنَّهُ رَأَى ‏ ‏عُثْمَانَ ‏ ‏دَعَا بِإِنَاءٍ فَأَفْرَغَ عَلَى كَفَّيْهِ ثَلَاثَ مِرَارٍ فَغَسَلَهُمَا ثُمَّ أَدْخَلَ يَمِينَهُ فِي الْإِنَاءِ فَمَضْمَضَ ‏ ‏وَاسْتَنْثَرَ ‏ ‏ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثَ مَرَّاتٍ وَيَدَيْهِ إِلَى الْمِرْفَقَيْنِ ثَلَاثَ مَرَّاتٍ ثُمَّ مَسَحَ بِرَأْسِهِ ثُمَّ غَسَلَ رِجْلَيْهِ ثَلَاثَ مَرَّاتٍ ثُمَّ قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَوَضَّأَ نَحْوَ وُضُوئِي هَذَا ثُمَّ صَلَّى رَكْعَتَيْنِ لَا يُحَدِّثُ فِيهِمَا نَفْسَهُ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('39255726-b06f-5bb4-b797-f0bb179dedda', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '333', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏وَعُثْمَانُ بْنُ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ الْحَنْظَلِيُّ ‏ ‏وَاللَّفْظُ ‏ ‏لِقُتَيْبَةَ ‏ ‏قَالَ ‏ ‏إِسْحَقُ ‏ ‏أَخْبَرَنَا ‏ ‏وَقَالَ الْآخَرَانِ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏حُمْرَانَ ‏ ‏مَوْلَى ‏ ‏عُثْمَانَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏وَهُوَ بِفِنَاءِ الْمَسْجِدِ فَجَاءَهُ الْمُؤَذِّنُ عِنْدَ الْعَصْرِ فَدَعَا بِوَضُوءٍ فَتَوَضَّأَ ثُمَّ قَالَ وَاللَّهِ لَأُحَدِّثَنَّكُمْ حَدِيثًا لَوْلَا آيَةٌ فِي كِتَابِ اللَّهِ مَا حَدَّثْتُكُمْ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَتَوَضَّأُ رَجُلٌ مُسْلِمٌ فَيُحْسِنُ الْوُضُوءَ فَيُصَلِّي صَلَاةً إِلَّا غَفَرَ اللَّهُ لَهُ مَا بَيْنَهُ وَبَيْنَ الصَّلَاةِ الَّتِي تَلِيهَا ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏وَأَبُو كُرَيْبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏ح ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏وَفِي حَدِيثِ ‏ ‏أَبِي أُسَامَةَ ‏ ‏فَيُحْسِنُ وُضُوءَهُ ثُمَّ ‏ ‏يُصَلِّي الْمَكْتُوبَةَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
