insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c525d2be-f622-59f4-92c9-110735d5bb0a', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '335', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ بْنُ حُمَيْدٍ ‏ ‏وَحَجَّاجُ بْنُ الشَّاعِرِ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏أَبِي الْوَلِيدِ ‏ ‏قَالَ ‏ ‏عَبْدٌ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ سَعِيدِ بْنِ عَمْرِو بْنِ سَعِيدِ بْنِ الْعَاصِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ كُنْتُ عِنْدَ ‏ ‏عُثْمَانَ ‏ ‏فَدَعَا بِطَهُورٍ فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ امْرِئٍ مُسْلِمٍ تَحْضُرُهُ صَلَاةٌ مَكْتُوبَةٌ فَيُحْسِنُ وُضُوءَهَا وَخُشُوعَهَا وَرُكُوعَهَا إِلَّا كَانَتْ كَفَّارَةً لِمَا قَبْلَهَا مِنْ الذُّنُوبِ مَا لَمْ يُؤْتِ كَبِيرَةً وَذَلِكَ الدَّهْرَ كُلَّهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('03aa7312-51d1-564c-8866-30fc17cf0cb4', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '336', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏وَأَحْمَدُ بْنُ عَبْدَةَ الضَّبِّيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ وَهُوَ الدَّرَاوَرْدِيُّ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏حُمْرَانَ ‏ ‏مَوْلَى ‏ ‏عُثْمَانَ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏بِوَضُوءٍ فَتَوَضَّأَ ثُمَّ قَالَ إِنَّ نَاسًا يَتَحَدَّثُونَ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحَادِيثَ لَا أَدْرِي مَا هِيَ إِلَّا أَنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ مِثْلَ وُضُوئِي هَذَا ثُمَّ قَالَ ‏ ‏مَنْ تَوَضَّأَ هَكَذَا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ وَكَانَتْ صَلَاتُهُ وَمَشْيُهُ إِلَى الْمَسْجِدِ نَافِلَةً ‏ ‏وَفِي رِوَايَةِ ‏ ‏ابْنِ عَبْدَةَ ‏ ‏أَتَيْتُ ‏ ‏عُثْمَانَ ‏ ‏فَتَوَضَّأَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ebcbf6f7-6aee-5cc0-b827-8aea136c775c', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '337', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏وَأَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَزُهَيْرُ بْنُ حَرْبٍ ‏ ‏وَاللَّفْظُ ‏ ‏لِقُتَيْبَةَ ‏ ‏وَأَبِي بَكْرٍ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏أَبِي أَنَسٍ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ ‏ ‏تَوَضَّأَ ‏ ‏بِالْمَقَاعِدِ ‏ ‏فَقَالَ ‏ ‏أَلَا ‏ ‏أُرِيكُمْ وُضُوءَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ تَوَضَّأَ ثَلَاثًا ثَلَاثًا ‏ ‏وَزَادَ ‏ ‏قُتَيْبَةُ ‏ ‏فِي رِوَايَتِهِ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏قَالَ ‏ ‏أَبُو النَّضْرِ ‏ ‏عَنْ ‏ ‏أَبِي أَنَسٍ ‏ ‏قَالَ ‏ ‏وَعِنْدَهُ رِجَالٌ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ce4b8b6e-4dd9-5fe4-96f2-e778a6b0b7fb', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '338', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏وَكِيعٍ ‏ ‏قَالَ ‏ ‏أَبُو كُرَيْبٍ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏مِسْعَرٍ ‏ ‏عَنْ ‏ ‏جَامِعِ بْنِ شَدَّادٍ أَبِي صَخْرَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏حُمْرَانَ بْنَ أَبَانَ ‏ ‏قَالَ ‏ ‏كُنْتُ أَضَعُ ‏ ‏لِعُثْمَانَ ‏ ‏طَهُورَهُ فَمَا أَتَى عَلَيْهِ يَوْمٌ إِلَّا وَهُوَ يُفِيضُ عَلَيْهِ ‏ ‏نُطْفَةً ‏ ‏وَقَالَ ‏ ‏عُثْمَانُ ‏ ‏حَدَّثَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَ انْصِرَافِنَا مِنْ صَلَاتِنَا هَذِهِ ‏ ‏قَالَ ‏ ‏مِسْعَرٌ ‏ ‏أُرَاهَا الْعَصْرَ ‏ ‏فَقَالَ مَا أَدْرِي أُحَدِّثُكُمْ بِشَيْءٍ أَوْ أَسْكُتُ فَقُلْنَا يَا رَسُولَ اللَّهِ إِنْ كَانَ خَيْرًا فَحَدِّثْنَا وَإِنْ كَانَ غَيْرَ ذَلِكَ فَاللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ ‏ ‏مَا مِنْ مُسْلِمٍ يَتَطَهَّرُ فَيُتِمُّ الطُّهُورَ الَّذِي كَتَبَ اللَّهُ عَلَيْهِ فَيُصَلِّي هَذِهِ الصَّلَوَاتِ الْخَمْسَ إِلَّا كَانَتْ كَفَّارَاتٍ لِمَا بَيْنَهَا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('05a86d6c-58d9-5347-a1c2-3b26a31a0e79', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '339', '‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏وَابْنُ بَشَّارٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَا ‏ ‏جَمِيعًا ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏جَامِعِ بْنِ شَدَّادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏حُمْرَانَ بْنَ أَبَانَ ‏ ‏يُحَدِّثُ ‏ ‏أَبَا بُرْدَةَ ‏ ‏فِي هَذَا الْمَسْجِدِ فِي إِمَارَةِ ‏ ‏بِشْرٍ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ بْنَ عَفَّانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَتَمَّ الْوُضُوءَ كَمَا أَمَرَهُ اللَّهُ تَعَالَى فَالصَّلَوَاتُ الْمَكْتُوبَاتُ كَفَّارَاتٌ لِمَا بَيْنَهُنَّ ‏ ‏هَذَا حَدِيثُ ‏ ‏ابْنِ مُعَاذٍ ‏ ‏وَلَيْسَ فِي حَدِيثِ ‏ ‏غُنْدَرٍ ‏ ‏فِي إِمَارَةِ ‏ ‏بِشْرٍ ‏ ‏وَلَا ذِكْرُ الْمَكْتُوبَاتِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cb34791d-19d0-5d69-b760-4ef619bf56a5', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '340', '‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ سَعِيدٍ الْأَيْلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ وَأَخْبَرَنِي ‏ ‏مَخْرَمَةُ بْنُ بُكَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏حُمْرَانَ ‏ ‏مَوْلَى ‏ ‏عُثْمَانَ ‏ ‏قَالَ ‏ ‏تَوَضَّأَ ‏ ‏عُثْمَانُ بْنُ عَفَّانَ ‏ ‏يَوْمًا وُضُوءًا حَسَنًا ثُمَّ قَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ فَأَحْسَنَ الْوُضُوءَ ثُمَّ قَالَ ‏ ‏مَنْ تَوَضَّأَ هَكَذَا ثُمَّ خَرَجَ إِلَى الْمَسْجِدِ لَا ‏ ‏يَنْهَزُهُ ‏ ‏إِلَّا الصَّلَاةُ غُفِرَ لَهُ مَا خَلَا مِنْ ذَنْبِهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cd0cdbb0-04dd-5d6e-b58d-0125b14627c6', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '341', '‏ ‏و حَدَّثَنِي ‏ ‏أَبُو الطَّاهِرِ ‏ ‏وَيُونُسُ بْنُ عَبْدِ الْأَعْلَى ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْحَارِثِ ‏ ‏أَنَّ ‏ ‏الْحُكَيْمَ بْنَ عَبْدِ اللَّهِ الْقُرَشِيَّ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏نَافِعَ بْنَ جُبَيْرٍ ‏ ‏وَعَبْدَ اللَّهِ بْنَ أَبِي سَلَمَةَ ‏ ‏حَدَّثَاهُ أَنَّ ‏ ‏مُعَاذَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَهُمَا عَنْ ‏ ‏حُمْرَانَ ‏ ‏مَوْلَى ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ تَوَضَّأَ لِلصَّلَاةِ ‏ ‏فَأَسْبَغَ ‏ ‏الْوُضُوءَ ثُمَّ مَشَى إِلَى الصَّلَاةِ الْمَكْتُوبَةِ فَصَلَّاهَا مَعَ النَّاسِ أَوْ مَعَ الْجَمَاعَةِ أَوْ فِي الْمَسْجِدِ غَفَرَ اللَّهُ لَهُ ذُنُوبَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f79fb43e-0228-5136-9fe6-3c86838e7de7', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '342', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏وَقُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏وَعَلِيُّ بْنُ حُجْرٍ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ ‏ ‏قَالَ ‏ ‏ابْنُ أَيُّوبَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ بْنُ جَعْفَرٍ ‏ ‏أَخْبَرَنِي ‏ ‏الْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ يَعْقُوبَ ‏ ‏مَوْلَى ‏ ‏الْحُرَقَةِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الصَّلَاةُ الْخَمْسُ وَالْجُمْعَةُ إِلَى الْجُمْعَةِ كَفَّارَةٌ لِمَا بَيْنَهُنَّ مَا لَمْ تُغْشَ الْكَبَائِرُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d08ffc2f-5eaa-5220-b8a4-f7bda6d4f923', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '343', '‏ ‏حَدَّثَنِي ‏ ‏نَصْرُ بْنُ عَلِيٍّ الْجَهْضَمِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الصَّلَوَاتُ الْخَمْسُ وَالْجُمْعَةُ إِلَى الْجُمْعَةِ كَفَّارَاتٌ لِمَا بَيْنَهُنَّ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5448f584-07d7-5f8e-9900-b145751cc467', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '344', '‏ ‏حَدَّثَنِي ‏ ‏أَبُو الطَّاهِرِ ‏ ‏وَهَارُونُ بْنُ سَعِيدٍ الْأَيْلِيُّ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏أَبِي صَخْرٍ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ إِسْحَقَ ‏ ‏مَوْلَى ‏ ‏زَائِدَةَ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏الصَّلَوَاتُ الْخَمْسُ وَالْجُمْعَةُ إِلَى الْجُمْعَةِ وَرَمَضَانُ إِلَى رَمَضَانَ مُكَفِّرَاتٌ مَا بَيْنَهُنَّ إِذَا اجْتَنَبَ الْكَبَائِرَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2f73b9fe-7df3-57c2-9be5-65d33751e8c2', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '345', '‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ حَاتِمِ بْنِ مَيْمُونٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ يَعْنِي ابْنَ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي إِدْرِيسَ الْخَوْلَانِيِّ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏ح ‏ ‏وَحَدَّثَنِي ‏ ‏أَبُو عُثْمَانَ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏كَانَتْ عَلَيْنَا رِعَايَةُ الْإِبِلِ فَجَاءَتْ نَوْبَتِي ‏ ‏فَرَوَّحْتُهَا ‏ ‏بِعَشِيٍّ فَأَدْرَكْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَائِمًا يُحَدِّثُ النَّاسَ فَأَدْرَكْتُ مِنْ قَوْلِهِ ‏ ‏مَا مِنْ مُسْلِمٍ يَتَوَضَّأُ فَيُحْسِنُ وُضُوءَهُ ثُمَّ يَقُومُ فَيُصَلِّي رَكْعَتَيْنِ مُقْبِلٌ عَلَيْهِمَا بِقَلْبِهِ وَوَجْهِهِ إِلَّا وَجَبَتْ لَهُ الْجَنَّةُ قَالَ فَقُلْتُ مَا أَجْوَدَ هَذِهِ فَإِذَا قَائِلٌ بَيْنَ يَدَيَّ يَقُولُ الَّتِي قَبْلَهَا أَجْوَدُ فَنَظَرْتُ فَإِذَا ‏ ‏عُمَرُ ‏ ‏قَالَ إِنِّي قَدْ رَأَيْتُكَ جِئْتَ ‏ ‏آنِفًا ‏ ‏قَالَ مَا مِنْكُمْ مِنْ أَحَدٍ يَتَوَضَّأُ ‏ ‏فَيُبْلِغُ ‏ ‏أَوْ فَيُسْبِغُ الْوَضُوءَ ثُمَّ يَقُولُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ ‏ ‏مُحَمَّدًا عَبْدُ اللَّهِ وَرَسُولُهُ ‏ ‏إِلَّا فُتِحَتْ لَهُ أَبْوَابُ الْجَنَّةِ الثَّمَانِيَةُ يَدْخُلُ مِنْ أَيِّهَا شَاءَ ‏ ‏و حَدَّثَنَاه ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي إِدْرِيسَ الْخَوْلَانِيِّ ‏ ‏وَأَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ نُفَيْرِ بْنِ مَالِكٍ الْحَضْرَمِيِّ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَذَكَرَ مِثْلَهُ غَيْرَ أَنَّهُ قَالَ مَنْ تَوَضَّأَ فَقَالَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5a751d1f-7617-5a60-8b18-9e24a4293e30', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '346', '‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ الصَّبَّاحِ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى بْنِ عُمَارَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدِ بْنِ عَاصِمٍ الْأَنْصَارِيِّ ‏ ‏وَكَانَتْ لَهُ صُحْبَةٌ ‏ ‏قَالَ ‏ ‏قِيلَ لَهُ ‏ ‏تَوَضَّأْ لَنَا وُضُوءَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَعَا بِإِنَاءٍ ‏ ‏فَأَكْفَأَ ‏ ‏مِنْهَا عَلَى يَدَيْهِ فَغَسَلَهُمَا ثَلَاثًا ثُمَّ أَدْخَلَ يَدَهُ فَاسْتَخْرَجَهَا فَمَضْمَضَ وَاسْتَنْشَقَ مِنْ كَفٍّ وَاحِدَةٍ فَفَعَلَ ذَلِكَ ثَلَاثًا ثُمَّ أَدْخَلَ يَدَهُ فَاسْتَخْرَجَهَا فَغَسَلَ وَجْهَهُ ثَلَاثًا ثُمَّ أَدْخَلَ يَدَهُ فَاسْتَخْرَجَهَا فَغَسَلَ يَدَيْهِ إِلَى الْمِرْفَقَيْنِ مَرَّتَيْنِ مَرَّتَيْنِ ثُمَّ أَدْخَلَ يَدَهُ فَاسْتَخْرَجَهَا فَمَسَحَ بِرَأْسِهِ فَأَقْبَلَ بِيَدَيْهِ وَأَدْبَرَ ثُمَّ غَسَلَ رِجْلَيْهِ إِلَى الْكَعْبَيْنِ ثُمَّ قَالَ هَكَذَا كَانَ وُضُوءُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏و حَدَّثَنِي ‏ ‏الْقَاسِمُ بْنُ زَكَرِيَّاءَ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ هُوَ ابْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏نَحْوَهُ وَلَمْ يَذْكُرْ الْكَعْبَيْنِ ‏ ‏و حَدَّثَنِي ‏ ‏إِسْحَقُ بْنُ مُوسَى الْأَنْصَارِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مَعْنٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى ‏ ‏بِهَذَا الْإِسْنَادِ وَقَالَ ‏ ‏مَضْمَضَ ‏ ‏وَاسْتَنْثَرَ ‏ ‏ثَلَاثًا وَلَمْ يَقُلْ مِنْ كَفٍّ وَاحِدَةٍ وَزَادَ بَعْدَ قَوْلِهِ فَأَقْبَلَ بِهِمَا وَأَدْبَرَ بَدَأَ بِمُقَدَّمِ رَأْسِهِ ثُمَّ ذَهَبَ بِهِمَا إِلَى ‏ ‏قَفَاهُ ‏ ‏ثُمَّ رَدَّهُمَا حَتَّى رَجَعَ إِلَى الْمَكَانِ الَّذِي بَدَأَ مِنْهُ وَغَسَلَ رِجْلَيْهِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ بِشْرٍ الْعَبْدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ يَحْيَى ‏ ‏بِمِثْلِ إِسْنَادِهِمْ ‏ ‏وَاقْتَصَّ الْحَدِيثَ وَقَالَ فِيهِ فَمَضْمَضَ وَاسْتَنْشَقَ ‏ ‏وَاسْتَنْثَرَ ‏ ‏مِنْ ثَلَاثِ غَرَفَاتٍ وَقَالَ أَيْضًا فَمَسَحَ بِرَأْسِهِ فَأَقْبَلَ بِهِ وَأَدْبَرَ مَرَّةً وَاحِدَةً ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏أَمْلَى عَلَيَّ ‏ ‏وُهَيْبٌ ‏ ‏هَذَا الْحَدِيثَ ‏ ‏و قَالَ ‏ ‏وُهَيْبٌ ‏ ‏أَمْلَى عَلَيَّ ‏ ‏عَمْرُو بْنُ يَحْيَى ‏ ‏هَذَا الْحَدِيثَ مَرَّتَيْنِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('92ac3946-c894-59b6-883c-0d4f0c0a7b75', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '347', '‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏هَارُونُ بْنُ سَعِيدٍ الْأَيْلِيُّ ‏ ‏وَأَبُو الطَّاهِرِ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏أَنَّ ‏ ‏حَبَّانَ بْنَ وَاسِعٍ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏أَبَاهُ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ زَيْدِ بْنِ عَاصِمٍ الْمَازِنِيَّ ‏ ‏يَذْكُرُ ‏ ‏أَنَّهُ رَأَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ فَمَضْمَضَ ثُمَّ ‏ ‏اسْتَنْثَرَ ‏ ‏ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثًا وَيَدَهُ الْيُمْنَى ثَلَاثًا وَالْأُخْرَى ثَلَاثًا وَمَسَحَ بِرَأْسِهِ بِمَاءٍ ‏ ‏غَيْرِ فَضْلِ يَدِهِ ‏ ‏وَغَسَلَ رِجْلَيْهِ حَتَّى أَنْقَاهُمَا ‏ ‏قَالَ ‏ ‏أَبُو الطَّاهِرِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْحَارِثِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('901957fc-c355-5791-a2b3-71f80e475faf', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '348', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏وَعَمْرٌو النَّاقِدُ ‏ ‏وَمُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏ابْنِ عُيَيْنَةَ ‏ ‏قَالَ ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏يَبْلُغُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏اسْتَجْمَرَ ‏ ‏أَحَدُكُمْ فَلْيَسْتَجْمِرْ ‏ ‏وِتْرًا ‏ ‏وَإِذَا تَوَضَّأَ أَحَدُكُمْ فَلِيَجْعَلْ فِي أَنْفِهِ مَاءً ثُمَّ ‏ ‏لِيَنْتَثِرْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fd2548a5-af83-58ff-b0d7-40b01ae968b5', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '349', '‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ بْنُ هَمَّامٍ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ مُنَبِّهٍ ‏ ‏قَالَ هَذَا مَا حَدَّثَنَا ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ أَحَادِيثَ مِنْهَا ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَوَضَّأَ أَحَدُكُمْ فَلْيَسْتَنْشِقْ بِمَنْخِرَيْهِ مِنْ الْمَاءِ ثُمَّ ‏ ‏لِيَنْتَثِرْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7eaf5c03-4f21-51eb-9ced-72644cc47598', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '350', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏قَالَ قَرَأْتُ عَلَى ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي إِدْرِيسَ الْخَوْلَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ تَوَضَّأَ ‏ ‏فَلْيَسْتَنْثِرْ ‏ ‏وَمَنْ ‏ ‏اسْتَجْمَرَ ‏ ‏فَلْيُوتِرْ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ ‏ ‏حَدَّثَنَا ‏ ‏حَسَّانُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ يَزِيدَ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏حَرْمَلَةُ بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو إِدْرِيسَ الْخَوْلَانِيُّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏وَأَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏يَقُولَانِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('93a3d39b-b0b8-5c15-a9ce-d6f298995151', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '351', '‏ ‏حَدَّثَنِي ‏ ‏بِشْرُ بْنُ الْحَكَمِ الْعَبْدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي الدَّرَاوَرْدِيَّ ‏ ‏عَنْ ‏ ‏ابْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا اسْتَيْقَظَ أَحَدُكُمْ مِنْ مَنَامِهِ فَلْيَسْتَنْثِرْ ثَلَاثَ مَرَّاتٍ فَإِنَّ الشَّيْطَانَ يَبِيتُ عَلَى ‏ ‏خَيَاشِيمِهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0eaabe4c-9d2b-5cb6-8fc6-c179c4a5a1c3', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '352', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏وَمُحَمَّدُ بْنُ رَافِعٍ ‏ ‏قَالَ ‏ ‏ابْنُ رَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُا ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏اسْتَجْمَرَ ‏ ‏أَحَدُكُمْ فَلْيُوتِرْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('11c4397e-3a1a-5267-a943-3b449185e74d', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '353', '‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ سَعِيدٍ الْأَيْلِيُّ ‏ ‏وَأَبُو الطَّاهِرِ ‏ ‏وَأَحْمَدُ بْنُ عِيسَى ‏ ‏قَالُوا أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏مَخْرَمَةَ بْنِ بُكَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏مَوْلَى ‏ ‏شَدَّادٍ ‏ ‏قَالَ دَخَلْتُ عَلَى ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ تُوُفِّيَ ‏ ‏سَعْدُ بْنُ أَبِي وَقَّاصٍ ‏ ‏فَدَخَلَ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكْرٍ ‏ ‏فَتَوَضَّأَ عِنْدَهَا فَقَالَتْ يَا ‏ ‏عَبْدَ الرَّحْمَنِ ‏ ‏أَسْبِغْ ‏ ‏الْوُضُوءَ ‏ ‏فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏وَيْلٌ ‏ ‏لِلْأَعْقَابِ ‏ ‏مِنْ النَّارِ ‏ ‏و حَدَّثَنِي ‏ ‏حَرْمَلَةُ بْنُ يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏حَيْوَةُ ‏ ‏أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أَبَا عَبْدِ اللَّهِ ‏ ‏مَوْلَى ‏ ‏شَدَّادِ بْنِ الْهَادِ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّهُ دَخَلَ عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَذَكَرَ عَنْهَا عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ حَاتِمٍ ‏ ‏وَأَبُو مَعْنٍ الرَّقَاشِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عُمَرُ بْنُ يُونُسَ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَوْ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنِي ‏ ‏سَالِمٌ ‏ ‏مَوْلَى ‏ ‏الْمَهْرِيِّ ‏ ‏قَالَ ‏ ‏خَرَجْتُ أَنَا ‏ ‏وَعَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكْرٍ ‏ ‏فِي جَنَازَةِ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏فَمَرَرْنَا عَلَى بَابِ حُجْرَةِ ‏ ‏عَائِشَةَ ‏ ‏فَذَكَرَ عَنْهَا عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏ ‏حَدَّثَنِي ‏ ‏سَلَمَةُ بْنُ شَبِيبٍ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ أَعْيَنَ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏حَدَّثَنِي ‏ ‏نُعَيْمُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏مَوْلَى ‏ ‏شَدَّادِ بْنِ الْهَادِ ‏ ‏قَالَ ‏ ‏كُنْتُ أَنَا مَعَ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏فَذَكَرَ عَنْهَا عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2c829281-40c5-5445-b3c7-7c65af9bf9fa', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '354', '‏ ‏و حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏إِسْحَقُ ‏ ‏أَخْبَرَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يِسَافٍ ‏ ‏عَنْ ‏ ‏أَبِي يَحْيَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏رَجَعْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏مَكَّةَ ‏ ‏إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏حَتَّى إِذَا كُنَّا بِمَاءٍ بِالطَّرِيقِ تَعَجَّلَ قَوْمٌ عِنْدَ الْعَصْرِ فَتَوَضَّئُوا وَهُمْ عِجَالٌ فَانْتَهَيْنَا إِلَيْهِمْ وَأَعْقَابُهُمْ تَلُوحُ لَمْ يَمَسَّهَا الْمَاءُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَيْلٌ ‏ ‏لِلْأَعْقَابِ ‏ ‏مِنْ النَّارِ ‏ ‏أَسْبِغُوا ‏ ‏الْوُضُوءَ ‏ ‏و حَدَّثَنَاه ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏ابْنُ الْمُثَنَّى ‏ ‏وَابْنُ بَشَّارٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏وَلَيْسَ فِي حَدِيثِ ‏ ‏شُعْبَةَ ‏ ‏أَسْبِغُوا ‏ ‏الْوُضُوءَ وَفِي حَدِيثِهِ ‏ ‏عَنْ ‏ ‏أَبِى يَحْيَى الْأَعْرَجِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a0c8047f-b597-5b05-9022-733fae0490e5', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '355', '‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ بْنُ فَرُّوخَ ‏ ‏وَأَبُو كَامِلٍ الْجَحْدَرِيُّ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏أَبِي عَوَانَةَ ‏ ‏قَالَ ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مَاهَكَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏قَالَ تَخَلَّفَ عَنَّا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ سَافَرْنَاهُ فَأَدْرَكَنَا وَقَدْ حَضَرَتْ صَلَاةُ الْعَصْرِ فَجَعَلْنَا نَمْسَحُ عَلَى أَرْجُلِنَا فَنَادَى ‏ ‏وَيْلٌ ‏ ‏لِلْأَعْقَابِ ‏ ‏مِنْ النَّارِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('da1c90a3-fddc-528b-ae15-2fab6f51bcbe', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '356', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ سَلَّامٍ الْجُمَحِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الرَّبِيعُ يَعْنِي ابْنَ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ وَهُوَ ابْنُ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى رَجُلًا لَمْ يَغْسِلْ ‏ ‏عَقِبَيْهِ ‏ ‏فَقَالَ ‏ ‏وَيْلٌ ‏ ‏لِلْأَعْقَابِ ‏ ‏مِنْ النَّارِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('be8e52fd-9035-5b78-8431-4271e3f34c4f', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '357', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏وَأَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَأَبُو كُرَيْبٍ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ رَأَى قَوْمًا يَتَوَضَّئُونَ مِنْ ‏ ‏الْمَطْهَرَةِ ‏ ‏فَقَالَ ‏ ‏أَسْبِغُوا ‏ ‏الْوُضُوءَ فَإِنِّي سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏وَيْلٌ ‏ ‏لِلْعَرَاقِيبِ ‏ ‏مِنْ النَّارِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8a4fa13d-a53b-51ae-b311-d85e711b8a19', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '358', '‏ ‏حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَيْلٌ ‏ ‏لِلْأَعْقَابِ ‏ ‏مِنْ النَّارِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('83cb0e4f-8521-50a3-9aec-891b587d28ce', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '359', '‏ ‏حَدَّثَنِي ‏ ‏سَلَمَةُ بْنُ شَبِيبٍ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ مُحَمَّدِ بْنِ أَعْيَنَ ‏ ‏حَدَّثَنَا ‏ ‏مَعْقِلٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَخْبَرَنِي ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏أَنَّ رَجُلًا تَوَضَّأَ فَتَرَكَ مَوْضِعَ ظُفُرٍ عَلَى قَدَمِهِ فَأَبْصَرَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏ارْجِعْ فَأَحْسِنْ وُضُوءَكَ فَرَجَعَ ثُمَّ صَلَّى ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b3546805-f11f-5757-81a7-c529a7ff3a4c', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '360', '‏ ‏حَدَّثَنَا ‏ ‏سُوَيْدُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ أَنَسٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو الطَّاهِرِ ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا تَوَضَّأَ الْعَبْدُ الْمُسْلِمُ أَوْ الْمُؤْمِنُ فَغَسَلَ وَجْهَهُ خَرَجَ مِنْ وَجْهِهِ كُلُّ خَطِيئَةٍ نَظَرَ إِلَيْهَا بِعَيْنَيْهِ مَعَ الْمَاءِ أَوْ مَعَ آخِرِ قَطْرِ الْمَاءِ فَإِذَا غَسَلَ يَدَيْهِ خَرَجَ مِنْ يَدَيْهِ كُلُّ خَطِيئَةٍ كَانَ ‏ ‏بَطَشَتْهَا ‏ ‏يَدَاهُ مَعَ الْمَاءِ أَوْ مَعَ آخِرِ قَطْرِ الْمَاءِ فَإِذَا غَسَلَ رِجْلَيْهِ خَرَجَتْ كُلُّ خَطِيئَةٍ مَشَتْهَا رِجْلَاهُ مَعَ الْمَاءِ أَوْ مَعَ آخِرِ قَطْرِ الْمَاءِ حَتَّى يَخْرُجَ نَقِيًّا مِنْ الذُّنُوبِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('40b58a5c-39b6-5c75-860f-fab3a4412227', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '361', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مَعْمَرِ بْنِ رِبْعِيٍّ الْقَيْسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هِشَامٍ الْمَخْزُومِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْوَاحِدِ وَهُوَ ابْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ حَكِيمٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏حُمْرَانَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَوَضَّأَ فَأَحْسَنَ الْوُضُوءَ خَرَجَتْ خَطَايَاهُ مِنْ جَسَدِهِ حَتَّى تَخْرُجَ مِنْ تَحْتِ أَظْفَارِهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('085d4545-ff38-56e8-b5d4-1c51cb854608', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '362', '‏ ‏حَدَّثَنِي ‏ ‏أَبُو كُرَيْبٍ مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏وَالْقَاسِمُ بْنُ زَكَرِيَّاءَ بْنِ دِينَارٍ ‏ ‏وَعَبْدُ بْنُ حُمَيْدٍ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ بِلَالٍ ‏ ‏حَدَّثَنِي ‏ ‏عُمَارَةُ بْنُ غَزِيَّةَ الْأَنْصَارِيُّ ‏ ‏عَنْ ‏ ‏نُعَيْمِ بْنِ عَبْدِ اللَّهِ الْمُجْمِرِ ‏ ‏قَالَ رَأَيْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَتَوَضَّأُ فَغَسَلَ وَجْهَهُ ‏ ‏فَأَسْبَغَ ‏ ‏الْوُضُوءَ ثُمَّ غَسَلَ يَدَهُ الْيُمْنَى حَتَّى ‏ ‏أَشْرَعَ ‏ ‏فِي الْعَضُدِ ثُمَّ يَدَهُ الْيُسْرَى حَتَّى ‏ ‏أَشْرَعَ ‏ ‏فِي الْعَضُدِ ثُمَّ مَسَحَ رَأْسَهُ ثُمَّ غَسَلَ رِجْلَهُ الْيُمْنَى حَتَّى ‏ ‏أَشْرَعَ ‏ ‏فِي السَّاقِ ثُمَّ غَسَلَ رِجْلَهُ الْيُسْرَى حَتَّى ‏ ‏أَشْرَعَ ‏ ‏فِي السَّاقِ ثُمَّ قَالَ هَكَذَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ وَقَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْتُمْ ‏ ‏الْغُرُّ ‏ ‏الْمُحَجَّلُونَ ‏ ‏يَوْمَ الْقِيَامَةِ مِنْ ‏ ‏إِسْبَاغِ ‏ ‏الْوُضُوءِ فَمَنْ اسْتَطَاعَ مِنْكُمْ فَلْيُطِلْ ‏ ‏غُرَّتَهُ ‏ ‏وَتَحْجِيلَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('70b5351d-a9af-56a6-94b5-b224101896f1', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '363', '‏ ‏و حَدَّثَنِي ‏ ‏هَارُونُ بْنُ سَعِيدٍ الْأَيْلِيُّ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي هِلَالٍ ‏ ‏عَنْ ‏ ‏نُعَيْمِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّهُ رَأَى ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَتَوَضَّأُ فَغَسَلَ وَجْهَهُ وَيَدَيْهِ حَتَّى كَادَ يَبْلُغُ الْمَنْكِبَيْنِ ثُمَّ غَسَلَ رِجْلَيْهِ حَتَّى رَفَعَ إِلَى السَّاقَيْنِ ثُمَّ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ أُمَّتِي يَأْتُونَ يَوْمَ الْقِيَامَةِ ‏ ‏غُرًّا ‏ ‏مُحَجَّلِينَ ‏ ‏مِنْ أَثَرِ الْوُضُوءِ فَمَنْ اسْتَطَاعَ مِنْكُمْ أَنْ يُطِيلَ ‏ ‏غُرَّتَهُ ‏ ‏فَلْيَفْعَلْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1b8ba871-a207-5bbf-95f9-d22e619263cb', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '364', '‏ ‏حَدَّثَنَا ‏ ‏سُوَيْدُ بْنُ سَعِيدٍ ‏ ‏وَابْنُ أَبِي عُمَرَ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏مَرْوَانَ الْفَزَارِيِّ ‏ ‏قَالَ ‏ ‏ابْنُ أَبِي عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ ‏ ‏عَنْ ‏ ‏أَبِي مَالِكٍ الْأَشْجَعِيِّ سَعْدِ بْنِ طَارِقٍ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ حَوْضِي أَبْعَدُ مِنْ ‏ ‏أَيْلَةَ ‏ ‏مِنْ ‏ ‏عَدَنٍ ‏ ‏لَهُوَ أَشَدُّ بَيَاضًا مِنْ الثَّلْجِ وَأَحْلَى مِنْ الْعَسَلِ بِاللَّبَنِ وَلَآنِيَتُهُ أَكْثَرُ مِنْ عَدَدِ النُّجُومِ وَإِنِّي لَأَصُدُّ النَّاسَ عَنْهُ كَمَا يَصُدُّ الرَّجُلُ إِبِلَ النَّاسِ عَنْ حَوْضِهِ قَالُوا يَا رَسُولَ اللَّهِ أَتَعْرِفُنَا يَوْمَئِذٍ قَالَ نَعَمْ لَكُمْ سِيمَا لَيْسَتْ لِأَحَدٍ مِنْ الْأُمَمِ تَرِدُونَ عَلَيَّ ‏ ‏غُرًّا ‏ ‏مُحَجَّلِينَ ‏ ‏مِنْ أَثَرِ الْوُضُوءِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b37a5b59-d008-5b19-8781-9108bd511635', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '365', '‏ ‏و حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ ‏ ‏وَوَاصِلُ بْنُ عَبْدِ الْأَعْلَى ‏ ‏وَاللَّفْظُ ‏ ‏لِوَاصِلٍ ‏ ‏قَالَا ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِي مَالِكٍ الْأَشْجَعِيِّ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَرِدُ عَلَيَّ أُمَّتِي الْحَوْضَ وَأَنَا ‏ ‏أَذُودُ ‏ ‏النَّاسَ عَنْهُ كَمَا ‏ ‏يَذُودُ ‏ ‏الرَّجُلُ إِبِلَ الرَّجُلِ عَنْ إِبِلِهِ قَالُوا يَا نَبِيَّ اللَّهِ أَتَعْرِفُنَا قَالَ نَعَمْ لَكُمْ ‏ ‏سِيمَا ‏ ‏لَيْسَتْ لِأَحَدٍ غَيْرِكُمْ تَرِدُونَ عَلَيَّ غُرًّا ‏ ‏مُحَجَّلِينَ ‏ ‏مِنْ آثَارِ الْوُضُوءِ وَلَيُصَدَّنَّ عَنِّي طَائِفَةٌ مِنْكُمْ فَلَا يَصِلُونَ فَأَقُولُ يَا رَبِّ هَؤُلَاءِ مِنْ أَصْحَابِي فَيُجِيبُنِي مَلَكٌ فَيَقُولُ وَهَلْ تَدْرِي مَا أَحْدَثُوا بَعْدَكَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5dbc9af7-7490-596a-8fa3-23af4b7c2472', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '366', '‏ ‏و حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ طَارِقٍ ‏ ‏عَنْ ‏ ‏رِبْعِىِّ بْنِ حِرَاشٍ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ حَوْضِي لَأَبْعَدُ مِنْ ‏ ‏أَيْلَةَ ‏ ‏مِنْ ‏ ‏عَدَنٍ ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ إِنِّي ‏ ‏لَأَذُودُ ‏ ‏عَنْهُ الرِّجَالَ كَمَا ‏ ‏يَذُودُ ‏ ‏الرَّجُلُ الْإِبِلَ الْغَرِيبَةَ عَنْ حَوْضِهِ قَالُوا يَا رَسُولَ اللَّهِ وَتَعْرِفُنَا قَالَ نَعَمْ تَرِدُونَ عَلَيَّ ‏ ‏غُرًّا ‏ ‏مُحَجَّلِينَ ‏ ‏مِنْ آثَارِ الْوُضُوءِ لَيْسَتْ لِأَحَدٍ غَيْرِكُمْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
